    /// Opens the database file at `path`, becoming its sole owner for the
    /// lifetime of the returned handle. A second open of the same path — this
    /// process or another — returns [`Error::DatabaseLocked`]; see the "Store
    /// ownership and concurrency" section on [`Database`]. Use
    /// [`Database::open_memory`] for an ephemeral instance.
    pub fn open(path: impl AsRef<Path>) -> Result<Self> {
        Self::open_with_config(
            path,
            Arc::new(CorePlugin),
            Arc::new(MemoryAccountant::no_limit()),
        )
    }

    /// Force-recreate a file-backed store while owning its normal open lock
    /// for the complete destructive operation. A live owner is reported as
    /// `DatabaseLocked` before either the database or its coordination lock is
    /// changed; after the owner exits the same operation creates a fresh,
    /// current-format root.
    pub fn force_reset(path: impl AsRef<Path>) -> Result<()> {
        let canonical_path = canonical_database_path(path.as_ref())?;
        let registry_reservation = OpenRegistryReservation::acquire(canonical_path.clone())?;
        let persistence = RedbPersistence::recreate(&canonical_path)?;
        persistence.close();
        drop(registry_reservation);
        Ok(())
    }

    pub fn open_memory() -> Self {
        Self::open_memory_with_plugin_and_accountant(
            Arc::new(CorePlugin),
            Arc::new(MemoryAccountant::no_limit()),
        )
        .expect("failed to open in-memory database")
    }

    /// The durable fabric identity kept beside this database, when this
    /// instance owns a file-backed store. This stays crate-private so callers
    /// cannot use the database as a general persistence-path discovery API.
    pub(crate) fn sync_identity_path(&self) -> Option<PathBuf> {
        let persistence = self.persistence.as_ref()?;
        let mut file_name = persistence.path().file_name()?.to_os_string();
        file_name.push(".fabric-identity.key");
        Some(persistence.path().with_file_name(file_name))
    }

    /// Internal media adapter attachment. The returned repository is the
    /// same engine-owned instance shared by scoped database handles.
    #[doc(hidden)]
    pub(crate) fn blob_repository(&self) -> Arc<BlobRepository> {
        let _operation = self.assert_open_operation();
        self.blob_repository.clone()
    }

    #[cfg(feature = "test-seams")]
    #[doc(hidden)]
    pub fn wait_until_authoritative_purge_waits_for_blob_hash_for_test(
        &self,
        hash: &[u8; 32],
        timeout: Duration,
    ) -> bool {
        let _operation = self.assert_open_operation();
        self.blob_repository
            .wait_until_authoritative_purge_waits_for_hash_for_test(hash, timeout)
    }

    pub fn open_with_contexts<P: AsRef<Path>>(
        path: P,
        contexts: std::collections::BTreeSet<contextdb_core::types::ContextId>,
    ) -> Result<Self> {
        Self::open_with_constraints(path, Some(contexts), None, None)
    }

    pub fn open_memory_with_contexts(
        contexts: std::collections::BTreeSet<contextdb_core::types::ContextId>,
    ) -> Self {
        Self::open_memory_with_constraints(Some(contexts), None, None)
    }

    pub fn open_with_scope_labels<P: AsRef<Path>>(
        path: P,
        labels: std::collections::BTreeSet<contextdb_core::types::ScopeLabel>,
    ) -> Result<Self> {
        Self::open_with_constraints(path, None, Some(labels), None)
    }

    pub fn open_memory_with_scope_labels(
        labels: std::collections::BTreeSet<contextdb_core::types::ScopeLabel>,
    ) -> Self {
        Self::open_memory_with_constraints(None, Some(labels), None)
    }

    pub fn open_as_principal<P: AsRef<Path>>(
        path: P,
        principal: contextdb_core::types::Principal,
    ) -> Result<Self> {
        Self::open_with_constraints(path, None, None, Some(principal))
    }

    pub fn open_memory_as_principal(principal: contextdb_core::types::Principal) -> Self {
        Self::open_memory_with_constraints(None, None, Some(principal))
    }

    pub fn open_with_constraints<P: AsRef<Path>>(
        path: P,
        contexts: Option<std::collections::BTreeSet<contextdb_core::types::ContextId>>,
        scope_labels: Option<std::collections::BTreeSet<contextdb_core::types::ScopeLabel>>,
        principal: Option<contextdb_core::types::Principal>,
    ) -> Result<Self> {
        let access = AccessConstraints {
            contexts,
            scope_labels,
            principal,
        };
        let path = path.as_ref();
        let db = if path.as_os_str() == ":memory:" {
            Self::open_memory_internal(
                Arc::new(CorePlugin),
                Arc::new(MemoryAccountant::no_limit()),
            )?
        } else {
            let db = Self::open_loaded(
                path,
                Arc::new(CorePlugin),
                Arc::new(MemoryAccountant::no_limit()),
                None,
                false,
            )?;
            db.plugin.on_open()?;
            db
        };
        let db = db.with_access_constraints(access);
        db.start_cron_tickler_if_schedules_present();
        db.load_retention_sync_peer();
        db.reconcile_maintenance_thread();
        Ok(db)
    }

    pub fn open_memory_with_constraints(
        contexts: Option<std::collections::BTreeSet<contextdb_core::types::ContextId>>,
        scope_labels: Option<std::collections::BTreeSet<contextdb_core::types::ScopeLabel>>,
        principal: Option<contextdb_core::types::Principal>,
    ) -> Self {
        Self::open_memory().with_access_constraints(AccessConstraints {
            contexts,
            scope_labels,
            principal,
        })
    }

    fn with_access_constraints(mut self, access: AccessConstraints) -> Self {
        self.access = access;
        self
    }

    pub fn scoped_with_contexts(
        &self,
        contexts: std::collections::BTreeSet<contextdb_core::types::ContextId>,
    ) -> Self {
        self.scoped_with_constraints(Some(contexts), None, None)
    }

    pub fn scoped_with_constraints(
        &self,
        contexts: Option<std::collections::BTreeSet<contextdb_core::types::ContextId>>,
        scope_labels: Option<std::collections::BTreeSet<contextdb_core::types::ScopeLabel>>,
        principal: Option<contextdb_core::types::Principal>,
    ) -> Self {
        let contexts = narrowed_constraint_set(&self.access.contexts, contexts);
        let scope_labels = narrowed_constraint_set(&self.access.scope_labels, scope_labels);
        let principal = self.access.principal.clone().or(principal);
        Self {
            tx_mgr: self.tx_mgr.clone(),
            relational_store: self.relational_store.clone(),
            graph_store: self.graph_store.clone(),
            vector_store: self.vector_store.clone(),
            vector_schema_gates: self.vector_schema_gates.clone(),
            change_log: self.change_log.clone(),
            change_log_table_index: self.change_log_table_index.clone(),
            change_log_lsn_refcounts: self.change_log_lsn_refcounts.clone(),
            ddl_log: self.ddl_log.clone(),
            sync_tombstone_arrivals: self.sync_tombstone_arrivals.clone(),
            sync_graph_arrivals: self.sync_graph_arrivals.clone(),
            terminal_refusal_markers: self.terminal_refusal_markers.clone(),
            terminal_refusal_scans: self.terminal_refusal_scans.clone(),
            accepted_sync_row_authors: self.accepted_sync_row_authors.clone(),
            received_schema_stages: self.received_schema_stages.clone(),
            pending_local_schema_stages: self.pending_local_schema_stages.clone(),
            local_schema_stages: self.local_schema_stages.clone(),
            capture_detached_sync_write_set: self.capture_detached_sync_write_set.clone(),
            detached_sync_write_set: self.detached_sync_write_set.clone(),
            persistence: self.persistence.clone(),
            blob_repository: self.blob_repository.clone(),
            open_registry_path: Mutex::new(None),
            operation_gate: self.operation_gate.clone(),
            schema_publication_gate: self.schema_publication_gate.clone(),
            apply_phase_pause: self.apply_phase_pause.clone(),
            sync_apply_pre_commit_pause: self.sync_apply_pre_commit_pause.clone(),
            export_after_capture_pause: self.export_after_capture_pause.clone(),
            relational: MemRelationalExecutor::new(
                self.relational_store.clone(),
                self.tx_mgr.clone(),
            ),
            graph: MemGraphExecutor::new(self.graph_store.clone(), self.tx_mgr.clone()),
            vector: MemVectorExecutor::new_with_accountant(
                self.vector_store.clone(),
                self.tx_mgr.clone(),
                Arc::new(OnceLock::new()),
                self.accountant.clone(),
            ),
            session_tx: Mutex::new(None),
            instance_id: uuid::Uuid::new_v4(),
            owner_thread: thread::current().id(),
            plugin: self.plugin.clone(),
            access: AccessConstraints {
                contexts,
                scope_labels,
                principal,
            },
            accountant: self.accountant.clone(),
            conflict_policies: RwLock::new(self.conflict_policies.read().clone()),
            subscriptions: self.subscriptions.clone(),
            pruning_runtime: Mutex::new(PruningRuntime::new()),
            pruning_guard: self.pruning_guard.clone(),
            retention_sync_peer: self.retention_sync_peer.clone(),
            in_memory_destination_reuploads: self.in_memory_destination_reuploads.clone(),
            lineage_state_lock: self.lineage_state_lock.clone(),
            received_schema_manifest_lock: self.received_schema_manifest_lock.clone(),
            in_memory_received_schema_manifests: self.in_memory_received_schema_manifests.clone(),
            in_memory_table_generations: self.in_memory_table_generations.clone(),
            in_memory_ddl_generations: self.in_memory_ddl_generations.clone(),
            received_ddl_arrivals: self.received_ddl_arrivals.clone(),
            superseded_ddl_occurrences: self.superseded_ddl_occurrences.clone(),
            cron: self.cron.clone(),
            event_bus: self.event_bus.clone(),
            trigger: self.trigger.clone(),
            sync_relay_mode: self.sync_relay_mode.clone(),
            in_memory_sync_progress: self.in_memory_sync_progress.clone(),
            in_memory_applied_push_watermarks: self.in_memory_applied_push_watermarks.clone(),
            sync_incarnations: self.sync_incarnations.clone(),
            pending_event_bus_ddl: Mutex::new(HashMap::new()),
            pending_commit_metadata: Mutex::new(HashMap::new()),
            limit_update_lock: self.limit_update_lock.clone(),
            disk_limit: AtomicU64::new(self.disk_limit.load(Ordering::SeqCst)),
            disk_limit_startup_ceiling: AtomicU64::new(
                self.disk_limit_startup_ceiling.load(Ordering::SeqCst),
            ),
            trigger_audit_retention_secs: self.trigger_audit_retention_secs.clone(),
            snapshot_registry: self.snapshot_registry.clone(),
            maintenance_caller_driven: self.maintenance_caller_driven.clone(),
            last_maintenance_cycle_at: self.last_maintenance_cycle_at.clone(),
            caller_driven_backlog_warned_at: self.caller_driven_backlog_warned_at.clone(),
            last_auto_compact_at: self.last_auto_compact_at.clone(),
            auto_compact_min_interval: self.auto_compact_min_interval.clone(),
            sync_watermark: self.sync_watermark.clone(),
            closed: AtomicBool::new(false),
            resource_closed: self.resource_closed.clone(),
            rows_examined: AtomicU64::new(0),
            last_vector_search_used_hnsw: AtomicBool::new(false),
            last_vector_search_trace: RwLock::new(None),
            statement_cache: RwLock::new(HashMap::new()),
            rank_formula_cache: RwLock::new(HashMap::new()),
            acl_grant_cache: RwLock::new(HashMap::new()),
            rank_policy_eval_count: AtomicU64::new(0),
            rank_policy_formula_parse_count: AtomicU64::new(0),
            fk_indexed_tuple_probes: AtomicU64::new(0),
            fk_full_scan_fallbacks: AtomicU64::new(0),
            commit_rows_validated: AtomicU64::new(0),
            commit_indexed_probes: AtomicU64::new(0),
            commit_staged_vs_staged_comparisons: AtomicU64::new(0),
            commit_scan_rows_touched: AtomicU64::new(0),
            commit_index_maintenance_visits: AtomicU64::new(0),
            #[cfg(feature = "test-seams")]
            commit_stage_wall_nanos: std::array::from_fn(|_| AtomicU64::new(0)),
            corrupt_joined_values: RwLock::new(HashSet::new()),
            resource_owner: false,
        }
    }
    fn open_loaded(
        path: impl AsRef<Path>,
        plugin: Arc<dyn DatabasePlugin>,
        mut accountant: Arc<MemoryAccountant>,
        startup_disk_limit: Option<u64>,
        allow_legacy_table_meta_layout: bool,
    ) -> Result<Self> {
        let canonical_path = canonical_database_path(path.as_ref())?;
        let (registry_reservation, persistence) =
            acquire_registry_and_persistence(&canonical_path)?;
        if let Some(persisted) = persistence.load_config_value::<usize>("memory_limit")? {
            let startup = accountant.usage();
            if let Some(ceiling) = startup.startup_ceiling {
                accountant.set_budget(Some(persisted.min(ceiling)))?;
            } else if startup.limit.is_none() {
                accountant = Arc::new(MemoryAccountant::with_runtime_budget(persisted));
            }
        }
        let persisted_disk_limit = persistence.load_config_value::<u64>("disk_limit")?;
        let startup_disk_ceiling = startup_disk_limit;
        let effective_disk_limit = match (persisted_disk_limit, startup_disk_limit) {
            (Some(persisted), Some(ceiling)) => Some(persisted.min(ceiling)),
            (Some(persisted), None) => Some(persisted),
            (None, Some(ceiling)) => Some(ceiling),
            (None, None) => None,
        };

        let all_meta = persistence.load_all_table_meta()?;
        // A table whose meta only decoded via the pre-`contextdb migrate`
        // v1.0.0 layout (fewer `TableMeta`/`ColumnDef` fields than today)
        // means this WHOLE root predates the current schema layout — refuse
        // loudly here rather than silently loading it, UNLESS the caller is
        // the migrate command itself (`Database::open_legacy_for_migration`),
        // which exists specifically to read past this refusal.
        if !allow_legacy_table_meta_layout && persistence.used_legacy_table_meta_layout() {
            return Err(Error::LegacyVectorStoreDetected {
                found_format_marker: format!(
                    "{} (legacy table/column schema layout)",
                    crate::persistence::CURRENT_FORMAT_VERSION
                ),
                expected_release: crate::persistence::CURRENT_FORMAT_VERSION.to_string(),
            });
        }

        let relational = Arc::new(RelationalStore::new());
        let mut sanitized_row_tables = HashSet::new();
        for (name, meta) in &all_meta {
            let mut runtime_meta = meta.clone();
            let user_indexes = runtime_meta
                .indexes
                .iter()
                .filter(|index| index.kind == IndexKind::UserDeclared)
                .cloned()
                .collect::<Vec<_>>();
            runtime_meta.indexes = crate::executor::auto_indexes_for_table_meta(&runtime_meta);
            runtime_meta.indexes.extend(user_indexes);
            relational.create_table(name, runtime_meta.clone());
            // Register EVERY index declared in TableMeta.indexes — this
            // includes auto-indexes (kind=Auto) synthesized at CREATE TABLE
            // time AND user-declared indexes (kind=UserDeclared).
            for decl in &runtime_meta.indexes {
                if decl.kind == IndexKind::Auto {
                    relational.create_exact_index_storage(name, &decl.name, decl.columns.clone());
                } else {
                    relational.create_index_storage(name, &decl.name, decl.columns.clone());
                }
            }
            for mut row in persistence.load_relational_table(name)? {
                if sanitize_loaded_row_for_meta(&mut row, &runtime_meta) {
                    sanitized_row_tables.insert(name.clone());
                }
                relational.insert_loaded_row(name, row);
            }
        }
        let loaded_row_ids = relational
            .tables
            .read()
            .iter()
            .map(|(table, rows)| {
                (
                    table.clone(),
                    rows.iter()
                        .filter(|row| row.deleted_tx.is_none())
                        .map(|row| row.row_id)
                        .collect::<HashSet<_>>(),
                )
            })
            .collect::<HashMap<_, _>>();
        let sync_source_lsns: HashMap<(String, RowId), Lsn> = persistence
            .load_sync_source_lsns()?
            .into_iter()
            .filter(|((table, row_id), _)| {
                loaded_row_ids
                    .get(table)
                    .is_some_and(|row_ids| row_ids.contains(row_id))
            })
            .collect();
        let mut sync_source_kinds = persistence
            .load_sync_source_kinds()?
            .into_iter()
            .filter_map(|((table, row_id), kind)| {
                (loaded_row_ids
                    .get(&table)
                    .is_some_and(|rows| rows.contains(&row_id))
                    // A kind is a companion to an LSN, never independent
                    // provenance. Ignore roots left by an older cleanup bug
                    // rather than reclassifying a locally-authored row.
                    && sync_source_lsns.contains_key(&(table.clone(), row_id)))
                .then(|| {
                    let kind = match kind {
                        1 => contextdb_relational::store::SyncSourceKind::AcceptedLocal,
                        2 => contextdb_relational::store::SyncSourceKind::AcceptedLocalPending,
                        _ => contextdb_relational::store::SyncSourceKind::Pulled,
                    };
                    ((table, row_id), kind)
                })
            })
            .collect::<HashMap<_, _>>();
        // Roots written before the companion table existed contain only the
        // source LSN. Those entries were historically pulled/echo provenance,
        // so preserve that meaning rather than treating old remote data as
        // newly authored local work.
        for key in sync_source_lsns.keys() {
            sync_source_kinds
                .entry(key.clone())
                .or_insert(contextdb_relational::store::SyncSourceKind::Pulled);
        }
        relational.replace_sync_source_lsns(sync_source_lsns);
        relational.replace_sync_source_kinds(sync_source_kinds);

        let graph = Arc::new(GraphStore::new());
        for edge in persistence.load_forward_edges()? {
            graph.insert_loaded_edge(edge);
        }

        let hnsw = Arc::new(OnceLock::new());
        let vector = Arc::new(VectorStore::new(hnsw.clone()));
        for (table_name, meta) in &all_meta {
            for column in &meta.columns {
                if let ColumnType::Vector(dimension) = column.column_type {
                    vector.register_index(
                        VectorIndexRef::new(table_name, column.name.clone()),
                        dimension,
                        column.quantization,
                    );
                }
            }
        }
        let loaded_ddl_log = persistence.load_ddl_log()?;
        let (mut loaded_vectors, repaired_vector_refs) = reconcile_loaded_vectors_for_meta(
            persistence.load_vectors()?,
            &all_meta,
            &loaded_ddl_log,
        );
        let supplemented_vectors =
            supplement_loaded_vectors_from_rows(&relational, &all_meta, &mut loaded_vectors);
        for entry in &loaded_vectors {
            vector.insert_loaded_vector(entry.clone());
        }

        let loaded_change_log = persistence.load_change_log()?;
        let mut commit_index = persistence.load_commit_index()?;
        let reconstructed_commit_index =
            commit_index_across_all(&relational, &graph, &vector, &loaded_change_log);
        let mut missing_commit_index = BTreeMap::new();
        for (lsn, tx) in reconstructed_commit_index {
            if let std::collections::btree_map::Entry::Vacant(slot) = commit_index.entry(lsn) {
                slot.insert(tx);
                missing_commit_index.insert(lsn, tx);
            }
        }
        let repaired_visibility_order = repair_visibility_tx_order_if_needed(
            &relational,
            &graph,
            &vector,
            loaded_vectors.as_mut_slice(),
            &all_meta,
            &persistence,
            &mut commit_index,
        )?;
        if repaired_visibility_order {
            persistence.rewrite_commit_index(&commit_index)?;
        } else if !missing_commit_index.is_empty() {
            persistence.flush_commit_index_entries(&missing_commit_index)?;
        }
        let hydrated_row_tables = hydrate_relational_vector_values(&relational, &loaded_vectors);
        if repaired_vector_refs || supplemented_vectors {
            persistence.rewrite_vectors(&loaded_vectors)?;
        }
        for table in sanitized_row_tables
            .into_iter()
            .chain(hydrated_row_tables.into_iter())
            .collect::<HashSet<_>>()
        {
            if let Some(rows) = relational.tables.read().get(&table) {
                persistence.rewrite_table_rows(&table, rows)?;
            }
        }

        let max_row_id = relational.max_row_id();
        let max_tx = max_tx_across_all(&relational, &graph, &vector);
        let commit_index_max_lsn = commit_index.keys().next_back().copied().unwrap_or(Lsn(0));
        let ddl_max_lsn = loaded_ddl_log
            .iter()
            .map(|(lsn, _)| *lsn)
            .max()
            .unwrap_or(Lsn(0));
        let purge_frontier_max_lsn = persistence
            .load_config_values_with_prefix::<DurableLineageRecord>(
                Self::DURABLE_LINEAGE_CONFIG_PREFIX,
            )?
            .into_iter()
            .try_fold(Lsn(0), |maximum, (key, record)| {
                let expected_key = Self::durable_lineage_config_key(
                    &record.table,
                    &record.natural_key,
                    record.table_generation,
                );
                if key != expected_key {
                    return Err(Error::SyncError(
                        "durable lineage lifecycle key disagrees with its canonical record"
                            .to_string(),
                    ));
                }
                match (record.delete_obligation, record.purge_frontier.as_deref()) {
                    (DurableDeleteObligation::Purged, Some(frontier)) => {
                        let frontier = frontier.parse::<u64>().map_err(|_| {
                            Error::SyncError(
                                "durable lineage purge frontier is not a valid LSN".to_string(),
                            )
                        })?;
                        Ok(maximum.max(Lsn(frontier)))
                    }
                    (DurableDeleteObligation::Purged, None) => Err(Error::SyncError(
                        "durable purged lineage is missing its permanent frontier".to_string(),
                    )),
                    (_, Some(_)) => Err(Error::SyncError(
                        "non-purged durable lineage carries a purge frontier".to_string(),
                    )),
                    (_, None) => Ok(maximum),
                }
            })?;
        let max_lsn = max_lsn_across_all(&relational, &graph, &vector)
            .max(commit_index_max_lsn)
            .max(ddl_max_lsn)
            .max(purge_frontier_max_lsn);
        relational.set_next_row_id(RowId(max_row_id.0.saturating_add(1)));

        let (initial_table_index, initial_lsn_refcounts) =
            build_change_log_aux_indexes(&loaded_change_log);
        let change_log = Arc::new(RwLock::new(loaded_change_log));
        let change_log_table_index = Arc::new(RwLock::new(initial_table_index));
        let change_log_lsn_refcounts = Arc::new(RwLock::new(initial_lsn_refcounts));
        let ddl_log = Arc::new(RwLock::new(loaded_ddl_log));
        let received_schema_stages = Arc::new(Mutex::new(HashMap::new()));
        let pending_local_schema_stages = Arc::new(Mutex::new(HashMap::new()));
        let local_schema_stages = Arc::new(Mutex::new(HashMap::new()));
        let apply_phase_pause = Arc::new(ApplyPhasePause::new());
        let composite = CompositeStore::new_with_apply_phase_pause(
            relational.clone(),
            graph.clone(),
            vector.clone(),
            change_log.clone(),
            change_log_table_index.clone(),
            change_log_lsn_refcounts.clone(),
            ddl_log.clone(),
            accountant.clone(),
            apply_phase_pause.clone(),
        );
        let event_bus = Arc::new(EventBusState::new());
        let trigger = Arc::new(TriggerState::new());
        let persistent = PersistentCompositeStore::new(
            composite,
            persistence.clone(),
            Some(event_bus.clone()),
            Some(trigger.clone()),
            received_schema_stages.clone(),
            local_schema_stages.clone(),
        );
        let store: DynStore = Box::new(persistent);
        let tx_mgr = Arc::new(TransactionManager::new_with_counters_and_commit_index(
            store,
            TxId(max_tx.0.saturating_add(1)),
            Lsn(max_lsn.0.saturating_add(1)),
            max_tx,
            commit_index,
        ));
        let blob_repository = BlobRepository::shared(persistence.clone());

        let db = Self::build_db(
            tx_mgr,
            relational,
            graph,
            vector,
            hnsw,
            change_log,
            change_log_table_index,
            change_log_lsn_refcounts,
            ddl_log,
            received_schema_stages,
            pending_local_schema_stages,
            local_schema_stages,
            Some(persistence),
            blob_repository,
            Some(registry_reservation.disarm()),
            apply_phase_pause,
            plugin,
            accountant,
            effective_disk_limit,
            startup_disk_ceiling,
            event_bus,
            trigger,
        );

        db.load_received_ddl_arrivals_from_persistence()?;
        db.load_superseded_ddl_occurrences_from_persistence()?;
        db.load_graph_arrivals_from_persistence()?;

        for meta in all_meta.values() {
            if !meta.dag_edge_types.is_empty() {
                db.graph.register_dag_edge_types(&meta.dag_edge_types);
            }
        }
        db.rebuild_rank_formula_cache_from_meta(&all_meta)?;

        db.account_loaded_state()?;
        maybe_prebuild_hnsw(&db.vector_store, db.accountant());
        db.load_cron_state_from_persistence()?;
        db.load_event_bus_state_from_persistence()?;
        db.load_trigger_state_from_persistence()?;

        Ok(db)
    }

    fn open_memory_internal(
        plugin: Arc<dyn DatabasePlugin>,
        accountant: Arc<MemoryAccountant>,
    ) -> Result<Self> {
        let relational = Arc::new(RelationalStore::new());
        let graph = Arc::new(GraphStore::new());
        let hnsw = Arc::new(OnceLock::new());
        let vector = Arc::new(VectorStore::new(hnsw.clone()));
        let change_log = Arc::new(RwLock::new(Vec::new()));
        let change_log_table_index = Arc::new(RwLock::new(ChangeLogTableIndex::new()));
        let change_log_lsn_refcounts = Arc::new(RwLock::new(ChangeLogLsnRefcounts::new()));
        let ddl_log = Arc::new(RwLock::new(Vec::new()));
        let received_schema_stages = Arc::new(Mutex::new(HashMap::new()));
        let pending_local_schema_stages = Arc::new(Mutex::new(HashMap::new()));
        let local_schema_stages = Arc::new(Mutex::new(HashMap::new()));
        let apply_phase_pause = Arc::new(ApplyPhasePause::new());
        let trigger = Arc::new(TriggerState::new());
        let store: DynStore = Box::new(CompositeStore::new_with_apply_phase_pause(
            relational.clone(),
            graph.clone(),
            vector.clone(),
            change_log.clone(),
            change_log_table_index.clone(),
            change_log_lsn_refcounts.clone(),
            ddl_log.clone(),
            accountant.clone(),
            apply_phase_pause.clone(),
        ));
        let tx_mgr = Arc::new(TransactionManager::new(store));
        let event_bus = Arc::new(EventBusState::new());
        let blob_repository = BlobRepository::ephemeral()?;

        let db = Self::build_db(
            tx_mgr,
            relational,
            graph,
            vector,
            hnsw,
            change_log,
            change_log_table_index,
            change_log_lsn_refcounts,
            ddl_log,
            received_schema_stages,
            pending_local_schema_stages,
            local_schema_stages,
            None,
            blob_repository,
            None,
            apply_phase_pause,
            plugin,
            accountant,
            None,
            None,
            event_bus,
            trigger,
        );
        maybe_prebuild_hnsw(&db.vector_store, db.accountant());
        Ok(db)
    }

    pub fn begin(&self) -> Result<TxId> {
        let _operation = self.open_operation_after_public_tx_control_wait("begin")?;
        Ok(self.tx_mgr.begin())
    }

    fn callback_active_process_wide() -> bool {
        global_callback_active_count().load(Ordering::SeqCst) > 0
    }

    fn trigger_deadlock_timeout() -> Duration {
        std::env::var("CONTEXTDB_TRIGGER_DEADLOCK_TIMEOUT_MS")
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .map(Duration::from_millis)
            .unwrap_or(DEFAULT_TRIGGER_DEADLOCK_TIMEOUT)
    }

    fn open_operation_after_public_tx_control_wait(
        &self,
        surface: &'static str,
    ) -> Result<DatabaseOperationGuard<'_>> {
        self.open_operation_after_public_tx_control_wait_for_tx(surface, None)
    }

    fn open_operation_after_public_tx_control_wait_for_tx(
        &self,
        surface: &'static str,
        tx: Option<TxId>,
    ) -> Result<DatabaseOperationGuard<'_>> {
        let operation = self.open_operation()?;
        if !Self::callback_active_process_wide() {
            return Ok(operation);
        }
        drop(operation);
        self.assert_callback_reentry_allowed()?;
        if let Some(tx) = tx {
            self.assert_trigger_callback_tx_not_captured_cross_thread(tx)?;
        }
        self.assert_public_tx_control_cross_thread_allowed_for_surface(surface)?;
        self.open_operation()
    }

    fn assert_callback_reentry_allowed(&self) -> Result<()> {
        if CRON_CALLBACK_ACTIVE.with(|active| active.get()) {
            return Err(Error::CallbackReentry {
                kind: CallbackKind::Cron,
            });
        }
        if TRIGGER_CALLBACK_ACTIVE.with(|active| active.get()) {
            self.record_user_commit_trigger_reentry();
            return Err(Error::CallbackReentry {
                kind: CallbackKind::Trigger,
            });
        }
        Ok(())
    }

    fn assert_public_tx_control_cross_thread_allowed_for_surface(
        &self,
        surface: &'static str,
    ) -> Result<()> {
        if self.cron.callback_active_on_other_thread() {
            return Err(Error::CallbackActiveCrossThread {
                kind: CallbackKind::Cron,
            });
        }
        match self
            .trigger
            .callback_contention_for_tx_control(self.owner_thread, self.cron.has_schedules())
        {
            TriggerContention::None => Ok(()),
            TriggerContention::SameDb => self.wait_for_same_db_trigger_callback_idle(surface),
        }
    }

    fn wait_for_same_db_trigger_callback_idle(&self, surface: &'static str) -> Result<()> {
        let timeout = Self::trigger_deadlock_timeout();
        let started = Instant::now();
        let mut observed_wait = false;
        let mut guard = self.trigger.wait_lock.lock();
        loop {
            if self.closed.load(Ordering::SeqCst) {
                return Err(closed_database_error());
            }
            self.assert_callback_reentry_allowed()?;
            match self
                .trigger
                .callback_contention_for_tx_control(self.owner_thread, self.cron.has_schedules())
            {
                TriggerContention::None => {
                    if surface != "close"
                        && self.trigger.close_waiter_count.load(Ordering::SeqCst) > 0
                    {
                        let _ = self
                            .trigger
                            .waiters
                            .wait_for(&mut guard, Duration::from_millis(1));
                        continue;
                    }
                    return Ok(());
                }
                TriggerContention::SameDb => {
                    if !observed_wait {
                        self.trigger
                            .wait_observed_count
                            .fetch_add(1, Ordering::SeqCst);
                        observed_wait = true;
                    }
                }
            }

            let elapsed = started.elapsed();
            if elapsed >= timeout {
                return Err(self.trigger_same_db_deadlock_timeout_error(surface, elapsed));
            }
            let remaining = timeout.saturating_sub(elapsed);
            self.trigger.waiters.wait_for(&mut guard, remaining);
        }
    }

    fn trigger_same_db_deadlock_timeout_error(
        &self,
        surface: &'static str,
        waited: Duration,
    ) -> Error {
        self.trigger
            .deadlock_guard_timeout_observed_count
            .fetch_add(1, Ordering::SeqCst);
        self.trigger
            .typed_err_observed_same_db_count
            .fetch_add(1, Ordering::SeqCst);
        let trigger_name = self.trigger.active_trigger_name_for_wait();
        let waited_ms = waited.as_millis() as u64;
        tracing::warn!(
            trigger = %trigger_name,
            trigger_name = %trigger_name,
            waited_ms = waited_ms,
            surface = surface,
            "trigger callback wait exceeded deadlock guard"
        );
        Error::CallbackActiveCrossThread {
            kind: CallbackKind::Trigger,
        }
    }

    // Internal engine-managed writes still need callback-active gates, and
    // trigger contention stays scoped to this database so independent embedded
    // handles do not poison each other through process-wide state.
    fn begin_for_internal_write(&self) -> Result<TxId> {
        let _operation = self.open_operation()?;
        self.assert_internal_write_callbacks_allowed()?;
        Ok(self.tx_mgr.begin())
    }

    fn begin_for_public_autocommit_write(&self) -> Result<TxId> {
        let _operation = self.open_operation_after_internal_write_wait("execute")?;
        Ok(self.tx_mgr.begin())
    }

    fn rollback_preopened_autocommit_tx(&self, tx: Option<TxId>) {
        if let Some(tx) = tx {
            let _ = self.tx_mgr.rollback_empty_without_commit_lock(tx);
        }
    }

    fn enter_sql_write_control_bypass(&self, tx: TxId) -> SqlWriteControlBypassGuard {
        let db_id = self as *const Self as usize;
        SQL_WRITE_CONTROL_BYPASS_STACK.with(|stack| {
            stack.borrow_mut().push((db_id, tx));
        });
        SqlWriteControlBypassGuard { db_id, tx }
    }

    fn sql_write_control_bypass_active(&self, tx: TxId) -> bool {
        let db_id = self as *const Self as usize;
        SQL_WRITE_CONTROL_BYPASS_STACK.with(|stack| stack.borrow().contains(&(db_id, tx)))
    }

    fn assert_internal_write_callbacks_allowed(&self) -> Result<()> {
        if !Self::callback_active_process_wide() {
            return Ok(());
        }
        self.assert_callback_reentry_allowed()?;
        if self.cron.callback_active_on_other_thread() {
            return Err(Error::CallbackActiveCrossThread {
                kind: CallbackKind::Cron,
            });
        }
        if self
            .trigger
            .callback_active_on_other_thread(self.owner_thread)
        {
            return Err(Error::CallbackActiveCrossThread {
                kind: CallbackKind::Trigger,
            });
        }
        Ok(())
    }

    fn open_operation_after_internal_write_wait(
        &self,
        surface: &'static str,
    ) -> Result<DatabaseOperationGuard<'_>> {
        let operation = self.open_operation()?;
        if !Self::callback_active_process_wide() {
            return Ok(operation);
        }
        drop(operation);
        self.assert_callback_reentry_allowed()?;
        self.assert_internal_write_cross_thread_allowed(surface)?;
        self.open_operation()
    }

    fn cron_callback_tx_bound_matches(&self, tx: TxId) -> bool {
        let cron_tx = CRON_CALLBACK_TX.with(|slot| slot.get());
        let cron_db = CRON_CALLBACK_DB.with(|slot| slot.get());
        cron_tx == Some(tx) && cron_db == Some(self as *const Self as usize)
    }

    pub(crate) fn trigger_callback_tx_bound_matches(&self, tx: TxId) -> bool {
        let trigger_tx = TRIGGER_CALLBACK_TX.with(|slot| slot.get());
        let trigger_db = TRIGGER_CALLBACK_DB.with(|slot| slot.get());
        trigger_tx == Some(tx) && trigger_db == Some(self as *const Self as usize)
    }

    pub(crate) fn trigger_callback_wallclock(&self) -> Wallclock {
        TRIGGER_CALLBACK_WALLCLOCK
            .with(|slot| slot.get())
            .unwrap_or_else(current_wallclock)
    }

    fn callback_tx_bound_matches(&self, tx: TxId) -> bool {
        self.cron_callback_tx_bound_matches(tx) || self.trigger_callback_tx_bound_matches(tx)
    }

    pub(super) fn vector_schema_gate_id(&self) -> usize {
        Arc::as_ptr(&self.vector_schema_gates) as usize
    }

    fn callback_active_on_current_thread_for_this_db(&self) -> bool {
        let gate_id = self.vector_schema_gate_id();
        (CRON_CALLBACK_ACTIVE.with(|active| active.get())
            && CRON_CALLBACK_VECTOR_SCHEMA_GATE.with(|slot| slot.get()) == Some(gate_id))
            || (TRIGGER_CALLBACK_ACTIVE.with(|active| active.get())
                && TRIGGER_CALLBACK_VECTOR_SCHEMA_GATE.with(|slot| slot.get()) == Some(gate_id))
    }

    fn assert_callback_tx_bound_write_allowed(&self, tx: TxId) -> Result<()> {
        if CRON_CALLBACK_ACTIVE.with(|active| active.get())
            && !self.cron_callback_tx_bound_matches(tx)
        {
            return Err(Error::CallbackReentry {
                kind: CallbackKind::Cron,
            });
        }
        if TRIGGER_CALLBACK_ACTIVE.with(|active| active.get())
            && !self.trigger_callback_tx_bound_matches(tx)
        {
            self.record_user_commit_trigger_reentry();
            return Err(Error::CallbackReentry {
                kind: CallbackKind::Trigger,
            });
        }
        Ok(())
    }

    fn assert_trigger_callback_tx_not_captured_cross_thread(&self, tx: TxId) -> Result<()> {
        if self.trigger.callback_tx_active(tx) && !self.trigger_callback_tx_bound_matches(tx) {
            return Err(Error::CallbackActiveCrossThread {
                kind: CallbackKind::Trigger,
            });
        }
        Ok(())
    }

    fn open_operation_after_write_control_wait(
        &self,
        tx: TxId,
        surface: &'static str,
    ) -> Result<DatabaseOperationGuard<'_>> {
        let operation = self.open_operation()?;
        if self.sql_write_control_bypass_active(tx)
            || !Self::callback_active_process_wide()
            || self.callback_tx_bound_matches(tx)
        {
            return Ok(operation);
        }
        drop(operation);
        self.assert_callback_tx_bound_write_allowed(tx)?;
        self.assert_trigger_callback_tx_not_captured_cross_thread(tx)?;
        self.assert_write_control_cross_thread_allowed_for_surface(surface)?;
        self.open_operation()
    }

    fn open_operation_after_statement_callback_wait(
        &self,
        stmt: &Statement,
        surface: &'static str,
    ) -> Result<DatabaseOperationGuard<'_>> {
        let operation = self.open_operation()?;
        if !Self::callback_active_process_wide() {
            return Ok(operation);
        }
        drop(operation);
        self.assert_statement_allowed_for_callbacks_for_surface(stmt, surface)?;
        self.open_operation()
    }

    fn assert_write_control_cross_thread_allowed_for_surface(
        &self,
        surface: &'static str,
    ) -> Result<()> {
        if self.cron.callback_active_on_other_thread() {
            return Err(Error::CallbackActiveCrossThread {
                kind: CallbackKind::Cron,
            });
        }
        match self
            .trigger
            .callback_contention_for_tx_control(self.owner_thread, self.cron.has_schedules())
        {
            TriggerContention::None => Ok(()),
            TriggerContention::SameDb => self.wait_for_same_db_trigger_callback_idle(surface),
        }
    }

    fn assert_internal_write_cross_thread_allowed(&self, surface: &'static str) -> Result<()> {
        if self.cron.callback_active_on_other_thread() {
            return Err(Error::CallbackActiveCrossThread {
                kind: CallbackKind::Cron,
            });
        }
        match self
            .trigger
            .callback_contention_for_tx_control(self.owner_thread, self.cron.has_schedules())
        {
            TriggerContention::None => Ok(()),
            TriggerContention::SameDb => self.wait_for_same_db_trigger_callback_idle(surface),
        }
    }

    /// Test/example helper. Production code MUST use `?` propagation against
    /// the typed callback-active errors. Unwraps the engine's
    /// `CallbackActiveCrossThread` / `CallbackReentry` variants as panics; not
    /// appropriate for code that may run alongside trigger or cron callbacks.
    pub fn begin_or_panic(&self) -> TxId {
        self.begin().unwrap_or_else(|err| panic!("{err}"))
    }

    pub fn commit(&self, tx: TxId) -> Result<()> {
        // Direct API commits can run trigger callbacks that execute nested
        // reads; give them the same statement-level schema view as SQL
        // `COMMIT` (which enters this gate through `execute`). A transaction
        // with privately staged local schema must retain the write side
        // through Redb durability and the complete after-apply publication;
        // ordinary DML-only commits remain readers.
        let _schema_publication = self.enter_commit_schema_publication_gate(tx);
        let _operation =
            self.open_operation_after_public_tx_control_wait_for_tx("commit", Some(tx))?;
        let _user_commit = self.enter_user_commit_callback_scope();
        let result = self.commit_with_source(tx, CommitSource::User);
        if result.is_ok() {
            self.maybe_warn_caller_driven_backlog();
        }
        result
    }

    /// `CallerDriven` maintenance means the engine spawns no thread of its
    /// own, so nothing else ever notices a caller who declared retention or
    /// version-history cleanup and then never drives a cycle. Rather than
    /// fail silently, the NEXT commit after a full tick interval has elapsed
    /// with no cycle call logs one warning -- throttled to at most once per
    /// interval, so a caller that never drives a cycle is not warned on
    /// every single commit.
    fn maybe_warn_caller_driven_backlog(&self) {
        if !self.maintenance_caller_driven.load(Ordering::SeqCst) {
            return;
        }
        if !(self.has_version_cleanup_tables()
            || self.has_retained_tables()
            || self.has_durable_trigger_audit())
        {
            return;
        }
        let now = std::time::Instant::now();
        let overdue = match *self.last_maintenance_cycle_at.lock() {
            Some(at) => now.duration_since(at) >= MAINTENANCE_TICK,
            None => true,
        };
        if !overdue {
            return;
        }
        let mut warned_at = self.caller_driven_backlog_warned_at.lock();
        if warned_at.is_some_and(|at| now.duration_since(at) < MAINTENANCE_TICK) {
            return;
        }
        *warned_at = Some(now);
        drop(warned_at);
        tracing::warn!(
            name: "caller_driven_maintenance_backlog",
            target: "maintenance",
            "this database declares retention, HISTORY CURRENT ONLY, or a durable trigger \
             audit, and its maintenance policy is CallerDriven, but no run_maintenance_cycle \
             call has landed in over a tick interval -- declared cleanup is not being reclaimed"
        );
    }

    pub fn rollback(&self, tx: TxId) -> Result<()> {
        let _operation =
            self.open_operation_after_public_tx_control_wait_for_tx("rollback", Some(tx))?;
        self.rollback_without_callback_tx_control(tx)
    }

    fn rollback_without_callback_tx_control(&self, tx: TxId) -> Result<()> {
        let ws = self.tx_mgr.rollback_write_set(tx)?;
        self.pending_event_bus_ddl.lock().remove(&tx);
        self.pending_local_schema_stages.lock().remove(&tx);
        self.pending_commit_metadata.lock().remove(&tx);
        self.release_insert_allocations(&ws);
        Ok(())
    }

    fn local_schema_stage_unsupported(stmt: &Statement) -> bool {
        match stmt {
            Statement::CreateTable(table) => {
                table.columns.iter().any(|column| {
                    matches!(column.data_type, DataType::Vector(_)) || column.rank_policy.is_some()
                }) || !table.dag_edge_types.is_empty()
            }
            Statement::AlterTable(alter) => matches!(
                &alter.action,
                AlterAction::AddColumn(column)
                    if matches!(column.data_type, DataType::Vector(_)) || column.rank_policy.is_some()
            ),
            _ => false,
        }
    }

    fn is_staged_local_schema_statement(stmt: &Statement) -> bool {
        matches!(stmt, Statement::CreateTable(_))
            || matches!(stmt, Statement::AlterTable(alter) if matches!(alter.action, AlterAction::AddColumn(_)))
    }

    fn is_local_table_schema_statement(stmt: &Statement) -> bool {
        matches!(
            stmt,
            Statement::CreateTable(_)
                | Statement::DropTable(_)
                | Statement::AlterTable(_)
                | Statement::CreateIndex(_)
                | Statement::DropIndex(_)
                | Statement::CreateTrigger { .. }
                | Statement::DropTrigger { .. }
        )
    }

    fn ensure_no_mixed_local_schema_dml(&self, tx: TxId) -> Result<()> {
        if self.pending_local_schema_stages.lock().contains_key(&tx) {
            return Err(Error::Other(
                "mixed DML and transactional local schema DDL is not supported; commit or roll back before writing rows"
                    .to_string(),
            ));
        }
        Ok(())
    }

    fn ensure_no_pending_event_bus_ddl_for_local_schema(&self, tx: TxId) -> Result<()> {
        if self
            .pending_event_bus_ddl
            .lock()
            .get(&tx)
            .is_some_and(|ddl| !ddl.is_empty())
        {
            return Err(Error::Other(
                "event-bus DDL and transactional local table schema DDL cannot be combined yet; commit or roll back before changing the other schema surface"
                    .to_string(),
            ));
        }
        Ok(())
    }

    fn local_schema_pending_baseline_bytes(&self) -> usize {
        let metadata = self
            .relational_store
            .table_meta
            .read()
            .values()
            .fold(0usize, |bytes, meta| {
                bytes.saturating_add(meta.estimated_bytes())
            });
        let triggers =
            self.trigger
                .declarations
                .lock()
                .values()
                .fold(0usize, |bytes, declaration| {
                    bytes
                        .saturating_add(64)
                        .saturating_add(declaration.name.len())
                        .saturating_add(declaration.table.len())
                        .saturating_add(declaration.on_events.len().saturating_mul(8))
                });
        // `base_tables` and the schema-only worker each own metadata; the
        // worker also prebuilds physical index declarations. Trigger state is
        // retained in both the baseline and worker projections.
        metadata
            .saturating_mul(3)
            .saturating_add(triggers.saturating_mul(2))
            .saturating_add(4096)
    }

    fn new_pending_local_schema_stage(&self) -> Result<PendingLocalSchemaStage> {
        let temporary_memory = TemporaryMemoryReservation::reserve(
            self.accountant.clone(),
            self.local_schema_pending_baseline_bytes(),
            "stage_transactional_schema",
        )?;
        let working = self.detached_local_schema_working_database()?;
        *working.trigger.declarations.lock() = self.trigger.declarations.lock().clone();
        let base_triggers = working.trigger.declarations.lock().clone();
        Ok(PendingLocalSchemaStage {
            base_triggers,
            base_table_generations: HashMap::new(),
            working,
            base_tables: self.relational_store.table_meta.read().clone(),
            temporary_memory,
        })
    }

    fn staged_table_ddl_temporary_bytes(sql: &str) -> usize {
        sql.len().saturating_mul(32).saturating_add(4096)
    }

    fn staged_trigger_ddl_temporary_bytes(ddl: &DdlChange) -> usize {
        let payload = match ddl {
            DdlChange::CreateTrigger {
                name,
                table,
                on_events,
            }
            | DdlChange::CreateTriggerIncludingSync {
                name,
                table,
                on_events,
            } => name
                .len()
                .saturating_add(table.len())
                .saturating_add(on_events.iter().map(String::len).sum::<usize>()),
            DdlChange::DropTrigger { name } => name.len(),
            _ => 0,
        };
        payload.saturating_mul(32).saturating_add(4096)
    }

    fn capture_local_schema_base_generation(
        &self,
        pending: &mut PendingLocalSchemaStage,
        ddl: &DdlChange,
    ) -> Result<()> {
        let table = Self::ddl_affected_table(ddl)
            .map(str::to_string)
            .or_else(|| match ddl {
                DdlChange::DropTrigger { name } => pending
                    .base_triggers
                    .get(name)
                    .map(|declaration| declaration.table.clone()),
                _ => None,
            });
        let Some(table) = table else {
            return Ok(());
        };
        let generation = self.authoritative_table_generation_counter(&table)?;
        pending
            .base_table_generations
            .entry(table.clone())
            .or_insert(generation);
        pending
            .working
            .in_memory_table_generations
            .lock()
            .entry(table)
            .or_insert(generation);
        Ok(())
    }

    /// Run the requested local schema change against a private clone.  The
    /// clone deliberately uses the ordinary executor, so sequential DDL gets
    /// its established validation without publishing a half-transaction
    /// schema to the live database.
    fn stage_local_schema_statement(
        &self,
        tx: TxId,
        stmt: &Statement,
        sql: &str,
    ) -> Result<QueryResult> {
        self.ensure_no_pending_event_bus_ddl_for_local_schema(tx)?;
        match stmt {
            Statement::CreateTable(_) if self.has_context_or_principal_constraints() => {
                return Err(Error::Other(
                    "DDL requires an admin database handle".to_string(),
                ));
            }
            Statement::AlterTable(_) if self.has_access_constraints_for_query() => {
                return Err(Error::Other(
                    "DDL requires an admin database handle".to_string(),
                ));
            }
            Statement::CreateTable(_) => self.check_disk_budget("CREATE TABLE")?,
            Statement::AlterTable(_) => self.check_disk_budget("ALTER TABLE")?,
            _ => {}
        }
        if Self::local_schema_stage_unsupported(stmt) {
            return Err(Error::Other(
                "transactional local schema staging currently supports CREATE TABLE and ALTER TABLE ADD COLUMN only for non-vector, non-rank, non-DAG shapes; commit or roll back before using this schema feature"
                    .to_string(),
            ));
        }
        let existing = self.pending_local_schema_stages.lock().remove(&tx);
        if existing.is_none() {
            let write_set = self.tx_mgr.cloned_write_set(tx)?;
            if !write_set.is_empty() {
                return Err(Error::Other(
                    "mixed DML and transactional local schema DDL is not supported; commit or roll back before changing schema"
                        .to_string(),
                ));
            }
        }
        let had_pending = existing.is_some();
        let mut pending = match existing {
            Some(pending) => pending,
            None => self.new_pending_local_schema_stage()?,
        };
        let change = pending
            .working
            .ddl_change_for_statement(stmt, None)
            .expect("staged local table statement has a DDL change");
        if let Err(error) = self.capture_local_schema_base_generation(&mut pending, &change) {
            if had_pending {
                self.pending_local_schema_stages.lock().insert(tx, pending);
            }
            return Err(error);
        }
        let statement_memory = match TemporaryMemoryReservation::reserve(
            self.accountant.clone(),
            Self::staged_table_ddl_temporary_bytes(sql),
            "grow_transactional_schema_stage",
        ) {
            Ok(reservation) => reservation,
            Err(error) => {
                if had_pending {
                    self.pending_local_schema_stages.lock().insert(tx, pending);
                }
                return Err(error);
            }
        };
        if let Err(error) = self.plugin.on_ddl(&change) {
            if had_pending {
                self.pending_local_schema_stages.lock().insert(tx, pending);
            }
            return Err(error);
        }
        let result = pending.working.execute(sql, &HashMap::new());
        match result {
            Ok(result) => {
                pending.temporary_memory.absorb(statement_memory);
                self.tx_mgr.with_write_set(tx, |ws| {
                    ws.requires_commit_lsn = true;
                })?;
                self.pending_local_schema_stages.lock().insert(tx, pending);
                Ok(result)
            }
            Err(error) => {
                // A failed second statement must not erase earlier valid DDL
                // from the still-open transaction.
                if had_pending {
                    self.pending_local_schema_stages.lock().insert(tx, pending);
                }
                Err(error)
            }
        }
    }

    fn stage_local_trigger_ddl(&self, tx: TxId, ddl: DdlChange) -> Result<()> {
        self.ensure_no_pending_event_bus_ddl_for_local_schema(tx)?;
        self.require_admin_trigger_ddl(match &ddl {
            DdlChange::CreateTrigger { .. } | DdlChange::CreateTriggerIncludingSync { .. } => {
                "CREATE TRIGGER"
            }
            DdlChange::DropTrigger { .. } => "DROP TRIGGER",
            _ => "trigger DDL",
        })?;
        let existing = self.pending_local_schema_stages.lock().remove(&tx);
        if existing.is_none() {
            let write_set = self.tx_mgr.cloned_write_set(tx)?;
            if !write_set.is_empty() {
                return Err(Error::Other(
                    "mixed DML and transactional local schema DDL is not supported; commit or roll back before changing schema"
                        .to_string(),
                ));
            }
        }
        let had_pending = existing.is_some();
        let mut pending = match existing {
            Some(pending) => pending,
            None => self.new_pending_local_schema_stage()?,
        };
        // Capture before private execution while the outer schema-write gate
        // excludes COMMIT/ROLLBACK and structural ABA. A fallible generation
        // read must not discard earlier valid DDL from the still-open tx.
        if let Err(error) = self.capture_local_schema_base_generation(&mut pending, &ddl) {
            if had_pending {
                self.pending_local_schema_stages.lock().insert(tx, pending);
            }
            return Err(error);
        }
        let statement_memory = match TemporaryMemoryReservation::reserve(
            self.accountant.clone(),
            Self::staged_trigger_ddl_temporary_bytes(&ddl),
            "grow_transactional_schema_stage",
        ) {
            Ok(reservation) => reservation,
            Err(error) => {
                if had_pending {
                    self.pending_local_schema_stages.lock().insert(tx, pending);
                }
                return Err(error);
            }
        };
        let result = pending.working.apply_trigger_ddl_from_user(ddl);
        match result {
            Ok(()) => {
                pending.temporary_memory.absorb(statement_memory);
                self.tx_mgr
                    .with_write_set(tx, |ws| ws.requires_commit_lsn = true)?;
                self.pending_local_schema_stages.lock().insert(tx, pending);
                Ok(())
            }
            Err(error) => {
                if had_pending {
                    self.pending_local_schema_stages.lock().insert(tx, pending);
                }
                Err(error)
            }
        }
    }

    pub fn snapshot(&self) -> SnapshotId {
        let _operation = self.assert_open_operation();
        self.tx_mgr.snapshot()
    }

    pub fn snapshot_at(&self, lsn: Lsn) -> SnapshotId {
        let _operation = self.assert_open_operation();
        self.tx_mgr.snapshot_at_lsn(lsn)
    }

    fn enter_sync_apply_trigger_gate_bypass(&self) -> SyncApplyTriggerGateGuard {
        SYNC_APPLY_TRIGGER_GATE_BYPASS_DEPTH.with(|depth| {
            depth.set(depth.get().saturating_add(1));
        });
        SyncApplyTriggerGateGuard
    }

    fn sync_apply_trigger_gate_bypass_active() -> bool {
        SYNC_APPLY_TRIGGER_GATE_BYPASS_DEPTH.with(|depth| depth.get() > 0)
    }

    fn enter_sync_apply_local_schema_bypass(&self, tx: TxId) -> SyncApplyLocalSchemaBypassGuard {
        let db_id = self as *const Self as usize;
        SYNC_APPLY_LOCAL_SCHEMA_BYPASS_STACK.with(|stack| {
            stack.borrow_mut().push((db_id, tx));
        });
        SyncApplyLocalSchemaBypassGuard { db_id, tx }
    }

    fn sync_apply_local_schema_bypass_active(&self, tx: TxId) -> bool {
        let db_id = self as *const Self as usize;
        SYNC_APPLY_LOCAL_SCHEMA_BYPASS_STACK.with(|stack| stack.borrow().contains(&(db_id, tx)))
    }

    fn enter_user_commit_callback_scope(&self) -> UserCommitCallbackGuard {
        let prior_active = USER_COMMIT_ACTIVE.with(|slot| slot.replace(true));
        let prior_reentry = USER_COMMIT_TRIGGER_REENTRY.with(|slot| slot.replace(false));
        UserCommitCallbackGuard {
            prior_active,
            prior_reentry,
        }
    }

    fn record_user_commit_trigger_reentry(&self) {
        if self.access_is_admin() && USER_COMMIT_ACTIVE.with(|slot| slot.get()) {
            USER_COMMIT_TRIGGER_REENTRY.with(|slot| slot.set(true));
        }
    }

    fn take_user_commit_trigger_reentry(&self) -> bool {
        USER_COMMIT_TRIGGER_REENTRY.with(|slot| slot.replace(false))
    }

    pub fn execute(&self, sql: &str, params: &HashMap<String, Value>) -> Result<QueryResult> {
        let scope = QueryRowsExaminedScope::enter(self);
        let mut result = self.execute_with_rows_examined_scope(sql, params);
        scope.finish(&mut result);
        result
    }

    fn execute_with_rows_examined_scope(
        &self,
        sql: &str,
        params: &HashMap<String, Value>,
    ) -> Result<QueryResult> {
        // Checked BEFORE the snapshot registration below: `snapshot_for_read`
        // resolves through the public `Database::snapshot`, which panics on a
        // closed handle (`assert_open_operation`) by design for a caller that
        // asks for a snapshot directly. `execute` is a `Result`-returning
        // surface, never a panicking one -- a scoped view whose owner has
        // closed must see the same typed closed-handle error every other
        // `execute` path already returns, not a panic. Deliberately a
        // LOCK-FREE check (`already_closed`, not `open_operation`): this
        // function's own later logic can legitimately PARK a caller waiting
        // on an in-flight trigger callback (e.g. `BEGIN` under contention),
        // and `close()` needs `operation_gate`'s write lock to ever
        // complete -- holding its read lock here across that wait would
        // deadlock close() against the parked caller. This check narrows,
        // but does not by itself close, the race: a close landing between
        // THIS check and the snapshot registration just below is caught
        // there instead, by that call's own fallible form
        // (`try_snapshot_for_read`), not by anything later in this
        // function -- the registration precedes every one of this
        // function's own `open_operation()?` calls, so those cannot be
        // what catches a close in this specific window.
        if self.already_closed() {
            return Err(closed_database_error());
        }
        // Test-only race seam: deterministically simulates a close landing
        // in the window this comment block describes, on this same thread.
        // See `CLOSE_IN_SNAPSHOT_REGISTRATION_RACE_WINDOW`'s own doc
        // comment; production-dead, reads a thread-local that is never set.
        if take_close_in_snapshot_registration_race_window_for_test() {
            self.close()
                .expect("test-only synchronous close in the race window must succeed");
        }
        // Registered for exactly this call's duration -- see
        // `SnapshotFloorRegistry`'s doc comment. Covers `execute_at_snapshot`
        // too, since it runs through this same function under an override.
        // `try_snapshot_for_read`, not the panicking `snapshot_for_read`:
        // a close landing between the `already_closed` check above and this
        // line must still surface as the typed closed-handle error.
        let Some(read_snapshot) = self.try_snapshot_for_read() else {
            return Err(closed_database_error());
        };
        let _snapshot_registration = self.snapshot_registry.register(read_snapshot);
        let cached = self.cached_statement(sql);
        let parsed_stmt;
        let (stmt, cached_plan) = if let Some(cached) = cached.as_ref() {
            (&cached.stmt, Some(&cached.plan))
        } else {
            parsed_stmt = contextdb_parser::parse(sql)?;
            (&parsed_stmt, None)
        };
        if Self::callback_active_process_wide() {
            self.assert_statement_allowed_for_callbacks_for_surface(stmt, "execute")?;
        }
        // This is the outer parsed-statement boundary: planning, subqueries,
        // trigger/callback reads, execution and autocommit all stay on one
        // side of a local table-schema publication.
        let session_schema_commit = if matches!(stmt, Statement::Commit) {
            *self.session_tx.lock()
        } else {
            None
        };
        let _schema_publication = if let Some(tx) = session_schema_commit {
            self.enter_commit_schema_publication_gate(tx)
        } else {
            self.enter_schema_publication_gate(Self::statement_changes_table_schema(stmt))
        };

        match stmt {
            Statement::Begin => {
                if self.session_tx.lock().is_none() {
                    if Self::callback_active_process_wide() {
                        self.assert_callback_reentry_allowed()?;
                        self.assert_public_tx_control_cross_thread_allowed_for_surface("begin")?;
                    }
                    let _operation = self.open_operation()?;
                    let mut session = self.session_tx.lock();
                    if session.is_none() {
                        *session = Some(self.tx_mgr.begin());
                    }
                }
                return Ok(QueryResult::empty());
            }
            Statement::Commit => {
                let tx = *self.session_tx.lock();
                if let Some(tx) = tx {
                    match self.commit(tx) {
                        Ok(()) => {
                            let mut session = self.session_tx.lock();
                            if *session == Some(tx) {
                                *session = None;
                            }
                        }
                        Err(err) => {
                            if self.tx_mgr.cloned_write_set(tx).is_err() {
                                let mut session = self.session_tx.lock();
                                if *session == Some(tx) {
                                    *session = None;
                                }
                            }
                            return Err(err);
                        }
                    }
                }
                return Ok(QueryResult::empty());
            }
            Statement::Rollback => {
                let tx = *self.session_tx.lock();
                if let Some(tx) = tx {
                    self.rollback(tx)?;
                    let mut session = self.session_tx.lock();
                    if *session == Some(tx) {
                        *session = None;
                    }
                }
                return Ok(QueryResult::empty());
            }
            _ => {}
        }

        let active_tx = self.active_session_tx();
        let preopened_autocommit_tx =
            if active_tx.is_none() && Self::statement_uses_public_autocommit_write(stmt) {
                Some(self.begin_for_public_autocommit_write()?)
            } else {
                None
            };

        let operation_result = if preopened_autocommit_tx.is_some() {
            self.open_operation()
        } else {
            self.open_operation_after_statement_callback_wait(stmt, "execute")
        };
        let _operation = match operation_result {
            Ok(operation) => operation,
            Err(error) => {
                self.rollback_preopened_autocommit_tx(preopened_autocommit_tx);
                return Err(error);
            }
        };

        match stmt {
            Statement::CreateSchedule {
                name,
                every,
                callback,
                missed_tick_policy,
                catch_up_within_seconds,
            } => {
                self.create_cron_schedule(
                    name,
                    every,
                    callback,
                    missed_tick_policy.as_deref(),
                    *catch_up_within_seconds,
                )?;
                return Ok(QueryResult::empty());
            }
            Statement::DropSchedule { name } => {
                self.drop_cron_schedule(name)?;
                return Ok(QueryResult::empty());
            }
            Statement::CreateTrigger { .. } | Statement::DropTrigger { .. } => {
                let ddl = self
                    .ddl_change_for_statement(stmt, self.active_session_tx())
                    .expect("trigger statement has DDL change");
                if let Some(tx) = self.active_session_tx() {
                    self.stage_local_trigger_ddl(tx, ddl)?;
                } else {
                    self.apply_trigger_ddl_from_user(ddl)?;
                }
                return Ok(QueryResult::empty());
            }
            _ => {}
        }

        let result = self.execute_statement_with_plan(
            stmt,
            sql,
            params,
            active_tx,
            cached_plan,
            preopened_autocommit_tx,
        );

        #[cfg(test)]
        if matches!(stmt, Statement::Select(_)) {
            maybe_pause_before_query_trace_rows_examined_capture_for_test();
        }

        result
    }

    fn active_session_tx(&self) -> Option<TxId> {
        if CRON_CALLBACK_ACTIVE.with(|active| active.get()) {
            let this_db = self as *const Self as usize;
            if CRON_CALLBACK_DB.with(|slot| slot.get()) == Some(this_db) {
                return CRON_CALLBACK_TX.with(|slot| slot.get());
            }
        }
        if let Some(tx) = self.active_trigger_tx_for_this_handle() {
            return Some(tx);
        }
        *self.session_tx.lock()
    }

    fn assert_statement_allowed_inside_cron_callback(
        &self,
        stmt: &Statement,
        forbidden_in_callback: bool,
        requires_callback_tx: bool,
    ) -> Result<()> {
        if CRON_CALLBACK_ACTIVE.with(|active| active.get()) && forbidden_in_callback {
            return Err(Error::CallbackReentry {
                kind: CallbackKind::Cron,
            });
        }
        if CRON_CALLBACK_ACTIVE.with(|active| active.get()) && requires_callback_tx {
            let active_tx = self.active_session_tx();
            let cron_tx = CRON_CALLBACK_TX.with(|slot| slot.get());
            let cron_db = CRON_CALLBACK_DB.with(|slot| slot.get());
            let this_db = self as *const Self as usize;
            if active_tx.is_none() || active_tx != cron_tx || cron_db != Some(this_db) {
                return Err(Error::CallbackReentry {
                    kind: CallbackKind::Cron,
                });
            }
        }
        if TRIGGER_CALLBACK_ACTIVE.with(|active| active.get()) && forbidden_in_callback {
            // Self-drop of the currently firing trigger has a long-standing
            // admin-error contract: block the DDL locally, preserve the active
            // trigger, and let the firing cascade continue if the callback
            // handles the error.
            if let Statement::DropTrigger { name } = stmt {
                let drops_active_trigger = TRIGGER_CALLBACK_NAME
                    .with(|active_name| active_name.borrow().as_deref() == Some(name));
                let drops_from_active_trigger_handle = TRIGGER_CALLBACK_DB
                    .with(|active_db| active_db.get() == Some(self as *const Self as usize));
                if drops_active_trigger && drops_from_active_trigger_handle {
                    return Ok(());
                }
            }
            self.record_user_commit_trigger_reentry();
            return Err(Error::CallbackReentry {
                kind: CallbackKind::Trigger,
            });
        }
        if TRIGGER_CALLBACK_ACTIVE.with(|active| active.get()) && requires_callback_tx {
            let active_tx = self.active_session_tx();
            let trigger_tx = TRIGGER_CALLBACK_TX.with(|slot| slot.get());
            let trigger_db = TRIGGER_CALLBACK_DB.with(|slot| slot.get());
            let this_db = self as *const Self as usize;
            if active_tx.is_none() || active_tx != trigger_tx || trigger_db != Some(this_db) {
                self.record_user_commit_trigger_reentry();
                return Err(Error::CallbackReentry {
                    kind: CallbackKind::Trigger,
                });
            }
        }
        Ok(())
    }

    fn assert_statement_allowed_during_cross_thread_callback(
        &self,
        forbidden_in_callback: bool,
        requires_callback_tx: bool,
        surface: &'static str,
    ) -> Result<()> {
        if !forbidden_in_callback && !requires_callback_tx {
            return Ok(());
        }
        if self.cron.callback_active_on_other_thread() {
            return Err(Error::CallbackActiveCrossThread {
                kind: CallbackKind::Cron,
            });
        }
        if self
            .trigger
            .callback_active_on_other_thread(self.owner_thread)
        {
            return self.wait_for_same_db_trigger_callback_idle(surface);
        }
        if requires_callback_tx {
            match self
                .trigger
                .callback_contention_for_tx_control(self.owner_thread, false)
            {
                TriggerContention::None => {}
                TriggerContention::SameDb => {
                    return self.wait_for_same_db_trigger_callback_idle(surface);
                }
            }
        }
        Ok(())
    }

    fn assert_statement_allowed_for_callbacks_for_surface(
        &self,
        stmt: &Statement,
        surface: &'static str,
    ) -> Result<()> {
        let forbidden_in_callback = Self::statement_forbidden_inside_cron_callback(stmt);
        let requires_callback_tx = Self::statement_requires_cron_bound_handle(stmt);
        if !forbidden_in_callback && !requires_callback_tx {
            return Ok(());
        }
        if !Self::callback_active_process_wide() {
            return Ok(());
        }
        self.assert_statement_allowed_inside_cron_callback(
            stmt,
            forbidden_in_callback,
            requires_callback_tx,
        )?;
        self.assert_statement_allowed_during_cross_thread_callback(
            forbidden_in_callback,
            requires_callback_tx,
            surface,
        )
    }

    fn cached_statement(&self, sql: &str) -> Option<Arc<CachedStatement>> {
        self.statement_cache.read().get(sql).cloned()
    }

    fn cache_statement_if_eligible(&self, sql: &str, stmt: &Statement, plan: &PhysicalPlan) {
        if !Self::is_statement_cache_eligible(stmt, plan) {
            return;
        }

        let mut cache = self.statement_cache.write();
        if cache.contains_key(sql) {
            return;
        }
        if cache.len() >= MAX_STATEMENT_CACHE_ENTRIES {
            return;
        }
        cache.insert(
            sql.to_string(),
            Arc::new(CachedStatement {
                stmt: stmt.clone(),
                plan: plan.clone(),
            }),
        );
    }

    fn is_statement_cache_eligible(stmt: &Statement, plan: &PhysicalPlan) -> bool {
        match (stmt, plan) {
            (Statement::Insert(ins), PhysicalPlan::Insert(_)) => {
                !ins.table.eq_ignore_ascii_case("GRAPH")
                    && !ins.table.eq_ignore_ascii_case("__edges")
            }
            (Statement::Update(_), PhysicalPlan::Update(_))
            | (Statement::Delete(_), PhysicalPlan::Delete(_)) => true,
            _ => false,
        }
    }

    fn statement_forbidden_inside_cron_callback(stmt: &Statement) -> bool {
        matches!(
            stmt,
            Statement::Begin
                | Statement::Commit
                | Statement::Rollback
                | Statement::CreateTable(_)
                | Statement::AlterTable(_)
                | Statement::DropTable(_)
                | Statement::CreateIndex(_)
                | Statement::DropIndex(_)
                | Statement::CreateSchedule { .. }
                | Statement::DropSchedule { .. }
                | Statement::CreateTrigger { .. }
                | Statement::DropTrigger { .. }
                | Statement::CreateEventType { .. }
                | Statement::CreateSink { .. }
                | Statement::CreateRoute { .. }
                | Statement::DropRoute { .. }
                | Statement::SetMemoryLimit(_)
                | Statement::SetDiskLimit(_)
                | Statement::Purge(_)
        )
    }

    fn statement_requires_cron_bound_handle(stmt: &Statement) -> bool {
        matches!(
            stmt,
            Statement::Insert(_) | Statement::Delete(_) | Statement::Update(_)
        )
    }

    fn statement_uses_public_autocommit_write(stmt: &Statement) -> bool {
        matches!(
            stmt,
            Statement::Insert(_) | Statement::Delete(_) | Statement::Update(_)
        )
    }

    fn plan_vector_schema_refs(&self, plan: &PhysicalPlan) -> Vec<VectorIndexRef> {
        match plan {
            PhysicalPlan::Insert(plan) => self.vector_schema_refs_for_table(&plan.table),
            PhysicalPlan::Delete(plan) => self.vector_schema_refs_for_table(&plan.table),
            PhysicalPlan::Update(plan) => self.vector_schema_refs_for_table(&plan.table),
            _ => Vec::new(),
        }
    }

    pub(crate) fn write_set_vector_schema_refs(ws: &WriteSet) -> Vec<VectorIndexRef> {
        VectorSchemaGates::sorted_refs(
            ws.vector_inserts
                .iter()
                .map(|entry| entry.index.clone())
                .chain(ws.vector_deletes.iter().map(|(index, _, _)| index.clone()))
                .chain(ws.vector_moves.iter().map(|(index, _, _, _)| index.clone())),
        )
    }

    pub(crate) fn write_set_touches_vector_schema(ws: &WriteSet) -> bool {
        !Self::write_set_vector_schema_refs(ws).is_empty()
    }

    fn record_vector_schema_epoch(&self, tx: TxId, index: &VectorIndexRef) -> Result<()> {
        self.record_vector_schema_epochs(tx, [index.clone()])
    }

    fn record_vector_schema_epochs(
        &self,
        tx: TxId,
        refs: impl IntoIterator<Item = VectorIndexRef>,
    ) -> Result<()> {
        let refs = VectorSchemaGates::sorted_refs(refs);
        if refs.is_empty() {
            return Ok(());
        }
        self.tx_mgr.with_write_set(tx, |_| ())?;
        let observed = refs
            .into_iter()
            .map(|index| {
                let epoch = self.vector_schema_gates.epoch_for(&index);
                (index, epoch)
            })
            .collect::<Vec<_>>();
        let mut metadata = self.pending_commit_metadata.lock();
        let metadata = metadata.entry(tx).or_default();
        for (index, epoch) in observed {
            metadata.vector_schema_epochs.entry(index).or_insert(epoch);
        }
        Ok(())
    }

    pub(crate) fn clear_statement_cache(&self) {
        self.statement_cache.write().clear();
    }

    fn clear_trigger_insert_state_machine_cache(db_key: usize) {
        TRIGGER_INSERT_STATE_MACHINE_CACHE.with(|cache| {
            cache.borrow_mut().remove(&db_key);
        });
    }

    fn trigger_insert_table_has_state_machine(&self, table: &str) -> Result<bool> {
        let db_key = self as *const Self as usize;
        if let Some(cached) = TRIGGER_INSERT_STATE_MACHINE_CACHE.with(|cache| {
            cache
                .borrow()
                .get(&db_key)
                .and_then(|by_table| by_table.get(table).copied())
        }) {
            return Ok(cached);
        }

        let has_state_machine = self
            .relational_store
            .table_has_state_machine(table)
            .ok_or_else(|| Error::TableNotFound(table.to_string()))?;
        TRIGGER_INSERT_STATE_MACHINE_CACHE.with(|cache| {
            cache
                .borrow_mut()
                .entry(db_key)
                .or_default()
                .insert(table.to_string(), has_state_machine);
        });
        Ok(has_state_machine)
    }

    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn __statement_cache_len(&self) -> usize {
        let _operation = self.assert_open_operation();
        self.statement_cache.read().len()
    }

    fn execute_autocommit(
        &self,
        plan: &PhysicalPlan,
        params: &HashMap<String, Value>,
        preopened_autocommit_tx: Option<TxId>,
    ) -> Result<QueryResult> {
        match plan {
            PhysicalPlan::Insert(_) | PhysicalPlan::Delete(_) | PhysicalPlan::Update(_) => {
                let tx = match preopened_autocommit_tx {
                    Some(tx) => tx,
                    None => self.begin_for_public_autocommit_write()?,
                };
                let vector_schema_refs = self.plan_vector_schema_refs(plan);
                let _vector_schema = (!vector_schema_refs.is_empty())
                    .then(|| self.vector_schema_read_many(vector_schema_refs));
                let result = {
                    let _write_gate = self.enter_sql_write_control_bypass(tx);
                    let snapshot = self.snapshot_for_read();
                    self.with_snapshot_override(snapshot, || {
                        execute_plan(self, plan, params, Some(tx))
                    })
                };
                match result {
                    Ok(mut qr) => {
                        let event_bus_ddl = self.take_pending_event_bus_ddl(tx);
                        let validation = self.commit_with_source_and_event_bus_ddl(
                            tx,
                            CommitSource::AutoCommit,
                            &event_bus_ddl,
                        )?;
                        qr.rows_affected = qr
                            .rows_affected
                            .saturating_sub(validation.conditional_noop_count);
                        Ok(qr)
                    }
                    Err(e) => {
                        let _ = self.rollback_without_callback_tx_control(tx);
                        Err(e)
                    }
                }
            }
            _ => {
                if preopened_autocommit_tx.is_some() {
                    self.rollback_preopened_autocommit_tx(preopened_autocommit_tx);
                    return Err(Error::Other(
                        "internal autocommit transaction reserved for non-DML statement"
                            .to_string(),
                    ));
                }
                execute_plan(self, plan, params, None)
            }
        }
    }

    pub fn explain(&self, sql: &str) -> Result<String> {
        let stmt = contextdb_parser::parse(sql)?;
        let _schema_publication = self.enter_schema_publication_gate(false);
        let _operation = self.open_operation()?;
        let plan = contextdb_planner::plan(&stmt)?;
        // Refuse a statically-invalid query here too: rendering a plan for a
        // query that can never run reads as a green light for it.
        validate_plan_columns(self, &plan)?;
        let vector_shape = vector_search_shape_from_plan(&plan);
        let _vector_schema = vector_shape
            .as_ref()
            .map(|shape| self.vector_schema_read(&shape.index));
        let snapshot = self.snapshot();
        let mut output = plan.explain();
        let uses_hnsw = vector_shape
            .as_ref()
            .is_some_and(|shape| self.vector_hnsw_strategy_for_explain(shape, snapshot));
        if uses_hnsw {
            output = output.replace("VectorSearch(", "HNSWSearch(");
            output = output.replace("VectorSearch {", "HNSWSearch {");
        } else {
            output = annotate_vector_search_strategy(output, "BruteForce");
            output = output.replace("VectorSearch {", "VectorSearch { strategy: BruteForce,");
        }
        Ok(output)
    }

    fn vector_hnsw_strategy_for_explain(
        &self,
        shape: &VectorExplainShape,
        snapshot: SnapshotId,
    ) -> bool {
        if !self
            .vector
            .hnsw_eligible_without_build(&shape.index, snapshot)
        {
            return false;
        }
        !shape.restricted_candidates
            || self
                .vector
                .hnsw_search_covers_all_without_build(&shape.index, shape.k)
    }

    pub fn execute_in_tx(
        &self,
        tx: TxId,
        sql: &str,
        params: &HashMap<String, Value>,
    ) -> Result<QueryResult> {
        let scope = QueryRowsExaminedScope::enter(self);
        let mut result = self.execute_in_tx_with_rows_examined_scope(tx, sql, params);
        scope.finish(&mut result);
        result
    }

    fn execute_in_tx_with_rows_examined_scope(
        &self,
        tx: TxId,
        sql: &str,
        params: &HashMap<String, Value>,
    ) -> Result<QueryResult> {
        // Checked BEFORE the snapshot registration below -- see `execute`'s
        // own identical, deliberately LOCK-FREE guard for why (`already_
        // closed`, never `open_operation`, which this function's own later
        // `open_operation_after_*` calls must remain free to acquire without
        // a pre-held read lock from here deadlocking a racing `close()`).
        // Narrows, but does not by itself close, the race -- a close landing
        // between this check and the registration just below is caught
        // there instead (`try_snapshot_for_read`), not by anything later in
        // this function.
        if self.already_closed() {
            return Err(closed_database_error());
        }
        // Registered for exactly this call's duration -- see
        // `SnapshotFloorRegistry`'s doc comment on `execute`. Fallible form,
        // same reason as `execute`'s own identical line.
        let Some(read_snapshot) = self.try_snapshot_for_read() else {
            return Err(closed_database_error());
        };
        let _snapshot_registration = self.snapshot_registry.register(read_snapshot);
        let cached = self.cached_statement(sql);
        let parsed_stmt;
        let (stmt, cached_plan) = if let Some(cached) = cached.as_ref() {
            (&cached.stmt, Some(&cached.plan))
        } else {
            parsed_stmt = contextdb_parser::parse(sql)?;
            (&parsed_stmt, None)
        };
        let _schema_publication =
            self.enter_schema_publication_gate(Self::statement_changes_table_schema(stmt));
        let trigger_callback_bound = self.trigger_callback_tx_bound_matches(tx);
        if trigger_callback_bound && matches!(stmt, Statement::Update(_) | Statement::Delete(_)) {
            if let Some(plan) = cached_plan {
                // This branch reaches execute_plan without going through
                // run_planned_statement, so it applies the pass itself.
                validate_plan_columns(self, plan)?;
                let snapshot = self.snapshot_for_read();
                return self
                    .with_snapshot_override(snapshot, || execute_plan(self, plan, params, Some(tx)))
                    .map(strip_internal_row_id);
            }

            let stmt = self.pre_resolve_cte_subqueries(stmt, params, Some(tx))?;
            let plan = contextdb_planner::plan(&stmt)?;
            self.cache_statement_if_eligible(sql, &stmt, &plan);
            validate_plan_columns(self, &plan)?;
            let snapshot = self.snapshot_for_read();
            return self
                .with_snapshot_override(snapshot, || execute_plan(self, &plan, params, Some(tx)))
                .map(strip_internal_row_id);
        }
        let requires_callback_tx = Self::statement_requires_cron_bound_handle(stmt);
        if trigger_callback_bound {
            self.assert_statement_allowed_inside_cron_callback(
                stmt,
                Self::statement_forbidden_inside_cron_callback(stmt),
                requires_callback_tx,
            )?;
        } else if Self::callback_active_process_wide() {
            self.assert_callback_tx_bound_write_allowed(tx)?;
            self.assert_trigger_callback_tx_not_captured_cross_thread(tx)?;
            self.assert_statement_allowed_for_callbacks_for_surface(stmt, "execute_in_tx")?;
        }
        let _operation = if trigger_callback_bound {
            None
        } else if requires_callback_tx {
            Some(self.open_operation_after_write_control_wait(tx, "execute_in_tx")?)
        } else {
            Some(self.open_operation_after_statement_callback_wait(stmt, "execute_in_tx")?)
        };
        self.execute_statement_with_plan(stmt, sql, params, Some(tx), cached_plan, None)
    }

    /// Register a commit-time guard that requires the visible row selected by
    /// `key_column = key_value` to keep the supplied column values until this
    /// transaction commits. Returns `Ok(false)` when the row is not visible or
    /// does not currently match the predicates.
    pub fn guard_row_conditions_in_tx(
        &self,
        tx: TxId,
        table: &str,
        key_column: &str,
        key_value: &Value,
        predicates: &[(String, Value)],
    ) -> Result<bool> {
        let _operation = self.open_operation_after_public_tx_control_wait_for_tx(
            "guard_row_conditions_in_tx",
            Some(tx),
        )?;
        self.tx_mgr.with_write_set(tx, |_| ())?;
        self.assert_table_read_allowed(table)?;
        let meta = self
            .table_meta(table)
            .ok_or_else(|| Error::TableNotFound(table.to_string()))?;
        if !meta.columns.iter().any(|column| column.name == key_column) {
            return Err(Error::ColumnNotFound {
                table: table.to_string(),
                column: key_column.to_string(),
            });
        }
        for (column, _) in predicates {
            if !meta
                .columns
                .iter()
                .any(|definition| definition.name == *column)
            {
                return Err(Error::ColumnNotFound {
                    table: table.to_string(),
                    column: column.clone(),
                });
            }
        }

        let snapshot = self.snapshot();
        let Some(row) = self.point_lookup_in_tx(tx, table, key_column, key_value, snapshot)? else {
            return Ok(false);
        };
        if !self.read_allowed_for_row(table, &meta, &row, snapshot)? {
            return Ok(false);
        }
        if !predicates
            .iter()
            .all(|(column, value)| row.values.get(column) == Some(value))
        {
            return Ok(false);
        }
        let counts = self.write_set_counts(tx)?;
        self.record_conditional_update_guard(
            tx,
            table.to_string(),
            row.row_id,
            predicates.to_vec(),
            counts,
            counts,
            true,
        )?;
        Ok(true)
    }

    fn commit_with_source(&self, tx: TxId, source: CommitSource) -> Result<()> {
        let event_bus_ddl = self.take_pending_event_bus_ddl(tx);
        if self.pending_local_schema_stages.lock().contains_key(&tx) && !event_bus_ddl.is_empty() {
            self.pending_event_bus_ddl
                .lock()
                .entry(tx)
                .or_default()
                .extend(event_bus_ddl);
            return Err(Error::Other(
                "event-bus DDL and transactional local table schema DDL cannot be combined yet; commit or roll back before changing the other schema surface"
                    .to_string(),
            ));
        }
        self.commit_with_source_and_event_bus_ddl(tx, source, &event_bus_ddl)
            .map(|_| ())
    }

    fn prepare_and_register_local_schema_stage(
        &self,
        tx: TxId,
        visibility_tx: TxId,
        lsn: Lsn,
    ) -> Result<()> {
        let Some(pending) = self.pending_local_schema_stages.lock().remove(&tx) else {
            return Ok(());
        };
        // Statement routing fences SQL row DML and the public row helpers,
        // but graph/vector and future mutation entrypoints share the generic
        // WriteSet.  The commit boundary is the final authority: schema
        // staging is DDL-only until a full mixed-image implementation exists.
        let mut write_set = self.tx_mgr.cloned_write_set(tx)?;
        write_set.requires_commit_lsn = false;
        if !write_set.is_empty() {
            return Err(Error::Other(
                "mixed DML and transactional local schema DDL is not supported; commit or roll back before changing schema"
                    .to_string(),
            ));
        }
        if *self.relational_store.table_meta.read() != pending.base_tables {
            return Err(Error::Other(
                "concurrent schema change invalidated this transactional local DDL; retry the transaction"
                    .to_string(),
            ));
        }
        if *self.trigger.declarations.lock() != pending.base_triggers {
            return Err(Error::Other(
                "concurrent trigger change invalidated this transactional local DDL; retry the transaction"
                    .to_string(),
            ));
        }
        for (table, expected_generation) in &pending.base_table_generations {
            if self.authoritative_table_generation_counter(table)? != *expected_generation {
                return Err(Error::Other(
                    "concurrent table generation change invalidated this transactional local DDL; retry the transaction"
                        .to_string(),
                ));
            }
        }
        let working = pending.working;
        let staged_ddl = working.ddl_log.read().clone();
        if staged_ddl.is_empty() {
            return Err(Error::Other(
                "transactional local schema stage contains no DDL".to_string(),
            ));
        }
        let staged_changes = staged_ddl
            .iter()
            .map(|(_, change)| change.clone())
            .collect::<Vec<_>>();
        let tables = working.relational_store.table_meta.read().clone();
        let projected_tables = staged_changes
            .iter()
            .filter_map(|change| match change {
                DdlChange::CreateTable { name, .. } | DdlChange::AlterTable { name, .. } => {
                    Some(name.as_str())
                }
                _ => None,
            })
            .collect::<HashSet<_>>();

        // Prepare only tables whose metadata changes. The supported shapes do
        // not mutate stored row values, graph edges, or vector payloads, so a
        // schema commit never builds a whole-database replacement. Reserve
        // the affected projection's peak before cloning any live rows.
        let trigger_projection_bytes =
            working
                .trigger
                .declarations
                .lock()
                .values()
                .fold(0usize, |bytes, declaration| {
                    bytes
                        .saturating_add(64)
                        .saturating_add(declaration.name.len())
                        .saturating_add(declaration.table.len())
                        .saturating_add(declaration.on_events.len().saturating_mul(8))
                });
        let projection_peak_bytes = {
            let live_rows = self.relational_store.tables.read();
            projected_tables.iter().fold(
                trigger_projection_bytes
                    .saturating_mul(6)
                    .saturating_add(4096),
                |bytes, table| {
                    let Some(meta) = tables.get(*table) else {
                        return bytes;
                    };
                    let rows = live_rows.get(*table).map(Vec::as_slice).unwrap_or_default();
                    let row_bytes = rows.iter().fold(0usize, |row_bytes, row| {
                        row_bytes.saturating_add(estimate_row_bytes_for_meta(
                            &row.values,
                            meta,
                            false,
                        ))
                    });
                    bytes
                        .saturating_add(meta.estimated_bytes().saturating_mul(4))
                        .saturating_add(row_bytes.saturating_mul(4))
                },
            )
        };
        let temporary_memory = TemporaryMemoryReservation::reserve(
            self.accountant.clone(),
            projection_peak_bytes,
            "commit_transactional_schema",
        )?;
        let relational = {
            let live_rows = self.relational_store.tables.read();
            projected_tables
                .iter()
                .map(|table| {
                    let meta = tables.get(*table).cloned().ok_or_else(|| {
                        Error::SyncError(format!(
                            "transactional schema projection lost affected table {table}"
                        ))
                    })?;
                    Ok(RelationalStore::table_projection(
                        (*table).to_string(),
                        meta,
                        live_rows.get(*table).cloned().unwrap_or_default(),
                    ))
                })
                .collect::<Result<Vec<_>>>()?
        };
        let declarations = working.trigger.declarations.lock().clone();
        let trigger = self.prepare_received_trigger_publication_from_projection(declarations)?;
        let live_meta = self.relational_store.table_meta.read();
        let old_bytes = projected_tables.iter().fold(0usize, |bytes, table| {
            bytes.saturating_add(
                live_meta
                    .get(*table)
                    .map(TableMeta::estimated_bytes)
                    .unwrap_or(0),
            )
        });
        let new_bytes = projected_tables.iter().fold(0usize, |bytes, table| {
            bytes.saturating_add(
                tables
                    .get(*table)
                    .map(TableMeta::estimated_bytes)
                    .unwrap_or(0),
            )
        });
        drop(live_meta);
        let memory_swap =
            PreparedMemorySwap::prepare(self.accountant.clone(), old_bytes, new_bytes, 0)?;

        let working_table_generations = working.in_memory_table_generations.lock().clone();
        let affected_tables = staged_changes
            .iter()
            .filter_map(Self::ddl_affected_table)
            .collect::<HashSet<_>>();
        let table_generation_updates = affected_tables
            .iter()
            .map(|table| {
                working_table_generations
                    .get(*table)
                    .copied()
                    .ok_or_else(|| {
                        Error::SyncError(format!(
                            "transactional DDL has no projected generation for {table}"
                        ))
                    })
                    .map(|generation| ((*table).to_string(), generation))
            })
            .collect::<Result<HashMap<_, _>>>()?;
        let mut config_values = affected_tables
            .iter()
            .filter_map(|table| {
                table_generation_updates
                    .get(*table)
                    .map(|generation| (*table, *generation))
            })
            .map(|(table, generation)| {
                Ok((
                    Self::durable_lineage_table_generation_key(table),
                    RedbPersistence::encode_config_value(&generation)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        let mut ddl_generations = Vec::with_capacity(staged_changes.len());
        for (ordinal, change) in staged_changes.iter().enumerate() {
            let table = Self::ddl_affected_table(change).map(str::to_string);
            let generation = table
                .as_deref()
                .map(|table| {
                    table_generation_updates.get(table).copied().ok_or_else(|| {
                        Error::SyncError(format!(
                            "transactional DDL has no projected generation for {table}"
                        ))
                    })
                })
                .transpose()?;
            let sidecar = DurableDdlGenerationSidecar {
                table: table.clone(),
                table_generation: generation,
            };
            config_values.push((
                Self::durable_ddl_generation_sidecar_key(lsn, ordinal as u32),
                RedbPersistence::encode_config_value(&sidecar)?,
            ));
            ddl_generations.push(((lsn, ordinal as u32), (table, generation)));
        }
        config_values.extend(trigger.config_values.iter().cloned());
        let ddl_log = staged_changes
            .iter()
            .cloned()
            .map(|change| (lsn, change))
            .collect::<Vec<_>>();
        let durable_projection = LocalSchemaPersistenceProjection {
            affected_table_meta: projected_tables
                .iter()
                .map(|table| {
                    tables
                        .get(*table)
                        .cloned()
                        .map(|meta| ((*table).to_string(), meta))
                        .ok_or_else(|| {
                            Error::SyncError(format!(
                                "transactional schema persistence lost affected table {table}"
                            ))
                        })
                })
                .collect::<Result<HashMap<_, _>>>()?,
            ddl: staged_changes,
            config_values,
            commit_index_tx: visibility_tx,
        };
        self.local_schema_stages.lock().insert(
            lsn,
            LocalSchemaStage {
                relational,
                trigger,
                table_generations: table_generation_updates.into_iter().collect(),
                ddl_generations,
                ddl_log,
                memory_swap,
                _temporary_memory: temporary_memory,
                durable_projection,
            },
        );
        Ok(())
    }

    fn take_local_schema_stage(&self, lsn: Lsn) -> Option<LocalSchemaStage> {
        self.local_schema_stages.lock().remove(&lsn)
    }

    fn publish_local_schema_stage(&self, mut stage: LocalSchemaStage) {
        self.relational_store
            .publish_table_projections(stage.relational);
        self.publish_prepared_trigger_publication(stage.trigger);
        self.in_memory_table_generations
            .lock()
            .extend(stage.table_generations);
        self.in_memory_ddl_generations
            .lock()
            .extend(stage.ddl_generations);
        self.ddl_log.write().extend(stage.ddl_log);
        stage.memory_swap.commit_after_swap();
        self.clear_statement_cache();
        self.reconcile_maintenance_thread();
    }

    fn commit_with_source_and_event_bus_ddl(
        &self,
        tx: TxId,
        source: CommitSource,
        event_bus_ddl: &[DdlChange],
    ) -> Result<CommitValidationOutcome> {
        self.commit_with_source_and_sync_ddl(tx, source, event_bus_ddl, &[])
    }

    fn commit_with_source_and_sync_ddl(
        &self,
        tx: TxId,
        source: CommitSource,
        event_bus_ddl: &[DdlChange],
        trigger_ddl: &[DdlChange],
    ) -> Result<CommitValidationOutcome> {
        self.commit_with_source_and_sync_ddl_and_trigger_audit_projection(
            tx,
            source,
            event_bus_ddl,
            trigger_ddl,
            None,
            None,
            false,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn commit_with_source_and_sync_ddl_and_trigger_audit_projection(
        &self,
        tx: TxId,
        source: CommitSource,
        event_bus_ddl: &[DdlChange],
        trigger_ddl: &[DdlChange],
        sync_pull_trigger_audit_projection: Option<&BTreeMap<String, TriggerDeclaration>>,
        sync_tombstones: Option<&[AcceptedSyncTombstone]>,
        sync_trigger_derived_rows_are_local: bool,
    ) -> Result<CommitValidationOutcome> {
        let pending_trigger_audits = std::cell::RefCell::new(Vec::new());
        let sync_pull_pre_trigger_creation_keys = std::cell::RefCell::new(HashSet::<String>::new());
        let sync_pull_pre_trigger_rows = std::cell::RefCell::new(HashSet::<(String, RowId)>::new());
        let pending_trigger_active_guards =
            std::cell::RefCell::new(Vec::<TriggerCallbackThreadGuard>::new());
        let mut pending_sink_events = Vec::new();
        // For a durable queue append this lease starts before the persistent
        // store consumes staged events and survives until their memory queue
        // publication. An authoritative purge's phase-two freeze therefore
        // cannot inventory a queue between those two halves of one commit.
        let pending_sink_queue_mutation =
            std::cell::RefCell::new(None::<event_bus::QueueMutationLease>);
        let mut committed_trigger_audit_entries = Vec::new();
        let in_memory_lineage_delta = std::cell::RefCell::new(None);
        let committed_graph_arrivals =
            std::cell::RefCell::new(Vec::<(GraphIdentity, DurableGraphArrival)>::new());
        let validation_noop_count = std::cell::Cell::new(0_u64);
        let pre_apply_index_maintenance_visits = std::cell::Cell::new(0_u64);
        #[cfg(feature = "test-seams")]
        let apply_started = std::cell::Cell::new(None::<Instant>);
        let delete_release_bytes = std::cell::RefCell::new(DeleteReleaseBytes::default());
        let sync_trigger_dispatch_required = source != CommitSource::SyncPull
            || self.has_matching_sync_trigger_for_tx(tx, sync_pull_trigger_audit_projection)?;
        let (lsn, ws) = {
            match self.tx_mgr.commit_with_lsn_active_prepare_and_applied_mut(
                tx,
                |lsn, visibility_tx| {
                    self.prepare_and_register_local_schema_stage(tx, visibility_tx, lsn)?;
                    // This observes the canonical staged write set before
                    // conditional-update revalidation can discard a stale
                    // descendant as a no-op. A purged lineage is a typed
                    // refusal, not an ordinary lost-update result.
                    self.tx_mgr
                        .with_write_set(tx, |ws| self.reject_purged_lineage_recreation(ws))??;
                    if sync_trigger_dispatch_required {
                        let outcome = match if source == CommitSource::SyncPull {
                            self.prepare_active_sync_trigger_write_set_for_dispatch(tx)
                        } else {
                            self.prepare_active_trigger_write_set_for_dispatch(tx)
                        } {
                            Ok(outcome) => outcome,
                            Err(error) => {
                                let reason = error.to_string();
                                let pending = pending_trigger_audits.borrow();
                                if !pending.is_empty() {
                                    self.append_rolled_back_trigger_audits(&pending, tx, &reason)?;
                                }
                                return Err(error);
                            }
                        };
                        Self::reject_user_conditional_update_conflicts(source, &outcome)?;
                        validation_noop_count.set(
                            validation_noop_count
                                .get()
                                .saturating_add(outcome.conditional_noop_count),
                        );
                        if source == CommitSource::SyncPull {
                            let (creation_keys, rows) = self.tx_mgr.with_write_set(tx, |ws| {
                                let creation_keys = ws
                                    .config_writes
                                    .iter()
                                    .filter(|(key, _)| key.starts_with("sync_creation_lineage.v1."))
                                    .map(|(key, _)| key.clone())
                                    .collect();
                                let rows = ws
                                    .relational_inserts
                                    .iter()
                                    .map(|(table, row)| (table.clone(), row.row_id))
                                    .collect();
                                (creation_keys, rows)
                            })?;
                            *sync_pull_pre_trigger_creation_keys.borrow_mut() = creation_keys;
                            *sync_pull_pre_trigger_rows.borrow_mut() = rows;
                        }
                        let dispatch = if source == CommitSource::SyncPull {
                            self.dispatch_sync_triggers_for_tx(
                                tx,
                                sync_pull_trigger_audit_projection,
                            )
                        } else {
                            self.dispatch_triggers_for_tx(tx)
                        };
                        match dispatch {
                            Ok(outcome) => {
                                *pending_trigger_audits.borrow_mut() = outcome.pending;
                                pending_trigger_active_guards
                                    .borrow_mut()
                                    .extend(outcome.active_guards);
                            }
                            Err(failure) => {
                                let failure = *failure;
                                pending_trigger_active_guards
                                    .borrow_mut()
                                    .extend(failure.active_guards);
                                return Err(failure.error);
                            }
                        }
                        if source == CommitSource::SyncPull && !sync_trigger_derived_rows_are_local
                        {
                            let pre_trigger_rows = sync_pull_pre_trigger_rows.borrow();
                            self.tx_mgr.with_write_set(tx, |ws| {
                                let derived_rows = ws
                                    .relational_inserts
                                    .iter()
                                    .filter(|(table, row)| {
                                        !pre_trigger_rows.contains(&(table.clone(), row.row_id))
                                    })
                                    .map(|(table, row)| (table.clone(), row.row_id))
                                    .collect::<Vec<_>>();
                                for (table, row_id) in derived_rows {
                                    ws.set_relational_insert_source_lsn(
                                        table,
                                        row_id,
                                        SYNC_SOURCE_LSN_OWN_COMMIT,
                                    );
                                }
                            })?;
                        }
                        let outcome = if source == CommitSource::SyncPull {
                            self.prepare_active_sync_trigger_write_set_for_dispatch(tx)?
                        } else {
                            self.prepare_active_trigger_write_set_for_dispatch(tx)?
                        };
                        Self::reject_user_conditional_update_conflicts(source, &outcome)?;
                        validation_noop_count.set(
                            validation_noop_count
                                .get()
                                .saturating_add(outcome.conditional_noop_count),
                        );
                    }
                    Ok(())
                },
                |ws| {
                    if !ws.is_empty() {
                        if source == CommitSource::SyncPull && sync_trigger_dispatch_required {
                            self.rewrite_txid_placeholders_for_rows_not_in(
                                tx,
                                ws,
                                &sync_pull_pre_trigger_rows.borrow(),
                            );
                        }
                        if source == CommitSource::SyncPull {
                            // A received row has only the authenticated wire
                            // sidecar staged by sync apply. Never leave local
                            // unbound creation evidence behind: after a later
                            // sidecar loss it could be rebound as a false
                            // local author.
                            let received_creation_keys =
                                sync_pull_pre_trigger_creation_keys.borrow();
                            ws.config_writes.retain(|(key, _)| {
                                if !key.starts_with("sync_creation_lineage.v1.") {
                                    return true;
                                }
                                sync_trigger_derived_rows_are_local
                                    && !received_creation_keys.contains(key)
                            });
                            // An authoritative hub owns callback-derived rows,
                            // so only that role retains and stamps post-snapshot
                            // creation evidence. An edge materialization stays
                            // Pulled and owns no new fleet creation identity.
                            self.stamp_unbound_creation_lineages_at_commit(ws)?;
                        } else {
                            self.stamp_unbound_creation_lineages_at_commit(ws)?;
                        }
                        if source != CommitSource::SyncPull {
                            self.rewrite_txid_placeholders(tx, ws)?;
                        }
                        self.reject_purged_lineage_recreation(ws)?;
                        let final_validation = self.commit_validate(tx, ws)?;
                        Self::reject_user_conditional_update_conflicts(source, &final_validation)?;
                        validation_noop_count.set(
                            validation_noop_count
                                .get()
                                .saturating_add(final_validation.conditional_noop_count),
                        );
                        *committed_graph_arrivals.borrow_mut() = self.stage_pulled_graph_arrivals(
                            ws,
                            source == CommitSource::SyncPull
                                && !sync_trigger_derived_rows_are_local,
                        )?;
                        if let Some(lsn) = ws.commit_lsn {
                            let trigger_ddl_start =
                                self.stage_event_bus_ddl_for_commit(lsn, event_bus_ddl)?;
                            if trigger_ddl_start != 0
                                && pending_sink_queue_mutation.borrow().is_none()
                            {
                                *pending_sink_queue_mutation.borrow_mut() =
                                    Some(self.event_bus.begin_queue_mutation());
                            }
                            self.stage_trigger_ddl_for_commit(lsn, trigger_ddl, trigger_ddl_start)?;
                        }
                        self.plugin.pre_commit(ws, source)?;
                        #[cfg(feature = "test-seams")]
                        let projection_started = Instant::now();
                        let prepared_sink_events = self
                            .prepare_sink_events_for_write_set_with_event_bus_ddl(
                                ws,
                                event_bus_ddl,
                            )?;
                        if self.persistence.is_some()
                            && let Some(lsn) = ws.commit_lsn
                        {
                            if !prepared_sink_events.is_empty() {
                                *pending_sink_queue_mutation.borrow_mut() =
                                    Some(self.event_bus.begin_queue_mutation());
                            }
                            self.event_bus
                                .stage_sink_events_for_persistence(lsn, prepared_sink_events);
                        } else {
                            pending_sink_events = prepared_sink_events;
                        }
                        if let Some(lsn) = ws.commit_lsn {
                            committed_trigger_audit_entries = if source == CommitSource::SyncPull {
                                let projected_declarations =
                                    self.staged_trigger_declarations_for_commit(lsn);
                                let audit_projection = sync_pull_trigger_audit_projection
                                    .or(projected_declarations.as_ref());
                                let mut entries = self
                                    .committed_sync_pull_trigger_audits_for_write_set(
                                        ws,
                                        lsn,
                                        audit_projection,
                                    )?;
                                entries.extend(self.committed_trigger_audits_for_pending(
                                    &pending_trigger_audits.borrow(),
                                    ws,
                                    lsn,
                                ));
                                entries
                            } else {
                                let pending = pending_trigger_audits.borrow();
                                self.committed_trigger_audits_for_pending(&pending, ws, lsn)
                            };
                            self.stage_trigger_audits_for_persistence(
                                lsn,
                                &committed_trigger_audit_entries,
                            );
                        }
                        #[cfg(feature = "test-seams")]
                        {
                            let delta = Instant::now()
                                .duration_since(projection_started)
                                .as_nanos()
                                .min(u128::from(u64::MAX))
                                as u64;
                            let mut stage_wall_nanos = [0; 7];
                            stage_wall_nanos[6] = delta;
                            self.add_commit_stage_stats(&CommitStageStats {
                                stage_wall_nanos: Some(stage_wall_nanos),
                                ..Default::default()
                            });
                        }
                        *delete_release_bytes.borrow_mut() =
                            self.delete_release_bytes_for_write_set(ws);
                        if self.persistence.is_none() {
                            *in_memory_lineage_delta.borrow_mut() =
                                Some(Self::prepare_in_memory_lineage_delta(&ws.config_writes)?);
                        }
                        pre_apply_index_maintenance_visits
                            .set(self.relational_store.index_maintenance_visits());
                        #[cfg(feature = "test-seams")]
                        apply_started.set(Some(Instant::now()));
                    }
                    if source == CommitSource::SyncPull
                        && self
                            .capture_detached_sync_write_set
                            .swap(false, Ordering::SeqCst)
                    {
                        *self.detached_sync_write_set.lock() = Some(ws.clone());
                    }
                    Ok(())
                },
                |lsn, ws| {
                    if !ws.is_empty() {
                        if let Some(stage) = self.take_local_schema_stage(lsn) {
                            self.publish_local_schema_stage(stage);
                        }
                        if let Some(delta) = in_memory_lineage_delta.borrow_mut().take() {
                            self.publish_in_memory_lineage_delta(delta);
                        }
                        if !committed_graph_arrivals.borrow().is_empty() {
                            self.sync_graph_arrivals
                                .write()
                                .extend(committed_graph_arrivals.borrow_mut().drain(..));
                        }
                        let index_maintenance_visits = self
                            .relational_store
                            .index_maintenance_visits()
                            .saturating_sub(pre_apply_index_maintenance_visits.get());
                        #[cfg(feature = "test-seams")]
                        let mut stats = CommitStageStats {
                            index_maintenance_visits,
                            ..Default::default()
                        };
                        #[cfg(not(feature = "test-seams"))]
                        let stats = CommitStageStats {
                            index_maintenance_visits,
                            ..Default::default()
                        };
                        #[cfg(feature = "test-seams")]
                        if let Some(started) = apply_started.get() {
                            let delta = Instant::now()
                                .duration_since(started)
                                .as_nanos()
                                .min(u128::from(u64::MAX))
                                as u64;
                            let mut stage_wall_nanos = [0; 7];
                            stage_wall_nanos[5] = delta;
                            stats.stage_wall_nanos = Some(stage_wall_nanos);
                        }
                        self.add_commit_stage_stats(&stats);
                        if pending_sink_queue_mutation.borrow().is_some() {
                            self.publish_staged_event_bus_ddl_commit_under_queue_mutation_lease(
                                lsn,
                            );
                        } else {
                            self.publish_staged_event_bus_ddl_commit(lsn);
                        }
                        self.publish_staged_trigger_ddl_commit(lsn);
                        if let Some(sync_tombstones) = sync_tombstones {
                            let mut tombstones = self.sync_tombstone_arrivals.write();
                            for (table, natural_key, arrival, kind, row_id) in sync_tombstones {
                                tombstones.insert(
                                    Self::sync_tombstone_key(table, natural_key),
                                    SyncTombstoneArrival {
                                        arrival: arrival.unwrap_or(lsn),
                                        delete_lsn: lsn,
                                        row_id: Some(*row_id),
                                        kind: *kind,
                                        accepted_local_order_invalidated: false,
                                    },
                                );
                            }
                        }
                        // DDL metadata mutation also needs the commit mutex.
                        // Release delete-side accounting here so DROP/RENAME
                        // cannot remove vector state before cleanup observes it.
                        self.release_delete_allocations_from_bytes(&delete_release_bytes.borrow());
                    }
                },
            ) {
                Ok(committed) => committed,
                Err(failure) => {
                    if let Some(ws) = failure.write_set.as_deref() {
                        self.plugin.commit_failed(ws, source, &failure.error);
                    }
                    if let Some(lsn) = failure.write_set.as_ref().and_then(|ws| ws.commit_lsn) {
                        // A received-schema stage is registered during
                        // active_prepare, before the ordinary mutable prepare
                        // callback. Drop it on either later prepare failure or
                        // Redb apply failure; PersistentCompositeStore also
                        // removes it on its own flush error.
                        let _ = self.take_received_schema_stage(lsn);
                        let _ = self.take_local_schema_stage(lsn);
                        let _ = self.event_bus.take_staged_sink_events_for_persistence(lsn);
                        self.discard_staged_event_bus_ddl_commit(lsn);
                        self.discard_staged_trigger_ddl_commit(lsn);
                        self.discard_staged_trigger_audits_for_persistence(lsn);
                    }
                    if let Some(ws) = &failure.write_set {
                        self.release_insert_allocations(ws);
                    }
                    if let Err(audit_error) = self.append_rolled_back_trigger_audits(
                        &pending_trigger_audits.borrow(),
                        tx,
                        &failure.error.to_string(),
                    ) {
                        self.pending_commit_metadata.lock().remove(&tx);
                        return Err(audit_error);
                    }
                    self.pending_commit_metadata.lock().remove(&tx);
                    self.pending_local_schema_stages.lock().remove(&tx);
                    return Err(failure.error);
                }
            }
        };
        self.pending_commit_metadata.lock().remove(&tx);

        if !ws.is_empty() {
            self.plugin.post_commit(&ws, source);
            let sink_events_to_publish = if self.persistence.is_some() {
                ws.commit_lsn
                    .and_then(|lsn| self.event_bus.take_staged_sink_events_for_persistence(lsn))
                    .map(EventBusState::materialize_staged_sink_events)
                    .unwrap_or_default()
            } else {
                pending_sink_events
            };
            if pending_sink_queue_mutation.borrow().is_some() {
                self.publish_prepared_sink_events_to_memory_under_queue_mutation_lease(
                    sink_events_to_publish,
                );
            } else {
                self.publish_prepared_sink_events_to_memory(sink_events_to_publish);
            }
            drop(pending_sink_queue_mutation.borrow_mut().take());
            self.append_trigger_audits_to_memory(committed_trigger_audit_entries);
            self.publish_commit_event_if_subscribers(&ws, source, lsn);
        } else {
            if !event_bus_ddl.is_empty() {
                self.apply_event_bus_ddl_batch(event_bus_ddl.to_vec())?;
            }
            if !trigger_ddl.is_empty() {
                self.apply_trigger_ddl_batch(trigger_ddl.to_vec())?;
            }
        }

        Ok(CommitValidationOutcome {
            conditional_noop_count: validation_noop_count.get(),
            conditional_conflict_count: 0,
        })
    }

    fn reject_user_conditional_update_conflicts(
        source: CommitSource,
        outcome: &CommitValidationOutcome,
    ) -> Result<()> {
        if source == CommitSource::User && outcome.conditional_conflict_count > 0 {
            return Err(Error::ConditionalUpdateConflict {
                count: outcome.conditional_conflict_count,
            });
        }
        Ok(())
    }

    fn build_commit_event(
        ws: &contextdb_tx::WriteSet,
        source: CommitSource,
        lsn: Lsn,
    ) -> CommitEvent {
        let mut tables_changed: Vec<String> = ws
            .relational_inserts
            .iter()
            .map(|(table, _)| table.clone())
            .chain(
                ws.relational_deletes
                    .iter()
                    .map(|(table, _, _)| table.clone()),
            )
            .chain(
                ws.vector_inserts
                    .iter()
                    .map(|entry| entry.index.table.clone()),
            )
            .chain(
                ws.vector_deletes
                    .iter()
                    .map(|(index, _, _)| index.table.clone()),
            )
            .chain(
                ws.vector_moves
                    .iter()
                    .map(|(index, _, _, _)| index.table.clone()),
            )
            .collect::<HashSet<_>>()
            .into_iter()
            .collect();
        tables_changed.sort();

        let relational_row_count = ws
            .relational_inserts
            .iter()
            .map(|(table, row)| (table.clone(), row.row_id))
            .chain(
                ws.relational_deletes
                    .iter()
                    .map(|(table, row_id, _)| (table.clone(), *row_id)),
            )
            .collect::<HashSet<_>>()
            .len();

        CommitEvent {
            source,
            lsn,
            tables_changed,
            row_count: relational_row_count
                + ws.adj_inserts.len()
                + ws.adj_deletes.len()
                + ws.vector_inserts.len()
                + ws.vector_deletes.len()
                + ws.vector_moves.len(),
        }
    }

    fn publish_commit_event_if_subscribers(
        &self,
        ws: &contextdb_tx::WriteSet,
        source: CommitSource,
        lsn: Lsn,
    ) {
        let mut subscriptions = self.subscriptions.lock();
        if subscriptions.subscribers.is_empty() {
            return;
        }
        let event = Self::build_commit_event(ws, source, lsn);
        let subscribers = std::mem::take(&mut subscriptions.subscribers);
        let mut live_subscribers = Vec::with_capacity(subscribers.len());

        for sender in subscribers {
            match sender.try_send(event.clone()) {
                Ok(()) => {
                    subscriptions.events_sent += 1;
                    live_subscribers.push(sender);
                }
                Err(TrySendError::Full(_)) => {
                    subscriptions.events_dropped += 1;
                    live_subscribers.push(sender);
                }
                Err(TrySendError::Disconnected(_)) => {}
            }
        }

        subscriptions.subscribers = live_subscribers;
    }

    fn stop_pruning_thread(&self) {
        let handle = {
            let mut runtime = self.pruning_runtime.lock();
            runtime.shutdown.store(true, Ordering::SeqCst);
            let handle = runtime.handle.take();
            runtime.shutdown = Arc::new(AtomicBool::new(false));
            handle
        };

        if let Some(handle) = handle {
            let _ = handle.join();
        }
    }

    fn execute_statement_with_plan(
        &self,
        stmt: &Statement,
        sql: &str,
        params: &HashMap<String, Value>,
        tx: Option<TxId>,
        cached_plan: Option<&PhysicalPlan>,
        mut preopened_autocommit_tx: Option<TxId>,
    ) -> Result<QueryResult> {
        if let Err(error) = self.plugin.on_query(sql) {
            self.rollback_preopened_autocommit_tx(preopened_autocommit_tx.take());
            return Err(error);
        }

        let started = Instant::now();
        // Authenticated sync applies already run against their own private
        // received-schema image and intentionally combine one source DDL
        // vector with its rows. Keep that established atomic path in the
        // ordinary executor; this local authoring stage is only for caller
        // transactions.
        if let Some(tx) = tx
            && Self::is_staged_local_schema_statement(stmt)
            && !self.sync_apply_local_schema_bypass_active(tx)
        {
            let result = self.stage_local_schema_statement(tx, stmt, sql);
            let outcome = query_outcome_from_result(&result);
            self.plugin.post_query(sql, started.elapsed(), &outcome);
            return result;
        }
        if let Some(change) = self.ddl_change_for_statement(stmt, tx).as_ref()
            && let Err(error) = self.plugin.on_ddl(change)
        {
            self.rollback_preopened_autocommit_tx(preopened_autocommit_tx.take());
            return Err(error);
        }
        if let Some(tx) = tx
            && Self::is_local_table_schema_statement(stmt)
            && !self.sync_apply_local_schema_bypass_active(tx)
        {
            let result = Err(Error::Other(
                "transactional local schema staging currently supports only CREATE TABLE and ALTER TABLE ADD COLUMN; commit or roll back before using another table-schema operation"
                    .to_string(),
            ));
            let outcome = query_outcome_from_result(&result);
            self.plugin.post_query(sql, started.elapsed(), &outcome);
            return result;
        }
        if let Some(result) = self.execute_event_bus_statement(stmt, tx) {
            self.rollback_preopened_autocommit_tx(preopened_autocommit_tx.take());
            let outcome = query_outcome_from_result(&result);
            self.plugin.post_query(sql, started.elapsed(), &outcome);
            return result;
        }

        // Handle INSERT INTO GRAPH / __edges as a virtual table routing to the graph store.
        if let Statement::Insert(ins) = stmt
            && (ins.table.eq_ignore_ascii_case("GRAPH")
                || ins.table.eq_ignore_ascii_case("__edges"))
        {
            return self.execute_graph_insert(ins, params, tx, preopened_autocommit_tx.take());
        }

        let result = (|| {
            if let Some(plan) = cached_plan {
                let skip_static_dml_validation =
                    matches!(plan, PhysicalPlan::Update(_) | PhysicalPlan::Delete(_));
                return self.run_planned_statement(
                    stmt,
                    plan,
                    params,
                    tx,
                    preopened_autocommit_tx.take(),
                    skip_static_dml_validation,
                );
            }

            let (stmt, plan) = {
                // Pre-resolve InSubquery expressions with CTE context before planning.
                let stmt = self.pre_resolve_cte_subqueries(stmt, params, tx)?;
                let plan = contextdb_planner::plan(&stmt)?;
                self.cache_statement_if_eligible(sql, &stmt, &plan);
                (stmt, plan)
            };
            self.run_planned_statement(
                &stmt,
                &plan,
                params,
                tx,
                preopened_autocommit_tx.take(),
                false,
            )
        })();
        if result.is_err() {
            self.rollback_preopened_autocommit_tx(preopened_autocommit_tx.take());
        }
        let duration = started.elapsed();
        let outcome = query_outcome_from_result(&result);
        self.plugin.post_query(sql, duration, &outcome);
        result.map(strip_internal_row_id)
    }

    fn execute_event_bus_statement(
        &self,
        stmt: &Statement,
        tx: Option<TxId>,
    ) -> Option<Result<QueryResult>> {
        if !matches!(
            stmt,
            Statement::CreateEventType { .. }
                | Statement::CreateSink { .. }
                | Statement::CreateRoute { .. }
                | Statement::DropRoute { .. }
        ) {
            return None;
        }
        let change = self
            .ddl_change_for_statement(stmt, tx)
            .expect("event bus statement has DDL change");
        Some(match tx {
            Some(tx) => self
                .stage_event_bus_ddl_in_tx(tx, change)
                .map(|()| QueryResult::empty()),
            None => self
                .apply_event_bus_ddl_from_user(vec![change])
                .map(|()| QueryResult::empty()),
        })
    }

    fn run_planned_statement(
        &self,
        stmt: &Statement,
        plan: &PhysicalPlan,
        params: &HashMap<String, Value>,
        tx: Option<TxId>,
        preopened_autocommit_tx: Option<TxId>,
        skip_static_dml_validation: bool,
    ) -> Result<QueryResult> {
        if let Some(tx) = tx
            && matches!(
                plan,
                PhysicalPlan::Insert(_) | PhysicalPlan::Delete(_) | PhysicalPlan::Update(_)
            )
            && self.pending_local_schema_stages.lock().contains_key(&tx)
        {
            self.rollback_preopened_autocommit_tx(preopened_autocommit_tx);
            return Err(Error::Other(
                "mixed DML and transactional local schema DDL is not supported; commit or roll back before writing rows"
                    .to_string(),
            ));
        }
        if !skip_static_dml_validation && let Err(error) = validate_dml(plan, self, params) {
            self.rollback_preopened_autocommit_tx(preopened_autocommit_tx);
            return Err(error);
        }
        // Catalog validation for every column the plan names, before any row is
        // read. Sits with the existing static DML check so both plan-time
        // refusals happen at one seam.
        if let Err(error) = validate_plan_columns(self, plan) {
            self.rollback_preopened_autocommit_tx(preopened_autocommit_tx);
            return Err(error);
        }
        let result = match tx {
            Some(tx) => {
                let _write_gate = if self.trigger_callback_tx_bound_matches(tx) {
                    None
                } else {
                    Some(self.enter_sql_write_control_bypass(tx))
                };
                let snapshot = self.snapshot_for_read();
                self.with_snapshot_override(snapshot, || execute_plan(self, plan, params, Some(tx)))
            }
            None => self.execute_autocommit(plan, params, preopened_autocommit_tx),
        };
        if result.is_ok()
            && let Statement::CreateTable(ct) = stmt
            && !ct.dag_edge_types.is_empty()
        {
            self.graph.register_dag_edge_types(&ct.dag_edge_types);
        }
        result
    }

    /// Handle `INSERT INTO GRAPH (source_id, target_id, edge_type) VALUES (...)`.
    fn execute_graph_insert(
        &self,
        ins: &contextdb_parser::ast::Insert,
        params: &HashMap<String, Value>,
        tx: Option<TxId>,
        preopened_autocommit_tx: Option<TxId>,
    ) -> Result<QueryResult> {
        use crate::executor::resolve_expr;

        let col_index = |name: &str| {
            ins.columns
                .iter()
                .position(|c| c.eq_ignore_ascii_case(name))
        };
        let source_idx = col_index("source_id")
            .ok_or_else(|| Error::PlanError("GRAPH INSERT requires source_id column".into()))?;
        let target_idx = col_index("target_id")
            .ok_or_else(|| Error::PlanError("GRAPH INSERT requires target_id column".into()))?;
        let edge_type_idx = col_index("edge_type")
            .ok_or_else(|| Error::PlanError("GRAPH INSERT requires edge_type column".into()))?;

        let auto_commit = tx.is_none();
        let tx = match tx {
            Some(tx) => tx,
            None => match preopened_autocommit_tx {
                Some(tx) => tx,
                None => self.begin_for_public_autocommit_write()?,
            },
        };
        let result = {
            let _write_gate = self.enter_sql_write_control_bypass(tx);
            (|| {
                let mut count = 0u64;
                for row_exprs in &ins.values {
                    let source = resolve_expr(&row_exprs[source_idx], params)?;
                    let target = resolve_expr(&row_exprs[target_idx], params)?;
                    let edge_type = resolve_expr(&row_exprs[edge_type_idx], params)?;

                    let source_uuid = match &source {
                        Value::Uuid(u) => *u,
                        Value::Text(t) => uuid::Uuid::parse_str(t).map_err(|e| {
                            Error::PlanError(format!("invalid source_id uuid: {e}"))
                        })?,
                        _ => return Err(Error::PlanError("source_id must be UUID".into())),
                    };
                    let target_uuid = match &target {
                        Value::Uuid(u) => *u,
                        Value::Text(t) => uuid::Uuid::parse_str(t).map_err(|e| {
                            Error::PlanError(format!("invalid target_id uuid: {e}"))
                        })?,
                        _ => return Err(Error::PlanError("target_id must be UUID".into())),
                    };
                    let edge_type_str = match &edge_type {
                        Value::Text(t) => t.clone(),
                        _ => return Err(Error::PlanError("edge_type must be TEXT".into())),
                    };

                    self.insert_edge(
                        tx,
                        source_uuid,
                        target_uuid,
                        edge_type_str,
                        Default::default(),
                    )?;
                    count += 1;
                }
                Ok(count)
            })()
        };

        let count = match result {
            Ok(count) => count,
            Err(error) => {
                if auto_commit {
                    let _ = self.rollback_without_callback_tx_control(tx);
                }
                return Err(error);
            }
        };

        if auto_commit {
            self.commit_with_source(tx, CommitSource::AutoCommit)?;
        }

        Ok(QueryResult::empty_with_affected(count))
    }

    fn ddl_change_for_statement(&self, stmt: &Statement, tx: Option<TxId>) -> Option<DdlChange> {
        match stmt {
            Statement::CreateTable(ct) => Some(ddl_change_from_create_table(ct)),
            Statement::DropTable(dt) => Some(DdlChange::DropTable {
                name: dt.name.clone(),
            }),
            Statement::AlterTable(at) => {
                let mut meta = self.table_meta(&at.table).unwrap_or_default();
                // Simulate the alter action on a cloned meta to get post-alteration columns
                match &at.action {
                    AlterAction::AddColumn(col) => {
                        meta.columns.push(contextdb_core::ColumnDef {
                            name: col.name.clone(),
                            column_type: crate::executor::map_column_type(&col.data_type),
                            nullable: col.nullable,
                            primary_key: col.primary_key,
                            unique: col.unique,
                            default: col
                                .default
                                .as_ref()
                                .map(crate::executor::stored_default_expr),
                            references: col.references.as_ref().map(|reference| {
                                contextdb_core::ForeignKeyReference {
                                    table: reference.table.clone(),
                                    column: reference.column.clone(),
                                }
                            }),
                            expires: col.expires,
                            immutable: col.immutable,
                            quantization: match col.quantization {
                                contextdb_parser::ast::VectorQuantization::F32 => {
                                    contextdb_core::VectorQuantization::F32
                                }
                                contextdb_parser::ast::VectorQuantization::SQ8 => {
                                    contextdb_core::VectorQuantization::SQ8
                                }
                                contextdb_parser::ast::VectorQuantization::SQ4 => {
                                    contextdb_core::VectorQuantization::SQ4
                                }
                            },
                            rank_policy: col
                                .rank_policy
                                .as_deref()
                                .map(crate::executor::map_rank_policy),
                            context_id: col.context_id,
                            scope_label: col.scope_label.as_deref().map(|scope| match scope {
                                contextdb_parser::ast::ScopeLabelConstraint::Simple { labels } => {
                                    contextdb_core::ScopeLabelKind::Simple {
                                        write_labels: labels.clone(),
                                    }
                                }
                                contextdb_parser::ast::ScopeLabelConstraint::Split {
                                    read,
                                    write,
                                } => contextdb_core::ScopeLabelKind::Split {
                                    read_labels: read.clone(),
                                    write_labels: write.clone(),
                                },
                            }),
                            acl_ref: col.acl_ref.as_ref().map(|acl| contextdb_core::AclRef {
                                ref_table: acl.ref_table.clone(),
                                ref_column: acl.ref_column.clone(),
                            }),
                        });
                        if col.expires {
                            meta.expires_column = Some(col.name.clone());
                        }
                    }
                    AlterAction::DropColumn {
                        column: name,
                        cascade: _,
                    } => {
                        meta.columns.retain(|c| c.name != *name);
                        if meta.expires_column.as_deref() == Some(name.as_str()) {
                            meta.expires_column = None;
                        }
                    }
                    AlterAction::RenameColumn { from, to } => {
                        if let Some(c) = meta.columns.iter_mut().find(|c| c.name == *from) {
                            c.name = to.clone();
                        }
                        if meta.expires_column.as_deref() == Some(from.as_str()) {
                            meta.expires_column = Some(to.clone());
                        }
                    }
                    AlterAction::SetRetain {
                        duration_seconds,
                        sync_safe,
                        declared_unit,
                    } => {
                        // The execution path refuses a delivery promise the
                        // table's direction could never keep, so the projection
                        // must not hand a plugin a statement about to be
                        // rejected.
                        if crate::executor::refuse_promise_with_no_delivery(
                            &at.table,
                            *sync_safe,
                            Some(crate::executor::effective_sync_direction(&meta)),
                        )
                        .is_err()
                        {
                            return None;
                        }
                        meta.default_ttl_seconds = Some(*duration_seconds);
                        meta.sync_safe = *sync_safe;
                        meta.retain_declared_unit = Some(*declared_unit);
                    }
                    AlterAction::DropRetain => {
                        meta.default_ttl_seconds = None;
                        meta.sync_safe = false;
                        meta.retain_declared_unit = None;
                    }
                    AlterAction::SetSyncDirection(direction) => {
                        if crate::executor::refuse_promise_with_no_delivery(
                            &at.table,
                            meta.sync_safe,
                            Some(*direction),
                        )
                        .is_err()
                        {
                            return None;
                        }
                        meta.sync_direction = Some(*direction);
                    }
                    AlterAction::SetHistory(policy) => {
                        meta.history_policy = Some(*policy);
                    }
                    AlterAction::SetSyncConflict(policy) => {
                        meta.conflict_policy = Some(*policy);
                    }
                }
                Some(DdlChange::AlterTable {
                    name: at.table.clone(),
                    columns: meta
                        .columns
                        .iter()
                        .map(|c| {
                            (
                                c.name.clone(),
                                sql_type_for_meta_column(c, &meta.propagation_rules),
                            )
                        })
                        .collect(),
                    constraints: create_table_constraints_from_meta(&meta),
                    foreign_keys: single_column_foreign_keys_from_meta(&meta, &HashSet::new()),
                    composite_foreign_keys: meta.composite_foreign_keys.clone(),
                    composite_unique: meta.unique_constraints.clone(),
                })
            }
            Statement::CreateEventType { name, when, table } => Some(DdlChange::CreateEventType {
                name: name.clone(),
                trigger: match when {
                    contextdb_parser::ast::EventTypeTrigger::Insert => "INSERT",
                    contextdb_parser::ast::EventTypeTrigger::Update => "UPDATE",
                    contextdb_parser::ast::EventTypeTrigger::Delete => "DELETE",
                }
                .to_string(),
                table: table.clone(),
            }),
            Statement::CreateTrigger {
                name,
                table,
                on_events,
                including_sync,
            } => {
                let on_events = on_events
                    .iter()
                    .map(|event| match event {
                        contextdb_parser::ast::TriggerEvent::Insert => "INSERT",
                        contextdb_parser::ast::TriggerEvent::Update => "UPDATE",
                        contextdb_parser::ast::TriggerEvent::Delete => "DELETE",
                    })
                    .map(str::to_string)
                    .collect();
                Some(if *including_sync {
                    DdlChange::CreateTriggerIncludingSync {
                        name: name.clone(),
                        table: table.clone(),
                        on_events,
                    }
                } else {
                    DdlChange::CreateTrigger {
                        name: name.clone(),
                        table: table.clone(),
                        on_events,
                    }
                })
            }
            Statement::DropTrigger { name } => Some(DdlChange::DropTrigger { name: name.clone() }),
            Statement::CreateSink {
                name,
                sink_type,
                url,
            } => Some(DdlChange::CreateSink {
                name: name.clone(),
                sink_type: match sink_type {
                    contextdb_parser::ast::SinkType::Webhook => "WEBHOOK",
                    contextdb_parser::ast::SinkType::Callback => "CALLBACK",
                }
                .to_string(),
                url: url.clone(),
            }),
            Statement::CreateRoute {
                name,
                event_type,
                sink,
                where_in,
            } => Some(DdlChange::CreateRoute {
                name: name.clone(),
                event_type: event_type.clone(),
                sink: sink.clone(),
                table: self
                    .event_bus_table_for_event_type_with_pending(tx, event_type)
                    .unwrap_or_default(),
                where_in: where_in
                    .as_ref()
                    .map(|where_in| (where_in.column.clone(), where_in.values.clone())),
            }),
            Statement::DropRoute { name } => Some(DdlChange::DropRoute {
                name: name.clone(),
                table: self
                    .event_bus_table_for_route_with_pending(tx, name)
                    .unwrap_or_default(),
            }),
            _ => None,
        }
    }

    /// Pre-resolve InSubquery expressions within SELECT statements that have CTEs.
    /// This allows CTE-backed subqueries in WHERE clauses to be evaluated before planning.
    fn pre_resolve_cte_subqueries(
        &self,
        stmt: &Statement,
        params: &HashMap<String, Value>,
        tx: Option<TxId>,
    ) -> Result<Statement> {
        if let Statement::Select(sel) = stmt
            && !sel.ctes.is_empty()
            && sel.body.where_clause.is_some()
        {
            use crate::executor::resolve_in_subqueries_with_ctes;
            let resolved_where = sel
                .body
                .where_clause
                .as_ref()
                .map(|expr| resolve_in_subqueries_with_ctes(self, expr, params, tx, &sel.ctes))
                .transpose()?;
            let mut new_body = sel.body.clone();
            new_body.where_clause = resolved_where;
            Ok(Statement::Select(contextdb_parser::ast::SelectStatement {
                ctes: sel.ctes.clone(),
                body: new_body,
            }))
        } else {
            Ok(stmt.clone())
        }
    }

    pub fn insert_row(
        &self,
        tx: TxId,
        table: &str,
        values: HashMap<ColName, Value>,
    ) -> Result<RowId> {
        self.ensure_no_mixed_local_schema_dml(tx)?;
        let trigger_callback_bound = self.trigger_callback_tx_bound_matches(tx);
        let _operation = if trigger_callback_bound {
            None
        } else {
            Some(self.open_operation_after_write_control_wait(tx, "insert_row")?)
        };
        if !trigger_callback_bound || !self.trigger.ready.load(Ordering::SeqCst) {
            self.ensure_trigger_table_ready(table, "insert_row")?;
        }
        // Statement-scoped bound: `Value::TxId(n)` must satisfy
        // `n <= max(committed_watermark, tx)` so writes inside an active
        // transaction can reference their own allocated TxId. The error,
        // when fired, still reports `committed_watermark` per plan B7.
        let mut values =
            self.coerce_row_for_insert(table, values, Some(self.committed_watermark()), Some(tx))?;
        self.complete_insert_access_values(table, &mut values)?;
        self.validate_primary_key_values_present(table, &values)?;
        let creation_key = self
            .table_meta(table)
            .and_then(|meta| natural_key_from_row_values(&meta, &values));
        if !trigger_callback_bound {
            self.validate_row_constraints(tx, table, &values, None)?;
        }
        if trigger_callback_bound && !self.has_access_constraints_for_query() {
            let has_state_machine = self.trigger_insert_table_has_state_machine(table)?;
            let row_id = self.relational_store.new_row_id();
            self.assert_row_write_allowed(table, row_id, &values, self.snapshot_for_read())?;
            if !has_state_machine {
                let inserted = self
                    .relational
                    .insert_with_row_id_assume_no_state_machine_at(
                        tx,
                        table,
                        row_id,
                        values,
                        self.trigger_callback_wallclock(),
                    )?;
                if let Some(key) = creation_key {
                    self.stage_local_creation_lineage(tx, table, key, inserted)?;
                }
                return Ok(inserted);
            }
            let inserted = self.relational.insert_with_row_id(
                tx,
                table,
                row_id,
                values,
                self.snapshot_for_read(),
            )?;
            if let Some(key) = creation_key {
                self.stage_local_creation_lineage(tx, table, key, inserted)?;
            }
            return Ok(inserted);
        }
        let row_id = self.relational_store.new_row_id();
        self.assert_row_write_allowed(table, row_id, &values, self.snapshot_for_read())?;
        let inserted = self.relational.insert_with_row_id(
            tx,
            table,
            row_id,
            values,
            self.snapshot_for_read(),
        )?;
        if let Some(key) = creation_key {
            self.stage_local_creation_lineage(tx, table, key, inserted)?;
        }
        Ok(inserted)
    }

    /// UPDATE-aware insert: the UPDATE path first deletes the old row and
    /// then re-inserts. The constraint probe must skip the old row_id so the
    /// same PK does not self-collide. The old row's index entry still looks
    /// visible at the committed-watermark snapshot because its `deleted_tx`
    /// equals the current (uncommitted) `tx`.
    pub(crate) fn insert_row_replacing(
        &self,
        tx: TxId,
        table: &str,
        values: HashMap<ColName, Value>,
        old_row_id: RowId,
    ) -> Result<RowId> {
        self.ensure_trigger_table_ready(table, "insert_row_replacing")?;
        let mut values =
            self.coerce_row_for_insert(table, values, Some(self.committed_watermark()), Some(tx))?;
        self.complete_insert_access_values(table, &mut values)?;
        self.validate_primary_key_values_present(table, &values)?;
        if !self.trigger_callback_tx_bound_matches(tx) {
            self.validate_row_constraints(tx, table, &values, Some(old_row_id))?;
        }
        self.assert_row_write_allowed(table, old_row_id, &values, self.snapshot_for_read())?;
        self.relational
            .insert_with_row_id(tx, table, old_row_id, values, self.snapshot_for_read())
    }

    pub(crate) fn replace_row_after_update_validation(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
        values: HashMap<ColName, Value>,
        snapshot: SnapshotId,
    ) -> Result<RowId> {
        self.validate_primary_key_values_present(table, &values)?;
        self.relational.delete(tx, table, row_id)?;
        self.relational
            .insert_with_row_id(tx, table, row_id, values, snapshot)
    }

    pub(crate) fn replace_row_after_update_validation_counted(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
        values: HashMap<ColName, Value>,
        context: UpdateReplacementContext<'_>,
    ) -> Result<(RowId, WriteSetCounts, WriteSetCounts)> {
        self.validate_primary_key_values_present(table, &values)?;
        if context.meta.immutable {
            return Err(Error::ImmutableTable(table.to_string()));
        }
        let table_name = table.to_string();
        let row = VersionedRow {
            row_id,
            values,
            created_tx: tx,
            deleted_tx: None,
            lsn: Lsn(0),
            created_at: Some(context.created_at),
        };
        self.tx_mgr.with_write_set(tx, |ws| {
            let before = current_write_set_counts(ws);
            ws.relational_inserts.retain(|(staged_table, staged_row)| {
                !(staged_table == &table_name && staged_row.row_id == row_id)
            });
            if context.committed_row_exists
                && !ws
                    .relational_deletes
                    .iter()
                    .any(|(delete_table, deleted_row_id, _)| {
                        delete_table == &table_name && *deleted_row_id == row_id
                    })
            {
                ws.relational_deletes.push((table_name.clone(), row_id, tx));
            }
            ws.relational_inserts.push((table_name, row));
            let after = current_write_set_counts(ws);
            (row_id, before, after)
        })
    }

    /// Internal variant used by sync-apply: skips the TXID bound check because
    /// peer TxIds may legitimately exceed the local watermark. Still enforces
    /// wrong-variant + reverse-direction TXID column rules.
    /// Insert a row that arrived over sync. `created_at` is the birth time the
    /// row carried from the node that wrote it: retention judges a row by that
    /// stamp against the holder's own clock, so a replicated row keeps its age
    /// instead of being handed a fresh window on arrival. `None` (an origin
    /// that recorded no stamp) falls back to stamping the row here.
    pub(crate) fn insert_row_for_sync(
        &self,
        tx: TxId,
        table: &str,
        values: HashMap<ColName, Value>,
        created_at: Option<Wallclock>,
    ) -> Result<RowId> {
        let values = self.coerce_row_for_insert(table, values, None, None)?;
        self.validate_row_constraints(tx, table, &values, None)?;
        let row_id = self.relational_store.new_row_id();
        self.assert_row_write_allowed(table, row_id, &values, self.snapshot())?;
        match created_at {
            Some(created_at) => self.relational.insert_with_row_id_at(
                tx,
                table,
                row_id,
                values,
                self.snapshot(),
                created_at,
            ),
            None => self
                .relational
                .insert_with_row_id(tx, table, row_id, values, self.snapshot()),
        }
    }

    /// Upsert a row that arrived over sync. See [`Self::insert_row_for_sync`]
    /// for what `created_at` carries and why.
    pub(crate) fn upsert_row_for_sync(
        &self,
        tx: TxId,
        table: &str,
        natural_key: &NaturalKey,
        values: HashMap<ColName, Value>,
        created_at: Option<Wallclock>,
    ) -> Result<UpsertResult> {
        let values = self.coerce_row_for_insert(table, values, None, None)?;
        let snapshot = self.snapshot_for_read();
        // Resolve the existing row on the WHOLE natural key — every key column —
        // so a composite identity is matched in full rather than collapsed onto a
        // leading-column probe that resolves the wrong row and drops the update.
        // A single-column key routes through the same point lookup as before.
        let key_columns = natural_key.key_columns();
        let key_values: Option<Vec<Value>> = key_columns
            .iter()
            .map(|column| values.get(column).cloned())
            .collect();
        let existing_row = match key_values {
            Some(key_values) => {
                self.conflict_lookup_in_tx(tx, table, &key_columns, &key_values, snapshot)?
            }
            None => None,
        };
        let existing_row_id = existing_row.as_ref().map(|row| row.row_id);

        if let (Some(existing), Some(meta)) = (existing_row.as_ref(), self.table_meta(table)) {
            for col_def in meta.columns.iter().filter(|c| c.immutable) {
                let Some(incoming) = values.get(&col_def.name) else {
                    continue;
                };
                let existing_value = existing.values.get(&col_def.name);
                if existing_value != Some(incoming) {
                    return Err(Error::ImmutableColumn {
                        table: table.to_string(),
                        column: col_def.name.clone(),
                    });
                }
            }
        }

        self.validate_row_constraints(tx, table, &values, existing_row_id)?;

        let row_uuid = values.get("id").and_then(Value::as_uuid).copied();
        let meta = self.table_meta(table);
        let new_state = meta
            .as_ref()
            .and_then(|m| m.state_machine.as_ref())
            .and_then(|sm| values.get(&sm.column))
            .and_then(Value::as_text)
            .map(std::borrow::ToOwned::to_owned);

        if let Some(existing) = existing_row.as_ref() {
            self.assert_row_write_allowed(table, existing.row_id, &existing.values, snapshot)?;
            self.assert_row_write_allowed(table, existing.row_id, &values, snapshot)?;
            let changed = values
                .iter()
                .any(|(column, value)| existing.values.get(column) != Some(value));
            if !changed {
                return Ok(UpsertResult::NoOp);
            }
            // Sync carries a complete row, including its current state.  A
            // scalar-only change must not be treated as an explicit
            // `state = state` transition: local SQL keeps that stricter
            // contract and validates an assigned state column separately.
            let state_text_pair = meta
                .as_ref()
                .and_then(|table_meta| table_meta.state_machine.as_ref())
                .map(|state_machine| {
                    (
                        existing
                            .values
                            .get(&state_machine.column)
                            .and_then(Value::as_text),
                        values.get(&state_machine.column).and_then(Value::as_text),
                    )
                });
            let carried_state_unchanged_text = matches!(
                state_text_pair,
                Some((Some(old_state), Some(incoming_state))) if old_state == incoming_state
            );
            let state_changed_text = matches!(
                state_text_pair,
                Some((Some(old_state), Some(incoming_state))) if old_state != incoming_state
            );
            // An absent or malformed state is never a no-op: it must retain
            // the normal validator/constraint path. Only two equal text
            // values mean sync carried the existing state unchanged.
            if !carried_state_unchanged_text {
                self.validate_commit_time_upsert_state_transition(table, existing, &values)?;
            }
            self.relational.delete(tx, table, existing.row_id)?;
            self.insert_synced_row_at(tx, table, existing.row_id, values, snapshot, created_at)?;
            if state_changed_text
                && let (Some(uuid), Some(state), Some(_meta)) =
                    (row_uuid, new_state.as_deref(), meta.as_ref())
            {
                self.propagate_state_change_if_needed(tx, table, Some(uuid), Some(state))?;
            }
            return Ok(UpsertResult::Updated);
        }

        let row_id = self.relational_store.new_row_id();
        self.assert_row_write_allowed(table, row_id, &values, snapshot)?;
        self.insert_synced_row_at(tx, table, row_id, values, snapshot, created_at)?;
        if let (Some(uuid), Some(state), Some(_meta)) =
            (row_uuid, new_state.as_deref(), meta.as_ref())
        {
            self.propagate_state_change_if_needed(tx, table, Some(uuid), Some(state))?;
        }
        Ok(UpsertResult::Inserted)
    }

    /// Stage a synced row, honouring the birth time it carried when it has
    /// one and stamping locally when it does not.
    fn insert_synced_row_at(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
        values: HashMap<ColName, Value>,
        snapshot: SnapshotId,
        created_at: Option<Wallclock>,
    ) -> Result<RowId> {
        self.validate_primary_key_values_present(table, &values)?;
        match created_at {
            Some(created_at) => self
                .relational
                .insert_with_row_id_at(tx, table, row_id, values, snapshot, created_at),
            None => self
                .relational
                .insert_with_row_id(tx, table, row_id, values, snapshot),
        }
    }

    /// Whether this table's row for `natural_key` currently holds a version
    /// that ARRIVED over sync rather than one written here. The marker is set
    /// when a sync apply stages the row and cleared by any local write to it
    /// (see `sync_source_lsn_updates`), so it describes the CURRENT version,
    /// never the row's history: a pulled row that was then edited locally
    /// reads `false`.
    pub fn row_version_arrived_by_sync(&self, table: &str, natural_key: &NaturalKey) -> bool {
        let _operation = self.assert_open_operation();
        let Some(row_id) =
            self.row_id_for_natural_key_full(table, natural_key, self.snapshot_for_read())
        else {
            return false;
        };
        self.relational_store
            .sync_source_kind(table, row_id)
            .is_some_and(|kind| matches!(kind, contextdb_relational::store::SyncSourceKind::Pulled))
    }

    sync_test_seam! {
    #[cfg(any(test, feature = "test-seams"))]
    /// Mark one existing live row as a pulled arrival without constructing a
    /// synthetic wire apply. Production-dead: destination-move tests use this
    /// to isolate echo selection from the independently authenticated lineage
    /// contract exercised by the transport journey.
    #[doc(hidden)]
    fn mark_row_arrived_by_sync_for_test(
        &self,
        table: &str,
        natural_key: &NaturalKey,
        arrival_lsn: Lsn,
    ) -> Result<()> {
        let _operation = self.open_operation()?;
        let row_id = self
            .row_id_for_natural_key_full(table, natural_key, self.snapshot_for_read())
            .ok_or_else(|| {
                Error::SyncError(format!(
                    "cannot mark missing {table} row as a pulled sync arrival"
                ))
            })?;
        self.relational_store.set_sync_source_lsns([(
            table.to_string(),
            row_id,
            arrival_lsn,
        )]);
        self.relational_store.set_sync_source_kinds([(
            table.to_string(),
            row_id,
            contextdb_relational::store::SyncSourceKind::Pulled,
        )]);
        Ok(())
    }

    }

    /// Whether this exact outgoing row change was supplied by sync. Live rows
    /// use their relational provenance sidecar; deletes use the open-session
    /// tombstone marker staged before an incoming delete becomes visible.
    pub fn row_change_arrived_by_sync(&self, row: &RowChange) -> bool {
        let _operation = self.assert_open_operation();
        if !row.deleted {
            return self.row_version_arrived_by_sync(&row.table, &row.natural_key);
        }
        self.sync_tombstone_arrivals
            .read()
            .get(&Self::sync_tombstone_key(&row.table, &row.natural_key))
            .is_some_and(|marker| {
                matches!(
                    marker.kind,
                    contextdb_relational::store::SyncSourceKind::Pulled
                ) && (marker.delete_lsn == row.lsn
                    || marker.delete_lsn == SYNC_SOURCE_LSN_OWN_COMMIT)
            })
    }

    fn graph_arrival_config_key(record: &DurableGraphArrival) -> Result<String> {
        let identity = rmp_serde::to_vec(&(record.source, record.target, &record.edge_type))
            .map_err(|error| {
                Error::SyncError(format!("graph arrival identity encode failed: {error}"))
            })?;
        Ok(format!(
            "{SYNC_GRAPH_ARRIVAL_PREFIX}{}",
            blake3::hash(&identity).to_hex()
        ))
    }

    fn graph_arrival_key(record: &DurableGraphArrival) -> GraphIdentity {
        (record.source, record.target, record.edge_type.clone())
    }

    fn stage_pulled_graph_arrivals(
        &self,
        ws: &mut WriteSet,
        pulled: bool,
    ) -> Result<Vec<(GraphIdentity, DurableGraphArrival)>> {
        let Some(local_lsn) = ws.commit_lsn else {
            return Ok(Vec::new());
        };
        let mut records = ws
            .adj_deletes
            .iter()
            .map(|(source, edge_type, target, _)| DurableGraphArrival {
                source: *source,
                target: *target,
                edge_type: edge_type.clone(),
                local_lsn,
                deleted: true,
                pulled,
            })
            .collect::<Vec<_>>();
        // Storage applies deletes before inserts, so a same-commit
        // delete+reinsert is live. Insert markers must win that exact tie.
        records.extend(ws.adj_inserts.iter().map(|edge| DurableGraphArrival {
            source: edge.source,
            target: edge.target,
            edge_type: edge.edge_type.clone(),
            local_lsn,
            deleted: false,
            pulled,
        }));
        let markers = records
            .iter()
            .map(|record| (Self::graph_arrival_key(record), record.clone()))
            .collect();
        for record in records {
            ws.config_writes.push((
                Self::graph_arrival_config_key(&record)?,
                RedbPersistence::encode_config_value(&record)?,
            ));
        }
        Ok(markers)
    }

    /// Whether this exact receiver-local graph occurrence came from sync.
    /// Insert and delete are distinct so a later local operation on the same
    /// `(source,target,type)` is never mistaken for an echo.
    pub fn graph_change_arrived_by_sync(&self, edge: &EdgeChange) -> bool {
        let deleted = matches!(edge.properties.get("__deleted"), Some(Value::Bool(true)));
        self.sync_graph_arrivals
            .read()
            .get(&(edge.source, edge.target, edge.edge_type.clone()))
            .is_some_and(|marker| {
                marker.pulled && marker.local_lsn == edge.lsn && marker.deleted == deleted
            })
    }

    /// Whether this exact vector-owner mutation arrived by sync. Vector
    /// RowIds are local-store identities, so outbound echo filtering must use
    /// the owner plus its local commit LSN rather than a table/LSN group.
    /// Delete provenance is intentionally session-local, matching the current
    /// tombstone retention boundary.
    pub fn vector_change_arrived_by_sync(&self, vector: &VectorChange) -> bool {
        let _operation = self.assert_open_operation();
        if !vector.vector.is_empty() {
            return self
                .row_visible_at_snapshot(
                    &vector.index.table,
                    vector.row_id,
                    self.snapshot_for_read(),
                )
                .is_some_and(|row| {
                    row.lsn == vector.lsn
                        && matches!(
                            self.relational_store
                                .sync_source_kind(&vector.index.table, vector.row_id),
                            Some(contextdb_relational::store::SyncSourceKind::Pulled)
                        )
                });
        }
        self.change_log.read().iter().any(|entry| {
            let ChangeLogEntry::RowDelete {
                table,
                row_id,
                natural_key,
                lsn,
            } = entry
            else {
                return false;
            };
            table == &vector.index.table
                && *row_id == vector.row_id
                && *lsn == vector.lsn
                && self
                    .sync_tombstone_arrivals
                    .read()
                    .get(&Self::sync_tombstone_key(table, natural_key))
                    .is_some_and(|marker| {
                        matches!(
                            marker.kind,
                            contextdb_relational::store::SyncSourceKind::Pulled
                        ) && marker.delete_lsn == *lsn
                            && marker.row_id == Some(*row_id)
                    })
        })
    }

    fn sync_tombstone_key(table: &str, natural_key: &NaturalKey) -> (String, String) {
        (table.to_string(), format!("{:?}", natural_key.pairs()))
    }

    const DURABLE_LINEAGE_CONFIG_PREFIX: &'static str = "sync_lineage.v1.record.";

    fn load_unbound_creation_lineage(
        &self,
        state: &InMemoryLineageState,
        key: &str,
    ) -> Result<Option<DurableUnboundCreationLineage>> {
        match &self.persistence {
            Some(persistence) => persistence.load_config_value(key),
            None => Ok(state.unbound_creations.get(key).cloned()),
        }
    }

    fn load_row_lineage_sidecar(
        &self,
        state: &InMemoryLineageState,
        key: &str,
    ) -> Result<Option<DurableRowLineageSidecar>> {
        match &self.persistence {
            Some(persistence) => persistence.load_config_value(key),
            None => Ok(state.row_sidecars.get(key).cloned()),
        }
    }

    fn store_row_lineage_sidecar(
        &self,
        state: &mut InMemoryLineageState,
        key: &str,
        record: &DurableRowLineageSidecar,
    ) -> Result<()> {
        match &self.persistence {
            Some(persistence) => persistence.flush_config_value(key, record),
            None => {
                state.row_sidecars.insert(key.to_string(), record.clone());
                Ok(())
            }
        }
    }

    fn load_lineage_record(
        &self,
        state: &InMemoryLineageState,
        key: &str,
    ) -> Result<Option<DurableLineageRecord>> {
        match &self.persistence {
            Some(persistence) => persistence.load_config_value(key),
            None => Ok(state.records.get(key).cloned()),
        }
    }

    fn store_lineage_record(
        &self,
        state: &mut InMemoryLineageState,
        key: &str,
        record: &DurableLineageRecord,
    ) -> Result<()> {
        match &self.persistence {
            Some(persistence) => persistence.flush_config_value(key, record),
            None => {
                state.records.insert(key.to_string(), record.clone());
                Ok(())
            }
        }
    }

    /// Publish a delete record and its exact local-row sidecar as one durable
    /// unit. The caller holds `lineage_state_lock`, which is also the memory
    /// backend's atomicity boundary.
    fn store_lineage_record_and_row_sidecar(
        &self,
        state: &mut InMemoryLineageState,
        record_key: &str,
        record: &DurableLineageRecord,
        sidecar_key: &str,
        sidecar: &DurableRowLineageSidecar,
    ) -> Result<()> {
        match &self.persistence {
            Some(persistence) => {
                let encoded_record = RedbPersistence::encode_config_value(record)?;
                let encoded_sidecar = RedbPersistence::encode_config_value(sidecar)?;
                persistence.flush_encoded_config_values(vec![
                    (record_key, encoded_record),
                    (sidecar_key, encoded_sidecar),
                ])
            }
            None => {
                state.records.insert(record_key.to_string(), record.clone());
                state
                    .row_sidecars
                    .insert(sidecar_key.to_string(), sidecar.clone());
                Ok(())
            }
        }
    }

    fn remove_lineage_record(&self, state: &mut InMemoryLineageState, key: &str) -> Result<()> {
        match &self.persistence {
            Some(persistence) => persistence.remove_config_value(key),
            None => {
                state.records.remove(key);
                Ok(())
            }
        }
    }

    fn list_lineage_records(
        &self,
        state: &InMemoryLineageState,
    ) -> Result<Vec<(String, DurableLineageRecord)>> {
        match &self.persistence {
            Some(persistence) => {
                persistence.load_config_values_with_prefix(Self::DURABLE_LINEAGE_CONFIG_PREFIX)
            }
            None => Ok(state
                .records
                .iter()
                .map(|(key, record)| (key.clone(), record.clone()))
                .collect()),
        }
    }

    fn local_delete_sidecar_from_record(
        record: &DurableLineageRecord,
    ) -> Result<DurableRowLineageSidecar> {
        let local_row_id = record.local_row_id.ok_or_else(|| {
            Error::SyncError(
                "locally created pending delete lacks the pinned local row id".to_string(),
            )
        })?;
        let author_node_id = record.author_node_id.clone().ok_or_else(|| {
            Error::SyncError(
                "locally created pending delete lacks its creation lineage".to_string(),
            )
        })?;
        let author_database_incarnation = record
            .author_database_incarnation
            .as_deref()
            .and_then(Incarnation::from_hex)
            .ok_or_else(|| {
                Error::SyncError(
                    "locally created pending delete has an invalid author incarnation".to_string(),
                )
            })?;
        if record.lineage_attestation.is_empty() {
            return Err(Error::SyncError(
                "locally created pending delete lacks its lineage attestation".to_string(),
            ));
        }
        Ok(DurableRowLineageSidecar {
            author_node_id,
            author_database_incarnation,
            author_local_mutation_position: Lsn(record.author_local_mutation_position),
            table_generation: record.table_generation,
            lineage_root: record.lineage_root.clone(),
            lineage_attestation: record.lineage_attestation.clone(),
            local_row_id: Some(local_row_id),
            locally_created: true,
        })
    }

    fn local_delete_sidecar_slot_is_eligible(
        &self,
        state: &InMemoryLineageState,
        sidecar_key: &str,
        local_row_id: RowId,
    ) -> Result<bool> {
        Ok(match self.load_row_lineage_sidecar(state, sidecar_key)? {
            None => true,
            Some(existing) => {
                existing.local_row_id == Some(local_row_id) && existing.locally_created
            }
        })
    }

    fn prepare_in_memory_lineage_delta(
        config_writes: &[(String, Vec<u8>)],
    ) -> Result<InMemoryLineageDelta> {
        let mut delta = InMemoryLineageDelta::default();
        for (key, value) in config_writes {
            if key.starts_with("sync_creation_lineage.v1.") {
                delta
                    .unbound_creations
                    .insert(key.clone(), RedbPersistence::decode_config_value(value)?);
            } else if key.starts_with("sync_row_lineage.v1.") {
                delta
                    .row_sidecars
                    .insert(key.clone(), RedbPersistence::decode_config_value(value)?);
            } else if key.starts_with(Self::DURABLE_LINEAGE_CONFIG_PREFIX) {
                delta
                    .records
                    .insert(key.clone(), RedbPersistence::decode_config_value(value)?);
            }
        }
        Ok(delta)
    }

    fn publish_in_memory_lineage_delta(&self, delta: InMemoryLineageDelta) {
        if self.persistence.is_some() {
            return;
        }
        let mut state = self.lineage_state_lock.lock();
        state.unbound_creations.extend(delta.unbound_creations);
        state.row_sidecars.extend(delta.row_sidecars);
        state.records.extend(delta.records);
    }

    fn load_graph_arrivals_from_persistence(&self) -> Result<()> {
        let Some(persistence) = &self.persistence else {
            return Ok(());
        };
        let mut arrivals = HashMap::new();
        for (key, record) in persistence
            .load_config_values_with_prefix::<DurableGraphArrival>(SYNC_GRAPH_ARRIVAL_PREFIX)?
        {
            if key != Self::graph_arrival_config_key(&record)? {
                return Err(Error::StoreCorrupted {
                    path: key,
                    reason: "graph-arrival key disagrees with its canonical record".to_string(),
                });
            }
            arrivals.insert(Self::graph_arrival_key(&record), record);
        }
        *self.sync_graph_arrivals.write() = arrivals;
        Ok(())
    }

    fn durable_lineage_config_key(
        table: &str,
        natural_key: &NaturalKey,
        generation: u64,
    ) -> String {
        format!(
            "{}{generation:016x}.{}",
            Self::DURABLE_LINEAGE_CONFIG_PREFIX,
            Self::hex_component(&sync_identity_key(table, natural_key))
        )
    }

    fn durable_lineage_table_generation_key(table: &str) -> String {
        format!(
            "{}{}",
            Self::DURABLE_LINEAGE_TABLE_GENERATION_PREFIX,
            Self::hex_component(table.as_bytes())
        )
    }

    const DURABLE_LINEAGE_TABLE_GENERATION_PREFIX: &str = "sync_lineage.v1.table_generation.";

    /// A received-schema stage adjudicates against a private in-memory
    /// database.  Its generation map must therefore be a complete snapshot of
    /// the real owner's authoritative state, including names whose tables were
    /// dropped but whose next same-name CREATE still depends on their prior
    /// generation.
    fn authoritative_table_generations_for_detached_working(&self) -> Result<HashMap<String, u64>> {
        let Some(persistence) = &self.persistence else {
            return Ok(self.in_memory_table_generations.lock().clone());
        };

        let mut generations = HashMap::new();
        for (key, raw_generation) in persistence
            .load_config_values_raw_with_prefix(Self::DURABLE_LINEAGE_TABLE_GENERATION_PREFIX)?
        {
            let suffix = key
                .strip_prefix(Self::DURABLE_LINEAGE_TABLE_GENERATION_PREFIX)
                .ok_or_else(|| Error::StoreCorrupted {
                    path: key.clone(),
                    reason: "table-generation key lacks its canonical prefix".to_string(),
                })?;
            if suffix.is_empty()
                || suffix.len() % 2 != 0
                || !suffix
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
            {
                return Err(Error::StoreCorrupted {
                    path: key,
                    reason:
                        "table-generation key has a malformed canonical lowercase hex table suffix"
                            .to_string(),
                });
            }
            let table_bytes = suffix
                .as_bytes()
                .chunks_exact(2)
                .map(|pair| {
                    let high = (pair[0] as char).to_digit(16).expect("validated hex") as u8;
                    let low = (pair[1] as char).to_digit(16).expect("validated hex") as u8;
                    (high << 4) | low
                })
                .collect::<Vec<_>>();
            let table = String::from_utf8(table_bytes).map_err(|_| Error::StoreCorrupted {
                path: key.clone(),
                reason: "table-generation key table suffix is not UTF-8".to_string(),
            })?;
            let generation = RedbPersistence::decode_config_value_exact::<u64>(&raw_generation)
                .map_err(|err| Error::StoreCorrupted {
                    path: key.clone(),
                    reason: format!("table-generation value is not an exact canonical u64: {err}"),
                })?;
            let canonical_generation =
                RedbPersistence::encode_config_value(&generation).map_err(|err| {
                    Error::StoreCorrupted {
                        path: key.clone(),
                        reason: format!(
                            "table-generation value cannot be canonically encoded: {err}"
                        ),
                    }
                })?;
            if generation == 0
                || canonical_generation != raw_generation
                || Self::durable_lineage_table_generation_key(&table) != key
                || generations.insert(table, generation).is_some()
            {
                return Err(Error::StoreCorrupted {
                    path: key,
                    reason: "table-generation key or value is zero, duplicate, or noncanonical"
                        .to_string(),
                });
            }
        }
        for table in self.relational_store.table_meta.read().keys() {
            if !generations.contains_key(table) {
                return Err(Error::StoreCorrupted {
                    path: Self::durable_lineage_table_generation_key(table),
                    reason: format!(
                        "table {table} has schema metadata but no authoritative generation"
                    ),
                });
            }
        }
        Ok(generations)
    }

    fn durable_ddl_generation_sidecar_key(lsn: Lsn, ordinal: u32) -> String {
        format!("sync_ddl_generation.v1.{:020}.{ordinal:06}", lsn.0)
    }

    const DURABLE_RECEIVED_DDL_ARRIVAL_CONFIG_PREFIX: &str = "sync_ddl_received_arrival.v1.";

    fn durable_received_ddl_arrival_key(local_lsn: Lsn, persisted_ordinal: u32) -> String {
        format!(
            "{}{:020}.{persisted_ordinal:06}",
            Self::DURABLE_RECEIVED_DDL_ARRIVAL_CONFIG_PREFIX,
            local_lsn.0
        )
    }

    fn load_received_ddl_arrivals_from_persistence(&self) -> Result<()> {
        let Some(persistence) = &self.persistence else {
            return Ok(());
        };
        let mut arrivals = HashMap::new();
        for (key, arrival) in persistence
            .load_config_values_with_prefix::<DurableReceivedDdlArrival>(
                Self::DURABLE_RECEIVED_DDL_ARRIVAL_CONFIG_PREFIX,
            )?
        {
            let expected_key = Self::durable_received_ddl_arrival_key(
                arrival.local_lsn,
                arrival.persisted_ordinal,
            );
            if key != expected_key
                || arrivals
                    .insert((arrival.local_lsn, arrival.persisted_ordinal), arrival)
                    .is_some()
            {
                return Err(Error::StoreCorrupted {
                    path: key,
                    reason: "received DDL arrival key does not bind one exact local occurrence"
                        .to_string(),
                });
            }
        }
        *self.received_ddl_arrivals.write() = arrivals;
        Ok(())
    }

    const DURABLE_SUPERSEDED_DDL_CONFIG_PREFIX: &str = "sync_ddl_superseded.v1.";

    fn durable_superseded_ddl_occurrence_key(local_lsn: Lsn, persisted_ordinal: u32) -> String {
        format!(
            "{}{:020}.{persisted_ordinal:06}",
            Self::DURABLE_SUPERSEDED_DDL_CONFIG_PREFIX,
            local_lsn.0
        )
    }

    fn load_superseded_ddl_occurrences_from_persistence(&self) -> Result<()> {
        let Some(persistence) = &self.persistence else {
            return Ok(());
        };
        let mut superseded = HashMap::new();
        for (key, occurrence) in persistence
            .load_config_values_with_prefix::<DurableSupersededDdlOccurrence>(
                Self::DURABLE_SUPERSEDED_DDL_CONFIG_PREFIX,
            )?
        {
            let expected_key = Self::durable_superseded_ddl_occurrence_key(
                occurrence.local_lsn,
                occurrence.persisted_ordinal,
            );
            if key != expected_key
                || superseded
                    .insert(
                        (occurrence.local_lsn, occurrence.persisted_ordinal),
                        occurrence,
                    )
                    .is_some()
            {
                return Err(Error::StoreCorrupted {
                    path: key,
                    reason: "superseded DDL key does not bind one exact local occurrence"
                        .to_string(),
                });
            }
        }
        *self.superseded_ddl_occurrences.write() = superseded;
        Ok(())
    }

    /// The spelling one `DdlChange` takes once it has crossed the durable
    /// config codec. That codec's compatibility decoder projects structured
    /// table fields down to the legacy persisted shape, so this is the only
    /// comparison that can hold between a declaration this node parsed and the
    /// same declaration a peer serves back out of its own store.
    fn persisted_ddl_shape(change: &DdlChange) -> Result<DdlChange> {
        let encoded = RedbPersistence::encode_config_value(change)?;
        RedbPersistence::decode_config_value(&encoded)
    }

    /// Decide which locally authored DDL occurrences an incoming authenticated
    /// vector restates, given the local DDL log as it stood before that vector
    /// was appended. Occurrences already carrying arrival or superseded
    /// evidence are left alone, and each incoming declaration consumes at most
    /// the first still-unmatched local occurrence with the same persisted
    /// spelling, so duplicate DDL cannot be counted twice.
    ///
    /// A local schema commit is superseded only in full: marking part of one
    /// commit would let a later push carry a fragment of a transaction whose
    /// remaining statements the peer has never seen.
    fn superseded_local_ddl_occurrences(
        &self,
        local_ddl_log: &[(Lsn, DdlChange)],
        received_ddl: &[DdlChange],
    ) -> Result<Vec<((Lsn, u32), DurableSupersededDdlOccurrence)>> {
        let arrivals = self.received_ddl_arrivals.read().clone();
        let already_superseded = self.superseded_ddl_occurrences.read().clone();
        let mut next_ordinal = HashMap::<Lsn, u32>::new();
        let mut candidates: Vec<SupersedableLocalDdl> = Vec::new();
        let mut eligible_per_commit = HashMap::<Lsn, usize>::new();
        let mut unprovable_commits = HashSet::<Lsn>::new();
        for (lsn, change) in local_ddl_log {
            let ordinal = next_ordinal.entry(*lsn).or_default();
            let key = (*lsn, *ordinal);
            *ordinal = ordinal.saturating_add(1);
            if arrivals.contains_key(&key) || already_superseded.contains_key(&key) {
                continue;
            }
            // An occurrence with no immutable generation evidence cannot be
            // bound by a digest. Its whole commit therefore stays outbound,
            // because marking the rest would leave that commit half-proven.
            let Some(generation) = self.recorded_ddl_generation_sidecar(key.0, key.1)? else {
                unprovable_commits.insert(*lsn);
                continue;
            };
            *eligible_per_commit.entry(*lsn).or_default() += 1;
            candidates.push(SupersedableLocalDdl {
                key,
                persisted_shape: Self::persisted_ddl_shape(change)?,
                digest: Self::canonical_local_ddl_arrival_digest(
                    change,
                    key.0,
                    key.1,
                    &generation,
                )?,
                matched: false,
            });
        }

        let mut matched_per_commit = HashMap::<Lsn, usize>::new();
        for change in received_ddl {
            let incoming = Self::persisted_ddl_shape(change)?;
            if let Some(candidate) = candidates
                .iter_mut()
                .find(|candidate| !candidate.matched && candidate.persisted_shape == incoming)
            {
                candidate.matched = true;
                *matched_per_commit.entry(candidate.key.0).or_default() += 1;
            }
        }

        Ok(candidates
            .into_iter()
            .filter(|candidate| {
                candidate.matched
                    && !unprovable_commits.contains(&candidate.key.0)
                    && matched_per_commit
                        .get(&candidate.key.0)
                        .copied()
                        .unwrap_or(0)
                        == eligible_per_commit
                            .get(&candidate.key.0)
                            .copied()
                            .unwrap_or(0)
            })
            .map(|candidate| {
                (
                    candidate.key,
                    DurableSupersededDdlOccurrence {
                        local_lsn: candidate.key.0,
                        persisted_ordinal: candidate.key.1,
                        digest: candidate.digest,
                    },
                )
            })
            .collect())
    }

    fn canonical_local_ddl_arrival_digest(
        ddl: &DdlChange,
        local_lsn: Lsn,
        persisted_ordinal: u32,
        generation: &DurableDdlGenerationSidecar,
    ) -> Result<Vec<u8>> {
        // The receiver-local marker binds the durable DDL-log occurrence, not
        // the authenticated source spelling (whose full-fidelity digest is
        // validated separately before this point). DdlChange's compatibility
        // decoder deliberately projects structured table fields to the legacy
        // persisted shape, so normalize through that exact codec here. This
        // keeps one arrival digest stable before and after reopen without
        // weakening the source migration manifest.
        crate::protocol::canonical_ddl_provenance_digest(
            &crate::protocol::WireDdlChange::from(Self::persisted_ddl_shape(ddl)?),
            local_lsn,
            persisted_ordinal,
            generation.table.as_deref(),
            generation.table_generation,
        )
        .map_err(|err| Error::SyncError(err.to_string()))
    }

    fn durable_received_ddl_marker_key(
        tenant_id: &TenantId,
        source_node_id: &str,
        source_incarnation: Incarnation,
        source_ddl_lsn: Lsn,
        ordinal: u32,
    ) -> String {
        tenant_id.config_key(&format!(
            "sync_ddl_apply.v1.{}.inc.{}.lsn.{:020}.{:06}",
            Self::hex_component(source_node_id.as_bytes()),
            source_incarnation.to_hex(),
            source_ddl_lsn.0,
            ordinal,
        ))
    }

    fn received_schema_manifest_markers(
        received: &crate::protocol::ReceivedDdlContext,
    ) -> Result<Vec<DurableReceivedSchemaManifestMarker>> {
        let mut seen = HashSet::new();
        let mut markers = Vec::with_capacity(received.entries.len());
        for entry in &received.entries {
            let key = Self::durable_received_ddl_marker_key(
                &received.tenant_id,
                &received.source_node_id,
                received.source_incarnation,
                entry.source_ddl_lsn,
                entry.ordinal,
            );
            if !seen.insert(key.clone()) {
                return Err(Error::SyncError(
                    "received schema migration repeats an authenticated marker identity"
                        .to_string(),
                ));
            }
            markers.push(DurableReceivedSchemaManifestMarker {
                key,
                digest: entry.digest.clone(),
            });
        }
        Ok(markers)
    }

    fn durable_received_schema_manifest_key(
        received: &crate::protocol::ReceivedDdlContext,
    ) -> Result<String> {
        let markers = Self::received_schema_manifest_markers(received)?;
        let ordered_identity = markers
            .iter()
            .map(|marker| Self::hex_component(marker.key.as_bytes()))
            .collect::<Vec<_>>()
            .join(".");
        Ok(received.tenant_id.config_key(&format!(
            "sync_ddl_manifest.v1.{}.inc.{}.count.{:06}.{ordered_identity}",
            Self::hex_component(received.source_node_id.as_bytes()),
            received.source_incarnation.to_hex(),
            markers.len(),
        )))
    }

    /// Read retry evidence while the private manifest lock is held through
    /// the later commit. File-backed databases read Redb; memory databases
    /// read the shared lifetime mirror.
    fn classify_received_schema_manifest(
        &self,
        received: &crate::protocol::ReceivedDdlContext,
    ) -> Result<ReceivedSchemaManifestClassification> {
        let markers = Self::received_schema_manifest_markers(received)?;
        let manifest_key = Self::durable_received_schema_manifest_key(received)?;
        let (manifest, stored_markers) = if let Some(persistence) = self.persistence.as_ref() {
            let manifest =
                persistence.load_config_value::<DurableReceivedSchemaManifest>(&manifest_key)?;
            let mut stored_markers = HashMap::new();
            for marker in &markers {
                if let Some(stored) =
                    persistence.load_config_value::<DurableReceivedDdlMarker>(&marker.key)?
                {
                    stored_markers.insert(marker.key.clone(), stored);
                }
            }
            (manifest, stored_markers)
        } else {
            let state = self.in_memory_received_schema_manifests.lock();
            (
                state.manifests.get(&manifest_key).cloned(),
                markers
                    .iter()
                    .filter_map(|marker| {
                        state
                            .markers
                            .get(&marker.key)
                            .cloned()
                            .map(|stored| (marker.key.clone(), stored))
                    })
                    .collect(),
            )
        };
        if let Some(manifest) = manifest {
            return if manifest.markers == markers {
                Ok(ReceivedSchemaManifestClassification::Replay(
                    manifest.result,
                ))
            } else {
                Err(Error::SyncError(
                    "received schema retry changes the digest or order of an existing migration"
                        .to_string(),
                ))
            };
        }

        for marker in &markers {
            if let Some(stored) = stored_markers.get(&marker.key)
                && stored.digest != marker.digest
            {
                return Err(Error::SyncError(
                    "received schema retry changes an existing marker digest".to_string(),
                ));
            }
        }
        let present = stored_markers.len();
        if present == 0 {
            return Ok(ReceivedSchemaManifestClassification::Apply);
        }
        if present == markers.len() {
            return Err(Error::SyncError(
                "received schema migration recombines applied markers without its original manifest"
                    .to_string(),
            ));
        }
        Err(Error::SyncError(
            "received schema migration mixes applied and absent markers".to_string(),
        ))
    }

    fn received_schema_manifest(
        received: &crate::protocol::ReceivedDdlContext,
        result: &ApplyResult,
    ) -> Result<(String, DurableReceivedSchemaManifest)> {
        let manifest = DurableReceivedSchemaManifest {
            markers: Self::received_schema_manifest_markers(received)?,
            result: crate::protocol::WireApplyResult::from(result.clone()),
        };
        Ok((
            Self::durable_received_schema_manifest_key(received)?,
            manifest,
        ))
    }

    /// Evolve every schema subsystem in the authenticated source vector's
    /// order.  In particular, a trigger/event cannot refer to a table that is
    /// only created later, while CREATE → DROP removes its table-bound event
    /// and trigger state before the next source item is considered.
    fn project_received_schema_source_order(
        &self,
        ddl: &[DdlChange],
    ) -> Result<ReceivedSchemaSemanticProjection> {
        self.project_received_schema_from_state(
            self.relational_store.table_meta.read().clone(),
            self.received_event_bus_projection(),
            self.trigger.declarations.lock().clone(),
            ddl,
        )
    }

    /// Rebuild one schema vector from no prior declarations. Synthetic
    /// snapshots use this to prove that their live schema is exactly the
    /// schema described by durable received-DDL evidence, rather than merely
    /// sharing one old received marker with it.
    fn project_received_schema_from_empty(
        &self,
        ddl: &[DdlChange],
    ) -> Result<ReceivedSchemaSemanticProjection> {
        self.project_received_schema_from_state(
            HashMap::new(),
            event_bus::EventBusDefinitions::default(),
            BTreeMap::new(),
            ddl,
        )
    }

    fn project_received_schema_from_state(
        &self,
        mut tables: HashMap<String, TableMeta>,
        mut event_bus: event_bus::EventBusDefinitions,
        mut trigger: BTreeMap<String, TriggerDeclaration>,
        ddl: &[DdlChange],
    ) -> Result<ReceivedSchemaSemanticProjection> {
        for change in ddl {
            Self::validate_sync_table_ddl_against_projected_meta(&tables, change)?;
            Self::apply_sync_table_ddl_to_projected_meta(&mut tables, change);
            Self::validate_projected_foreign_key_schema(&tables)?;
            self.apply_sync_trigger_ddl_to_projection(&mut trigger, change, &tables)?;
            self.apply_received_event_bus_ddl_to_projection(&mut event_bus, change, &tables)?;
        }
        Ok(ReceivedSchemaSemanticProjection {
            tables,
            event_bus,
            trigger,
        })
    }

    fn received_schema_memory_mirrors(
        &self,
        local_lsn: Lsn,
        source_order: &[ReceivedSchemaOrderEntry],
        accepted_authors: HashMap<(String, Vec<u8>), String>,
    ) -> ReceivedSchemaMemoryMirrors {
        let mut mirrors = ReceivedSchemaMemoryMirrors {
            table_generations: self.in_memory_table_generations.lock().clone(),
            ddl_generations: self.in_memory_ddl_generations.lock().clone(),
            received_ddl_arrivals: self.received_ddl_arrivals.read().clone(),
            superseded_ddl_occurrences: self.superseded_ddl_occurrences.read().clone(),
            source_state: self.sync_tombstone_arrivals.read().clone(),
            accepted_authors: self.accepted_sync_row_authors.read().clone(),
            terminal_markers: self.terminal_refusal_markers.read().clone(),
            terminal_scans: self.terminal_refusal_scans.read().clone(),
            receipt_and_applied_watermarks: self.in_memory_applied_push_watermarks.lock().clone(),
        };
        for entry in source_order {
            mirrors.ddl_generations.insert(
                (local_lsn, entry.persisted_ordinal),
                (
                    entry.generation.table.clone(),
                    entry.generation.table_generation,
                ),
            );
            mirrors.received_ddl_arrivals.insert(
                (local_lsn, entry.persisted_ordinal),
                entry.local_arrival.clone(),
            );
            if let (Some(table), Some(generation)) =
                (&entry.generation.table, entry.generation.table_generation)
            {
                mirrors.table_generations.insert(table.clone(), generation);
            }
        }
        mirrors.accepted_authors.extend(accepted_authors);
        mirrors
    }

    /// Turn the already transport-validated creator sidecars into the durable
    /// row provenance and accepted-author writes for this private stage.
    /// The forwarding peer in `ReceivedDdlContext` is deliberately absent:
    /// a relay is not the immutable author of the row it carries.
    fn validate_received_schema_lineage_sidecars(
        &self,
        changes: &ChangeSet,
        validated_lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
    ) -> Result<()> {
        if validated_lineages.len() != changes.rows.len() {
            return Err(Error::SyncError(
                "received schema rows require exactly one validated lineage sidecar per row"
                    .to_string(),
            ));
        }
        let mut consumed = HashSet::new();
        for row in &changes.rows {
            let matching = validated_lineages
                .iter()
                .enumerate()
                .filter(|(_, (table, natural_key, lsn, _))| {
                    table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn
                })
                .collect::<Vec<_>>();
            if matching.len() != 1 || !consumed.insert(matching[0].0) {
                return Err(Error::SyncError(format!(
                    "received schema row {} {:?} at source LSN {} lacks exactly one validated lineage",
                    row.table, row.natural_key, row.lsn.0
                )));
            }
            let lineage = &matching[0].1.3;
            let expected_root = format!(
                "author:{}:{}:{}",
                lineage.author_node_id,
                lineage.author_database_incarnation.to_hex(),
                lineage.author_local_mutation_position.0,
            );
            if lineage.lineage_root != expected_root {
                return Err(Error::SyncError(
                    "validated row lineage root does not match its immutable creator tuple"
                        .to_string(),
                ));
            }
        }
        if consumed.len() != validated_lineages.len() {
            return Err(Error::SyncError(
                "received schema lineage sidecar does not match any retained row".to_string(),
            ));
        }
        Ok(())
    }

    fn received_schema_replacement_bytes(
        tables: &HashMap<String, TableMeta>,
        rows: &HashMap<String, Vec<VersionedRow>>,
        edges: &[AdjEntry],
        vector_bytes: usize,
    ) -> usize {
        let metadata = tables.values().fold(0usize, |bytes, meta| {
            bytes.saturating_add(meta.estimated_bytes())
        });
        let rows = rows.iter().fold(0usize, |bytes, (table, rows)| {
            let Some(meta) = tables.get(table) else {
                return bytes;
            };
            rows.iter().fold(bytes, |bytes, row| {
                bytes.saturating_add(estimate_row_bytes_for_meta(&row.values, meta, false))
            })
        });
        let edges = edges
            .iter()
            .filter(|edge| edge.deleted_tx.is_none())
            .fold(0usize, |bytes, edge| {
                bytes.saturating_add(edge.estimated_bytes())
            });
        metadata
            .saturating_add(rows)
            .saturating_add(edges)
            .saturating_add(vector_bytes)
    }

    /// Clone only declarations needed to validate locally authored CREATE /
    /// ALTER ADD / trigger DDL. Row, edge, and vector payloads remain solely
    /// in the live database and are never duplicated by a long-lived BEGIN.
    fn detached_local_schema_working_database(&self) -> Result<Database> {
        let working = Database::open_memory();
        let metadata = self.relational_store.table_meta.read().clone();
        for (table, meta) in metadata {
            working.relational_store.create_table(&table, meta.clone());
            for index in &meta.indexes {
                if index.kind == IndexKind::Auto {
                    working.relational_store.create_exact_index_storage(
                        &table,
                        &index.name,
                        index.columns.clone(),
                    );
                } else {
                    working.relational_store.create_index_storage(
                        &table,
                        &index.name,
                        index.columns.clone(),
                    );
                }
            }
        }
        Ok(working)
    }

    /// Clone the mutable state that the sync adjudicator reads into a private
    /// in-memory working database.  It deliberately has its own transaction
    /// manager, memory accountant and row-id cursor: planning an authenticated
    /// schema unit must not reserve an ID, charge memory or touch a live
    /// receipt/terminal mirror before the real commit has succeeded.
    fn detached_received_schema_working_database(&self) -> Result<Database> {
        let working = Database::open_memory();
        let authoritative_table_generations =
            self.authoritative_table_generations_for_detached_working()?;
        // The copied image retains the real database's MVCC identities.  Give
        // the detached transaction manager the same committed visibility
        // floor before adjudication, instead of rewriting every copied row to
        // fit a fresh manager.
        let source_watermark = self.tx_mgr.current_tx_max();
        if source_watermark != TxId(0) {
            let visibility_tx = working.begin()?;
            working.tx_mgr.advance_for_sync(
                visibility_tx,
                "detached_received_schema_snapshot",
                source_watermark,
            )?;
            working.tx_mgr.with_write_set(visibility_tx, |ws| {
                ws.config_writes.push((
                    "__contextdb.detached_received_schema_snapshot".to_string(),
                    RedbPersistence::encode_config_value(&source_watermark.0)?,
                ));
                Ok::<(), Error>(())
            })??;
            working.commit_with_source(visibility_tx, CommitSource::SyncPull)?;
        }
        let tables = self.relational_store.tables.read().clone();
        let metadata = self.relational_store.table_meta.read().clone();
        for (table, meta) in &metadata {
            working.relational_store.create_table(table, meta.clone());
            for index in &meta.indexes {
                if index.kind == IndexKind::Auto {
                    working.relational_store.create_exact_index_storage(
                        table,
                        &index.name,
                        index.columns.clone(),
                    );
                } else {
                    working.relational_store.create_index_storage(
                        table,
                        &index.name,
                        index.columns.clone(),
                    );
                }
            }
        }
        for (table, rows) in &tables {
            for row in rows {
                working
                    .relational_store
                    .insert_loaded_row(table, row.clone());
            }
        }
        working
            .relational_store
            .set_next_row_id(self.relational_store.next_row_id());
        let sources = self.relational_store.sync_source_sidecars_snapshot();
        working.relational_store.set_sync_source_lsns(
            sources
                .iter()
                .map(|((table, row_id), (lsn, _))| (table.clone(), *row_id, *lsn)),
        );
        working.relational_store.set_sync_source_kinds(
            sources
                .into_iter()
                .map(|((table, row_id), (_, kind))| (table, row_id, kind)),
        );
        for edge in self
            .graph_store
            .forward_adj
            .read()
            .values()
            .flat_map(|entries| entries.iter().cloned())
        {
            working.graph_store.insert_loaded_edge(edge);
        }
        // Schema planning must preserve empty vector indexes too. A purge can
        // remove the final vector while the VECTOR column remains declared;
        // cloning entries alone would then make the detached adjudicator
        // reject the next authenticated vector as an unknown index.
        for info in self.vector_store.index_infos() {
            working.vector_store.register_or_reconfigure_empty_index(
                info.index,
                info.dimension,
                info.quantization,
            );
        }
        for vector in self.vector_store.all_entries() {
            working.vector_store.insert_loaded_vector(vector);
        }
        *working.in_memory_table_generations.lock() = authoritative_table_generations;
        *working.in_memory_ddl_generations.lock() = self.in_memory_ddl_generations.lock().clone();
        *working.received_ddl_arrivals.write() = self.received_ddl_arrivals.read().clone();
        *working.superseded_ddl_occurrences.write() =
            self.superseded_ddl_occurrences.read().clone();
        *working.sync_tombstone_arrivals.write() = self.sync_tombstone_arrivals.read().clone();
        *working.accepted_sync_row_authors.write() = self.accepted_sync_row_authors.read().clone();
        *working.terminal_refusal_markers.write() = self.terminal_refusal_markers.read().clone();
        *working.terminal_refusal_scans.write() = self.terminal_refusal_scans.read().clone();
        *working.in_memory_applied_push_watermarks.lock() =
            self.in_memory_applied_push_watermarks.lock().clone();
        *working.lineage_state_lock.lock() = self.lineage_state_lock.lock().clone();
        *working.trigger.declarations.lock() = self.trigger.declarations.lock().clone();
        *working.trigger.callbacks.write() = self.trigger.callbacks.read().clone();
        working
            .trigger
            .ready
            .store(self.trigger.ready.load(Ordering::SeqCst), Ordering::SeqCst);
        Ok(working)
    }

    /// The detached executor is allowed to choose rows and conflict outcomes,
    /// but its transaction manager starts at one.  Before its image becomes a
    /// received-schema stage, restamp every mutation it finalized with the
    /// caller-reserved receiver commit identity.
    fn restamp_detached_received_schema_commit(
        working: &Database,
        finalized: &mut WriteSet,
        local_lsn: Lsn,
        receiver_tx: TxId,
        fallback_arrival_tombstones: &HashSet<(String, String)>,
    ) -> Result<()> {
        let local_tx = receiver_tx;
        let detached_lsn = finalized.commit_lsn;
        finalized.commit_lsn = Some(local_lsn);
        for (_, row) in &mut finalized.relational_inserts {
            row.created_tx = local_tx;
            row.deleted_tx = None;
            row.lsn = local_lsn;
        }
        for (_, _, deleted_tx) in &mut finalized.relational_deletes {
            *deleted_tx = local_tx;
        }
        for entry in &mut finalized.adj_inserts {
            entry.created_tx = local_tx;
            entry.deleted_tx = None;
            entry.lsn = local_lsn;
        }
        for (_, _, _, deleted_tx) in &mut finalized.adj_deletes {
            *deleted_tx = local_tx;
        }
        for entry in &mut finalized.vector_inserts {
            entry.created_tx = local_tx;
            entry.deleted_tx = None;
            entry.lsn = local_lsn;
        }
        for (_, _, deleted_tx) in &mut finalized.vector_deletes {
            *deleted_tx = local_tx;
        }
        for (_, _, _, moved_tx) in &mut finalized.vector_moves {
            *moved_tx = local_tx;
        }

        let inserted_rows = finalized.relational_inserts.clone();
        let deleted_rows = finalized.relational_deletes.clone();
        {
            let mut tables = working.relational_store.tables.write();
            for (table, row) in &inserted_rows {
                if let Some(current) = tables.get_mut(table).and_then(|rows| {
                    rows.iter_mut()
                        .rev()
                        .find(|current| current.row_id == row.row_id)
                }) {
                    *current = row.clone();
                }
            }
            for (table, row_id, _) in &deleted_rows {
                if let Some(current) = tables.get_mut(table).and_then(|rows| {
                    rows.iter_mut()
                        .rev()
                        .find(|current| current.row_id == *row_id)
                }) {
                    current.deleted_tx = Some(local_tx);
                }
            }
        }
        let inserted_edges = finalized.adj_inserts.clone();
        let deleted_edges = finalized.adj_deletes.clone();
        for entries in working.graph_store.forward_adj.write().values_mut() {
            for entry in entries {
                if let Some(replacement) = inserted_edges.iter().find(|replacement| {
                    replacement.source == entry.source
                        && replacement.target == entry.target
                        && replacement.edge_type == entry.edge_type
                }) {
                    *entry = replacement.clone();
                }
                if deleted_edges.iter().any(|(source, edge_type, target, _)| {
                    *source == entry.source
                        && *target == entry.target
                        && *edge_type == entry.edge_type
                }) {
                    entry.deleted_tx = Some(local_tx);
                }
            }
        }
        // Rebuild the reverse map from the one rewritten authoritative
        // forward image so both graph directions carry identical MVCC state.
        let edges = working
            .graph_store
            .forward_adj
            .read()
            .values()
            .flat_map(|entries| entries.iter().cloned())
            .collect();
        working.graph_store.publish_prepared_received_schema(
            GraphStore::prepare_received_schema_publication(edges),
        );
        let inserted_vectors = finalized.vector_inserts.clone();
        let deleted_vectors = finalized.vector_deletes.clone();
        let mut vectors = working.vector_store.all_entries();
        for entry in &mut vectors {
            if let Some(replacement) = inserted_vectors.iter().find(|replacement| {
                replacement.index == entry.index && replacement.row_id == entry.row_id
            }) {
                *entry = replacement.clone();
            }
            if deleted_vectors
                .iter()
                .any(|(index, row_id, _)| *index == entry.index && *row_id == entry.row_id)
            {
                entry.deleted_tx = Some(local_tx);
            }
        }
        working.vector_store.replace_loaded_vectors(vectors);
        let deleted_row_ids = finalized
            .relational_deletes
            .iter()
            .map(|(_, row_id, _)| *row_id)
            .collect::<HashSet<_>>();
        for (marker_key, marker) in working.sync_tombstone_arrivals.write().iter_mut() {
            if detached_lsn.is_some_and(|lsn| marker.delete_lsn == lsn)
                && marker
                    .row_id
                    .is_some_and(|row_id| deleted_row_ids.contains(&row_id))
            {
                marker.delete_lsn = local_lsn;
                // Only a wire entry explicitly mapped to `None` used the
                // detached commit LSN as its arrival fallback. An explicit
                // source arrival may have that same numeric value, so its
                // provenance, not equality with the detached LSN, decides.
                if fallback_arrival_tombstones.contains(marker_key) {
                    marker.arrival = local_lsn;
                }
            }
        }
        for (key, bytes) in &mut finalized.config_writes {
            if key.starts_with("sync_lineage.v1.")
                && let Ok(mut record) =
                    RedbPersistence::decode_config_value::<DurableLineageRecord>(bytes)
                && detached_lsn.is_some_and(|lsn| record.delete_lsn == lsn.0)
            {
                record.delete_lsn = local_lsn.0;
                *bytes = RedbPersistence::encode_config_value(&record)?;
            }
        }
        Ok(())
    }

    /// Assemble the private received-schema stage by running the ordinary
    /// conflict/adoption adjudicator against a detached projected image.  The
    /// wire `ChangeSet` contributes authenticated intent only; it never
    /// directly assigns a receiver row id, MVCC identity, vector owner, or
    /// delete/terminal outcome in the prepared image.
    #[allow(dead_code)]
    fn prepare_received_schema_stage(
        &self,
        local_lsn: Lsn,
        changes: &ChangeSet,
        received: &crate::protocol::ReceivedDdlContext,
        validated_lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
    ) -> Result<ReceivedSchemaStage> {
        let arrivals = HashMap::new();
        self.prepare_received_schema_stage_with_adjudication(
            local_lsn,
            changes,
            received,
            validated_lineages,
            ReceivedSchemaAdjudicationInputs {
                arrivals: &arrivals,
                adoption: SyncAdoption::Continuing,
                receipt: None,
                dependency_complete: false,
                terminal_refusal_context: None,
                hub_local_author: None,
                receiver_tx: self.tx_mgr.peek_next_tx(),
            },
        )
    }

    fn prepare_received_schema_stage_with_adjudication(
        &self,
        local_lsn: Lsn,
        changes: &ChangeSet,
        received: &crate::protocol::ReceivedDdlContext,
        validated_lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        inputs: ReceivedSchemaAdjudicationInputs<'_>,
    ) -> Result<ReceivedSchemaStage> {
        let (source_order, mut persistence) =
            plan_received_schema_source_order(local_lsn, &changes.ddl, &changes.ddl_lsn, received)?;
        let local_ddl_log_before_extension = self.ddl_log.read().clone();
        // Schema this node authored before the vector arrived, which the
        // vector itself restates, stops being outbound work. The comparison
        // uses the log as it stood before the received occurrences were
        // appended so the vector cannot match itself.
        let superseded_occurrences =
            self.superseded_local_ddl_occurrences(&local_ddl_log_before_extension, &changes.ddl)?;
        for (_, occurrence) in superseded_occurrences.iter() {
            persistence.superseded_occurrence_values.push((
                Self::durable_superseded_ddl_occurrence_key(
                    occurrence.local_lsn,
                    occurrence.persisted_ordinal,
                ),
                RedbPersistence::encode_config_value(occurrence)?,
            ));
        }
        let mut ddl_log_replacement = local_ddl_log_before_extension;
        ddl_log_replacement.extend(persistence.ddl_log_replacement);
        persistence.ddl_log_replacement = ddl_log_replacement;
        self.validate_received_schema_lineage_sidecars(changes, validated_lineages)?;
        let working = self.detached_received_schema_working_database()?;
        // The detached row/table image starts with no event-bus state. Seed it
        // from the receiver before replaying authenticated DDL so a later
        // source-ordered route can be idempotent against independently
        // received event-type and sink declarations.
        working.seed_received_event_bus_projection(self.received_event_bus_projection());
        working
            .capture_detached_sync_write_set
            .store(true, Ordering::SeqCst);
        *working.detached_sync_write_set.lock() = None;
        let detached_policies = Self::declared_sync_policies(true);
        // This is the only semantic application of the received rows, edges,
        // and vectors during stage preparation.  It preserves the established
        // whole-key adoption, empty-vector delete, remote-owner remapping and
        // conflict branches instead of trying to recreate them from wire
        // fields here.  Its commit is private to `working`.
        let mut apply_result = working.apply_changes_single_lsn_group(
            changes.clone(),
            &detached_policies,
            inputs.arrivals,
            inputs.adoption,
            inputs.receipt.clone(),
            inputs.dependency_complete,
            inputs.terminal_refusal_context,
            inputs.hub_local_author,
            validated_lineages,
            true,
        )?;
        let mut finalized_write_set = working
            .detached_sync_write_set
            .lock()
            .take()
            // DDL-only units use the legacy DDL mutation path and therefore
            // have no data WriteSet.  Their projected schema is still valid;
            // there simply are no receipt/lineage/tombstone writes to carry.
            .unwrap_or_default();
        let fallback_arrival_tombstones = changes
            .rows
            .iter()
            .filter(|row| row.deleted && matches!(inputs.arrivals.get(&row.lsn), Some(None)))
            .map(|row| Self::sync_tombstone_key(&row.table, &row.natural_key))
            .collect::<HashSet<_>>();
        Self::restamp_detached_received_schema_commit(
            &working,
            &mut finalized_write_set,
            local_lsn,
            inputs.receiver_tx,
            &fallback_arrival_tombstones,
        )?;
        let in_memory_lineage_delta = if self.persistence.is_none() {
            Self::prepare_in_memory_lineage_delta(&finalized_write_set.config_writes)?
        } else {
            InMemoryLineageDelta::default()
        };
        // The detached apply owns no externally visible receiver LSN. The
        // active transaction reserved this identity before preparation, so
        // preserve every observed outcome field and restamp only `new_lsn`.
        apply_result.new_lsn = local_lsn;
        let (received_schema_manifest_key, received_schema_manifest) =
            Self::received_schema_manifest(received, &apply_result)?;
        persistence.config_values.push((
            received_schema_manifest_key.clone(),
            RedbPersistence::encode_config_value(&received_schema_manifest)?,
        ));
        // Schema-bound side effects evolve from the receiver's current live
        // definitions in exact authored DDL order. The detached database is
        // authoritative for rows/tables, but begins without retained
        // event/trigger definitions.
        let side_semantic = self.project_received_schema_source_order(&changes.ddl)?;
        let semantic = ReceivedSchemaSemanticProjection {
            tables: working.relational_store.table_meta.read().clone(),
            event_bus: side_semantic.event_bus,
            trigger: side_semantic.trigger,
        };
        let mut rows = working.relational_store.tables.read().clone();
        let source_sidecars = working.relational_store.sync_source_sidecars_snapshot();
        let projected_next_row_id = working.relational_store.next_row_id();
        let dropped_tables = self
            .relational_store
            .tables
            .read()
            .keys()
            .filter(|table| !semantic.tables.contains_key(*table))
            .cloned()
            .collect::<Vec<_>>();
        // Keep the exact config writes the established adjudicator finalized:
        // receipt/watermark max semantics, accepted-row lineage, accepted
        // delete lineage, terminal clears and author evidence all belong to
        // that one WriteSet.  Rebuilding them from every wire row would make
        // a refused row look accepted.
        for (key, value) in finalized_write_set.config_writes.iter().cloned() {
            if key.starts_with("sync_row_lineage.") {
                persistence.lineage_values.push((key, value));
            } else if key.starts_with("sync_row_author.") {
                persistence.accepted_author_values.push((key, value));
            } else if key.starts_with("sync_terminal_refusal.v1.") {
                persistence.terminal_values.push((key, value));
            } else if key.starts_with("sync_applied_push_watermark_node.") {
                persistence.applied_push_watermark_values.push((key, value));
            } else {
                // Includes accepted-delete `DurableLineageRecord` values;
                // its durable key is intentionally distinct from the
                // immutable row-lineage sidecar above.
                persistence.config_values.push((key, value));
            }
        }
        persistence
            .config_max_u64_keys
            .extend(finalized_write_set.config_max_u64_keys.iter().cloned());
        // Reopen must retain the authoritative generation for tables born in
        // this received unit.  The per-DDL generation sidecars establish
        // provenance for the source vector; the table key is the ordinary
        // local DML lookup used by later grant-table deletes/updates.
        for entry in &source_order {
            if let (Some(table), Some(generation)) =
                (&entry.generation.table, entry.generation.table_generation)
            {
                persistence.config_values.push((
                    Self::durable_lineage_table_generation_key(table),
                    RedbPersistence::encode_config_value(&generation)?,
                ));
            }
        }
        // The publication below moves each table's rows into its prepared
        // projection, so retain this snapshot only for the private memory
        // delta calculation performed after graph/vector preparation.
        let prepared_rows_for_memory = rows.clone();
        let projections = semantic
            .tables
            .iter()
            .map(|(table, meta)| {
                let projection = RelationalStore::table_projection(
                    table.clone(),
                    meta.clone(),
                    rows.remove(table).unwrap_or_default(),
                );
                let sources = source_sidecars
                    .iter()
                    .filter_map(|((source_table, row_id), (lsn, kind))| {
                        (source_table == table).then_some((*row_id, *lsn, *kind))
                    })
                    .collect();
                RelationalStore::with_sync_sources(projection, sources)
            })
            .collect();
        let relational = self
            .relational_store
            .prepare_received_schema_publication(projections, dropped_tables);

        let edges = working
            .graph_store
            .forward_adj
            .read()
            .values()
            .flat_map(|entries| entries.iter().cloned())
            .collect::<Vec<_>>();
        let graph = GraphStore::prepare_received_schema_publication(edges.clone());

        // A vector registry can contain a retired index while a database is
        // opening/recovering.  The projected schema remains authoritative:
        // only entries whose table and declared vector column survived the
        // detached DDL lifecycle may enter the prepared image.
        let vectors = working
            .vector_store
            .all_entries()
            .into_iter()
            .filter(|entry| {
                semantic.tables.get(&entry.index.table).is_some_and(|meta| {
                    meta.columns.iter().any(|column| {
                        column.name == entry.index.column
                            && matches!(column.column_type, ColumnType::Vector(_))
                    })
                })
            })
            .collect::<Vec<_>>();
        let schemas = semantic
            .tables
            .iter()
            .flat_map(|(table, meta)| {
                meta.columns
                    .iter()
                    .filter_map(move |column| match column.column_type {
                        ColumnType::Vector(dimension) => Some((
                            VectorIndexRef::new(table.clone(), column.name.clone()),
                            dimension,
                            column.quantization,
                        )),
                        _ => None,
                    })
            })
            .collect::<Vec<_>>();
        let new_vector_bytes = vectors
            .iter()
            .filter(|entry| entry.deleted_tx.is_none())
            .fold(0usize, |bytes, entry| {
                let quantization = schemas
                    .iter()
                    .find(|(index, _, _)| *index == entry.index)
                    .map(|(_, _, quantization)| *quantization)
                    .unwrap_or(VectorQuantization::F32);
                bytes.saturating_add(quantization.storage_bytes(entry.vector.len()))
            });
        let new_bytes = Self::received_schema_replacement_bytes(
            &semantic.tables,
            &prepared_rows_for_memory,
            &edges,
            new_vector_bytes,
        );
        let durable_vectors = vectors.clone();
        let vector = VectorStore::prepare_received_schema_publication(schemas, vectors);

        let old_tables = self.relational_store.table_meta.read().clone();
        let old_rows = self.relational_store.tables.read().clone();
        let old_edges = self
            .graph_store
            .forward_adj
            .read()
            .values()
            .flat_map(|entries| entries.iter().cloned())
            .collect::<Vec<_>>();
        let old_vector_infos = self.vector_store.index_infos();
        let old_vector_bytes = old_vector_infos
            .iter()
            .fold(0usize, |bytes, info| bytes.saturating_add(info.bytes));
        let old_vector_payload_bytes = self
            .vector_store
            .all_entries()
            .iter()
            .filter(|entry| entry.deleted_tx.is_none())
            .fold(0usize, |bytes, entry| {
                let quantization = old_vector_infos
                    .iter()
                    .find(|info| info.index == entry.index)
                    .map(|info| info.quantization)
                    .unwrap_or(VectorQuantization::F32);
                bytes.saturating_add(quantization.storage_bytes(entry.vector.len()))
            });
        let retired_hnsw_bytes = old_vector_bytes.saturating_sub(old_vector_payload_bytes);
        let old_bytes = Self::received_schema_replacement_bytes(
            &old_tables,
            &old_rows,
            &old_edges,
            old_vector_bytes,
        );
        let memory_swap = PreparedMemorySwap::prepare(
            self.accountant.clone(),
            old_bytes,
            new_bytes,
            retired_hnsw_bytes,
        )?;
        let queue_mutation_lease = self.event_bus.begin_queue_mutation();
        let event_bus =
            self.prepare_received_event_bus_publication_from_projection(semantic.event_bus)?;
        let trigger =
            self.prepare_received_trigger_publication_from_projection(semantic.trigger.clone())?;
        let prepared_sink_events = self.prepare_received_sink_events_for_publication(
            &finalized_write_set,
            &event_bus,
            &prepared_rows_for_memory,
            &semantic.tables,
        );
        let trigger_audit_entries = self.committed_sync_pull_trigger_audits_for_write_set(
            &finalized_write_set,
            local_lsn,
            Some(&semantic.trigger),
        )?;
        let (trigger_audits, next_trigger_audit_index) = self
            .trigger
            .prepare_received_persistence_audits(&trigger_audit_entries);
        persistence
            .config_values
            .extend(event_bus.config_values.iter().cloned());
        persistence
            .config_values
            .extend(trigger.config_values.iter().cloned());
        let mut mirrors = self.received_schema_memory_mirrors(
            local_lsn,
            &source_order,
            working.accepted_sync_row_authors.read().clone(),
        );
        mirrors
            .superseded_ddl_occurrences
            .extend(superseded_occurrences);
        mirrors.source_state = working.sync_tombstone_arrivals.read().clone();
        mirrors.accepted_authors = working.accepted_sync_row_authors.read().clone();
        mirrors.terminal_markers = working.terminal_refusal_markers.read().clone();
        mirrors.terminal_scans = working.terminal_refusal_scans.read().clone();
        mirrors.receipt_and_applied_watermarks =
            working.in_memory_applied_push_watermarks.lock().clone();
        if let Some(receipt) = inputs.receipt.as_ref() {
            let key = Self::applied_push_watermark_node_incarnation_key(
                &receipt.tenant_id,
                &receipt.node_id,
                receipt.incarnation,
            );
            mirrors
                .receipt_and_applied_watermarks
                .entry(key)
                .and_modify(|current| *current = (*current).max(receipt.source_lsn))
                .or_insert(receipt.source_lsn);
        }
        let mut durable_config_values = persistence.generation_values.clone();
        durable_config_values.extend(persistence.marker_values.iter().cloned());
        durable_config_values.extend(persistence.received_arrival_values.iter().cloned());
        durable_config_values.extend(persistence.superseded_occurrence_values.iter().cloned());
        durable_config_values.extend(persistence.lineage_values.iter().cloned());
        durable_config_values.extend(persistence.accepted_author_values.iter().cloned());
        durable_config_values.extend(persistence.source_state_values.iter().cloned());
        durable_config_values.extend(persistence.receipt_values.iter().cloned());
        durable_config_values.extend(persistence.applied_push_watermark_values.iter().cloned());
        durable_config_values.extend(persistence.terminal_values.iter().cloned());
        durable_config_values.extend(persistence.config_values.iter().cloned());
        let mut staged_deleted_rows = HashMap::<String, HashMap<RowId, VersionedRow>>::new();
        for (table, row_id, _) in &finalized_write_set.relational_deletes {
            if let Some(row) = prepared_rows_for_memory
                .get(table)
                // A primary-key update leaves historical versions with the
                // same RowId. The finalized delete names the latest version,
                // so its change-log tombstone must take the last authoritative
                // projected version rather than the stale first append.
                .and_then(|rows| rows.iter().rev().find(|row| row.row_id == *row_id))
            {
                staged_deleted_rows
                    .entry(table.clone())
                    .or_default()
                    .insert(*row_id, row.clone());
            }
        }
        let structurally_dropped_tables = Self::sync_dropped_tables(&changes.ddl);
        let change_log_entries = build_received_schema_change_log_entries(
            &finalized_write_set,
            &semantic.tables,
            &staged_deleted_rows,
            &structurally_dropped_tables,
        );
        let durable_projection = ReceivedSchemaPersistenceProjection {
            table_meta: semantic.tables.clone(),
            rows: prepared_rows_for_memory,
            sync_sources: source_sidecars
                .into_iter()
                .map(|((table, row_id), (lsn, kind))| (table, row_id, lsn, kind))
                .collect(),
            edges,
            vectors: durable_vectors,
            ddl_log: persistence.ddl_log_replacement.clone(),
            config_values: durable_config_values,
            config_max_u64_keys: persistence.config_max_u64_keys.clone(),
            structurally_dropped_tables: structurally_dropped_tables.clone(),
        };
        Ok(ReceivedSchemaStage {
            source_order,
            relational,
            graph,
            vector,
            event_bus,
            queue_mutation_lease,
            trigger,
            sink_events: prepared_sink_events.events,
            next_sink_queue_id: prepared_sink_events.next_queue_id,
            trigger_audits,
            next_trigger_audit_index,
            mirrors,
            memory_swap,
            next_row_id: projected_next_row_id,
            persistence,
            apply_result,
            received_schema_manifest_key,
            received_schema_manifest,
            in_memory_lineage_delta,
            write_set: finalized_write_set,
            durable_projection,
            structurally_dropped_tables,
            change_log_entries,
        })
    }

    /// Register the complete, private stage under the local commit LSN that
    /// the transaction manager reserved.  Registration itself is infallible;
    /// failure cleanup in the later Redb integration removes this entry before
    /// any memory publication can occur.
    #[allow(dead_code)]
    fn register_received_schema_stage(&self, local_lsn: Lsn, stage: ReceivedSchemaStage) {
        self.received_schema_stages.lock().insert(local_lsn, stage);
    }

    #[allow(dead_code)]
    fn take_received_schema_stage(&self, local_lsn: Lsn) -> Option<ReceivedSchemaStage> {
        self.received_schema_stages.lock().remove(&local_lsn)
    }

    /// The post-durability half of received-schema apply.  It performs no
    /// parsing, allocation, persistence, or fallible operation: the complete
    /// table projections and event/trigger definitions were prepared before
    /// the matching Redb transaction started.
    #[allow(dead_code)]
    fn publish_received_schema_stage(&self, mut stage: ReceivedSchemaStage) {
        #[cfg(test)]
        if take_received_schema_pre_publish_pause_armed_here_for_test() {
            received_schema_pre_publish_pause_for_test().maybe_pause();
        }
        if self.persistence.is_none() {
            self.publish_in_memory_lineage_delta(stage.in_memory_lineage_delta);
            let mut manifests = self.in_memory_received_schema_manifests.lock();
            for marker in &stage.received_schema_manifest.markers {
                manifests.markers.insert(
                    marker.key.clone(),
                    DurableReceivedDdlMarker {
                        digest: marker.digest.clone(),
                    },
                );
            }
            manifests.manifests.insert(
                stage.received_schema_manifest_key.clone(),
                stage.received_schema_manifest.clone(),
            );
        }
        self.relational_store
            .publish_prepared_received_schema(stage.relational);
        self.graph_store
            .publish_prepared_received_schema(stage.graph);
        self.vector_store
            .publish_prepared_received_schema(stage.vector, &*self.accountant);
        self.publish_prepared_event_bus_publication_under_queue_mutation_lease(
            stage.event_bus,
            stage.sink_events,
        );
        self.advance_received_sink_event_id(stage.next_sink_queue_id);
        self.publish_prepared_trigger_publication(stage.trigger);
        self.publish_received_trigger_audits(stage.trigger_audits, stage.next_trigger_audit_index);
        *self.in_memory_table_generations.lock() = stage.mirrors.table_generations;
        *self.in_memory_ddl_generations.lock() = stage.mirrors.ddl_generations;
        *self.received_ddl_arrivals.write() = stage.mirrors.received_ddl_arrivals;
        *self.superseded_ddl_occurrences.write() = stage.mirrors.superseded_ddl_occurrences;
        *self.sync_tombstone_arrivals.write() = stage.mirrors.source_state;
        *self.accepted_sync_row_authors.write() = stage.mirrors.accepted_authors;
        *self.terminal_refusal_markers.write() = stage.mirrors.terminal_markers;
        *self.terminal_refusal_scans.write() = stage.mirrors.terminal_scans;
        *self.in_memory_applied_push_watermarks.lock() =
            stage.mirrors.receipt_and_applied_watermarks;
        *self.ddl_log.write() = stage.persistence.ddl_log_replacement;
        publish_prepared_change_log_entries(
            &self.change_log,
            &self.change_log_table_index,
            &self.change_log_lsn_refcounts,
            &stage.structurally_dropped_tables,
            stage.change_log_entries,
        );
        self.relational_store
            .fetch_max_next_row_id(stage.next_row_id);
        stage.memory_swap.commit_after_swap();
    }

    /// Test helper for the received-schema transaction-manager hand-off.
    #[cfg(test)]
    fn commit_received_schema_stage_for_test(
        &self,
        changes: &ChangeSet,
        received: &crate::protocol::ReceivedDdlContext,
        validated_lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        arrivals: &HashMap<Lsn, Option<Lsn>>,
        fail_after_stage_registration: bool,
    ) -> Result<()> {
        self.commit_received_schema_stage_with_receipt_for_test(
            changes,
            received,
            validated_lineages,
            arrivals,
            None,
            fail_after_stage_registration,
        )
        .map(|_| ())
    }

    /// Commit one authenticated received-schema unit through the prepared
    /// whole-migration stage. An identical durable manifest returns its
    /// stored result before beginning another transaction.
    #[allow(clippy::too_many_arguments)]
    fn commit_received_schema_stage<F, G>(
        &self,
        changes: &ChangeSet,
        received: &crate::protocol::ReceivedDdlContext,
        validated_lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        arrivals: &HashMap<Lsn, Option<Lsn>>,
        adoption: SyncAdoption,
        receipt: Option<SyncApplyReceipt>,
        dependency_complete: bool,
        terminal_refusal_context: Option<&TerminalRefusalPullContext>,
        hub_local_author: Option<&str>,
        apply_preflight: F,
        after_stage_registration: G,
    ) -> Result<crate::protocol::WireApplyResult>
    where
        F: FnOnce() -> Result<()>,
        G: FnOnce() -> Result<()>,
    {
        let _manifest_lock = self.received_schema_manifest_lock.lock();
        if let ReceivedSchemaManifestClassification::Replay(result) =
            self.classify_received_schema_manifest(received)?
        {
            return Ok(result);
        }
        apply_preflight()?;
        let tx = self.begin()?;
        // The after-apply publisher consumes the stage and records its result
        // only after Redb succeeds, immediately before publication moves the
        // prepared memory image into place.
        let committed_result = std::cell::RefCell::new(None);
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.config_writes.push((
                "__contextdb.received_schema_stage".to_string(),
                RedbPersistence::encode_config_value(&true)?,
            ));
            Ok::<(), Error>(())
        })??;
        self.tx_mgr
            .commit_with_lsn_active_prepare_and_applied_mut(
                tx,
                |lsn, receiver_tx| {
                    let stage = self.prepare_received_schema_stage_with_adjudication(
                        lsn,
                        changes,
                        received,
                        validated_lineages,
                        ReceivedSchemaAdjudicationInputs {
                            arrivals,
                            adoption,
                            receipt: receipt.clone(),
                            dependency_complete,
                            terminal_refusal_context,
                            hub_local_author,
                            receiver_tx,
                        },
                    )?;
                    self.register_received_schema_stage(lsn, stage);
                    after_stage_registration()?;
                    Ok(())
                },
                |write_set| {
                    let lsn = write_set.commit_lsn.ok_or_else(|| {
                        Error::Other("received-schema commit lacks an LSN".to_string())
                    })?;
                    let replacement = self
                        .received_schema_stages
                        .lock()
                        .get(&lsn)
                        .map(|stage| stage.write_set.clone())
                        .ok_or_else(|| {
                            Error::Other(
                                "received-schema stage disappeared before prepare".to_string(),
                            )
                        })?;
                    *write_set = replacement;
                    Ok(())
                },
                |lsn, _| {
                    if let Some(stage) = self.take_received_schema_stage(lsn) {
                        *committed_result.borrow_mut() = Some(
                            crate::protocol::WireApplyResult::from(stage.apply_result.clone()),
                        );
                        self.publish_received_schema_stage(stage);
                    }
                },
            )
            .map_err(|failure| {
                if let Some(lsn) = failure.write_set.as_ref().and_then(|ws| ws.commit_lsn) {
                    let _ = self.take_received_schema_stage(lsn);
                }
                failure.error
            })?;
        let result = committed_result.into_inner().ok_or_else(|| {
            Error::Other(
                "received-schema commit completed without publishing its staged result".to_string(),
            )
        })?;
        // Received schema changes can create, alter, or drop retention/history
        // declarations. Reconcile only after the prepared image is durably
        // committed and published, so the receiver's worker sees the same
        // schema the caller can now observe.
        self.reconcile_maintenance_thread();
        Ok(result)
    }

    /// Test-only received-schema bridge which carries the authenticated
    /// receipt and returns the detached adjudicator's committed outcome.
    #[cfg(test)]
    fn commit_received_schema_stage_with_receipt_for_test(
        &self,
        changes: &ChangeSet,
        received: &crate::protocol::ReceivedDdlContext,
        validated_lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        arrivals: &HashMap<Lsn, Option<Lsn>>,
        receipt: Option<SyncApplyReceipt>,
        fail_after_stage_registration: bool,
    ) -> Result<crate::protocol::WireApplyResult> {
        let dependency_complete = receipt
            .as_ref()
            .is_some_and(|receipt| receipt.dependency_complete);
        self.commit_received_schema_stage(
            changes,
            received,
            validated_lineages,
            arrivals,
            SyncAdoption::Continuing,
            receipt,
            dependency_complete,
            None,
            None,
            || Ok(()),
            || {
                if fail_after_stage_registration {
                    return Err(Error::Other(
                        "injected received-schema prepare failure".to_string(),
                    ));
                }
                Ok(())
            },
        )
    }

    fn durable_row_lineage_config_key(
        table: &str,
        natural_key: &NaturalKey,
        generation: u64,
    ) -> String {
        format!(
            "sync_row_lineage.v1.{generation:016x}.{}",
            Self::hex_component(&sync_identity_key(table, natural_key))
        )
    }

    fn durable_unbound_creation_config_key(
        table: &str,
        natural_key: &NaturalKey,
        generation: u64,
        local_row_id: RowId,
    ) -> String {
        format!(
            "sync_creation_lineage.v1.{generation:016x}.{:016x}.{}",
            local_row_id.0,
            Self::hex_component(&sync_identity_key(table, natural_key))
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn lineage_attestation_bytes(
        tenant_id: &TenantId,
        table: &str,
        natural_key: &NaturalKey,
        generation: u64,
        author_node_id: &str,
        author_database_incarnation: Incarnation,
        author_local_mutation_position: Lsn,
        lineage_root: &str,
    ) -> Result<Vec<u8>> {
        rmp_serde::to_vec(&(
            "contextdb.row-lineage-attestation.v1",
            tenant_id.as_str(),
            table,
            natural_key.pairs(),
            generation,
            author_node_id,
            author_database_incarnation.to_hex(),
            author_local_mutation_position.0,
            lineage_root,
        ))
        .map_err(|err| Error::SyncError(format!("cannot encode lineage attestation: {err}")))
    }

    fn verify_lineage_attestation(
        tenant_id: &TenantId,
        table: &str,
        natural_key: &NaturalKey,
        lineage: &crate::protocol::WireRowLineage,
    ) -> Result<()> {
        if lineage.attestation.is_empty() {
            return Err(Error::SyncError(
                "protocol v6 row lineage is missing its creator signature".to_string(),
            ));
        }
        let bytes = Self::lineage_attestation_bytes(
            tenant_id,
            table,
            natural_key,
            lineage.table_generation,
            &lineage.author_node_id,
            lineage.author_database_incarnation,
            lineage.author_local_mutation_position,
            &lineage.lineage_root,
        )?;
        crate::identity::FabricIdentity::verify_lineage_by_node_id(
            &lineage.author_node_id,
            &bytes,
            &lineage.attestation,
        )
    }

    fn stage_local_creation_lineage(
        &self,
        tx: TxId,
        table: &str,
        natural_key: NaturalKey,
        local_row_id: RowId,
    ) -> Result<()> {
        let generation = self.durable_lineage_table_generation(table)?;
        let record = DurableUnboundCreationLineage {
            table: table.to_string(),
            natural_key: natural_key.clone(),
            table_generation: generation,
            local_row_id,
            creation_lsn: None,
        };
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.config_writes.push((
                Self::durable_unbound_creation_config_key(
                    table,
                    &natural_key,
                    generation,
                    local_row_id,
                ),
                RedbPersistence::encode_config_value(&record)?,
            ));
            Ok(())
        })?
    }

    fn stamp_unbound_creation_lineages_at_commit(
        &self,
        ws: &mut contextdb_tx::WriteSet,
    ) -> Result<()> {
        let Some(lsn) = ws.commit_lsn else {
            return Ok(());
        };
        self.stamp_durable_delete_positions_at_commit(ws)?;
        let mut creation_positions = HashMap::new();
        for (key, encoded) in &mut ws.config_writes {
            if !key.starts_with("sync_creation_lineage.v1.") {
                continue;
            }
            let mut record: DurableUnboundCreationLineage =
                RedbPersistence::decode_config_value(encoded)?;
            record.creation_lsn = Some(lsn);
            creation_positions.insert(
                (
                    sync_identity_key(&record.table, &record.natural_key),
                    record.table_generation,
                    record.local_row_id,
                ),
                lsn,
            );
            *encoded = RedbPersistence::encode_config_value(&record)?;
        }
        for (key, encoded) in &mut ws.config_writes {
            if !key.starts_with(Self::DURABLE_LINEAGE_CONFIG_PREFIX) {
                continue;
            }
            let mut record: DurableLineageRecord = RedbPersistence::decode_config_value(encoded)?;
            if record.delete_lsn == 0 {
                record.delete_lsn = lsn.0;
            }
            if record.author_node_id.is_none()
                && let Some(creation_lsn) = creation_positions.get(&(
                    sync_identity_key(&record.table, &record.natural_key),
                    record.table_generation,
                    record.local_row_id.unwrap_or(RowId(0)),
                ))
            {
                record.author_local_mutation_position = creation_lsn.0;
                record.lineage_root = format!(
                    "unbound:{}:{}",
                    Self::hex_component(&sync_identity_key(&record.table, &record.natural_key)),
                    creation_lsn.0
                );
            }
            *encoded = RedbPersistence::encode_config_value(&record)?;
        }
        Ok(())
    }

    fn stamp_durable_delete_positions_at_commit(
        &self,
        ws: &mut contextdb_tx::WriteSet,
    ) -> Result<()> {
        let Some(lsn) = ws.commit_lsn else {
            return Ok(());
        };
        for (key, encoded) in &mut ws.config_writes {
            if !key.starts_with(Self::DURABLE_LINEAGE_CONFIG_PREFIX) {
                continue;
            }
            let mut record: DurableLineageRecord = RedbPersistence::decode_config_value(encoded)?;
            if record.delete_lsn == 0 {
                record.delete_lsn = lsn.0;
                *encoded = RedbPersistence::encode_config_value(&record)?;
            }
        }
        Ok(())
    }

    fn staged_unbound_creation_lineage(
        &self,
        tx: TxId,
        table: &str,
        natural_key: &NaturalKey,
        generation: u64,
        local_row_id: RowId,
    ) -> Result<Option<DurableUnboundCreationLineage>> {
        let key =
            Self::durable_unbound_creation_config_key(table, natural_key, generation, local_row_id);
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.config_writes
                .iter()
                .rev()
                .find(|(candidate, _)| candidate == &key)
                .map(|(_, encoded)| RedbPersistence::decode_config_value(encoded))
                .transpose()
        })?
    }

    #[allow(clippy::too_many_arguments)]
    fn bind_unbound_creation_lineage_with_state(
        &self,
        state: &mut InMemoryLineageState,
        tenant_id: &TenantId,
        table: &str,
        natural_key: &NaturalKey,
        generation: u64,
        local_row_id: RowId,
        author_node_id: &str,
        author_database_incarnation: Incarnation,
        signer: &dyn Fn(&[u8]) -> Result<Vec<u8>>,
    ) -> Result<DurableRowLineageSidecar> {
        let sidecar_key = Self::durable_row_lineage_config_key(table, natural_key, generation);
        if let Some(mut existing) = self.load_row_lineage_sidecar(state, &sidecar_key)?
            && existing.table_generation == generation
            && existing.local_row_id == Some(local_row_id)
        {
            if !existing.locally_created {
                return Err(Error::SyncError(format!(
                    "row {} {:?} has inherited lineage and cannot be rebound as a local creation",
                    table, natural_key
                )));
            }
            if existing.author_node_id == author_node_id
                && existing.author_database_incarnation == author_database_incarnation
            {
                if existing.lineage_attestation.is_empty() {
                    let bytes = Self::lineage_attestation_bytes(
                        tenant_id,
                        table,
                        natural_key,
                        existing.table_generation,
                        &existing.author_node_id,
                        existing.author_database_incarnation,
                        existing.author_local_mutation_position,
                        &existing.lineage_root,
                    )?;
                    existing.lineage_attestation = signer(&bytes)?;
                    self.store_row_lineage_sidecar(state, &sidecar_key, &existing)?;
                }
                return Ok(existing);
            }
            return Err(Error::SyncError(format!(
                "row {} {:?} is already bound to a different creation identity",
                table, natural_key
            )));
        }
        let evidence = self
            .load_unbound_creation_lineage(
                state,
                &Self::durable_unbound_creation_config_key(
                    table,
                    natural_key,
                    generation,
                    local_row_id,
                ),
            )?
            .filter(|evidence| {
                evidence.table_generation == generation
                    && evidence.local_row_id == local_row_id
                    && evidence.natural_key == *natural_key
            })
            .and_then(|evidence| evidence.creation_lsn.map(|lsn| (evidence, lsn)))
            .ok_or_else(|| {
                Error::SyncError(format!(
                    "row {} {:?} lacks committed creation evidence for provenance binding",
                    table, natural_key
                ))
            })?;
        let (evidence, creation_lsn) = evidence;
        let sidecar = DurableRowLineageSidecar {
            author_node_id: author_node_id.to_string(),
            author_database_incarnation,
            author_local_mutation_position: creation_lsn,
            table_generation: evidence.table_generation,
            lineage_root: format!(
                "author:{}:{}:{}",
                author_node_id,
                author_database_incarnation.to_hex(),
                creation_lsn.0
            ),
            lineage_attestation: Vec::new(),
            local_row_id: Some(evidence.local_row_id),
            locally_created: true,
        };
        let mut sidecar = sidecar;
        let bytes = Self::lineage_attestation_bytes(
            tenant_id,
            table,
            natural_key,
            sidecar.table_generation,
            &sidecar.author_node_id,
            sidecar.author_database_incarnation,
            sidecar.author_local_mutation_position,
            &sidecar.lineage_root,
        )?;
        sidecar.lineage_attestation = signer(&bytes)?;
        self.store_row_lineage_sidecar(state, &sidecar_key, &sidecar)?;
        Ok(sidecar)
    }

    /// Bind one still-pending delete while holding the shared lineage state.
    /// A reply that has accepted or retired this exact delete wins before this
    /// method can recreate it, for either backend.
    fn pending_delete_lineage(
        &self,
        row: &RowChange,
        tenant_id: &TenantId,
        local_node_id: &str,
        local_incarnation: Incarnation,
        signer: &dyn Fn(&[u8]) -> Result<Vec<u8>>,
    ) -> Result<Option<crate::protocol::WireRowLineage>> {
        let table_generation = self.durable_lineage_table_generation(&row.table)?;
        let record_key =
            Self::durable_lineage_config_key(&row.table, &row.natural_key, table_generation);
        let mut lineage_state = self.lineage_state_lock.lock();
        let Some(mut record) = self.load_lineage_record(&lineage_state, &record_key)? else {
            return Ok(None);
        };
        if record.table != row.table
            || record.natural_key != row.natural_key
            || record.table_generation != table_generation
            || record.delete_lsn != row.lsn.0
            || record.delete_obligation != DurableDeleteObligation::Pending
        {
            return Ok(None);
        }
        if record.locally_created {
            let locally_authenticated = record.author_node_id.is_some()
                && record.author_database_incarnation.is_some()
                && !record.lineage_attestation.is_empty();
            if locally_authenticated {
                let expected_incarnation = local_incarnation.to_hex();
                if record.author_node_id.as_deref() != Some(local_node_id)
                    || record.author_database_incarnation.as_deref()
                        != Some(expected_incarnation.as_str())
                {
                    return Err(Error::SyncError(format!(
                        "pending delete {} {:?} is already bound to a different creation identity",
                        record.table, record.natural_key
                    )));
                }
                let sidecar = Self::local_delete_sidecar_from_record(&record)?;
                let sidecar_key = Self::durable_row_lineage_config_key(
                    &record.table,
                    &record.natural_key,
                    record.table_generation,
                );
                if self.local_delete_sidecar_slot_is_eligible(
                    &lineage_state,
                    &sidecar_key,
                    sidecar
                        .local_row_id
                        .expect("local delete sidecar has a row id"),
                )? {
                    self.store_lineage_record_and_row_sidecar(
                        &mut lineage_state,
                        &record_key,
                        &record,
                        &sidecar_key,
                        &sidecar,
                    )?;
                }
            } else {
                // A fresh same-key row may now own the current sidecar. Bind
                // this old delete from its exact committed creation evidence;
                // only republish its sidecar when that slot is still safe.
                let local_row_id = record.local_row_id.ok_or_else(|| {
                    Error::SyncError(
                        "locally created pending delete lacks the pinned local row id".to_string(),
                    )
                })?;
                let evidence = self
                    .load_unbound_creation_lineage(
                        &lineage_state,
                        &Self::durable_unbound_creation_config_key(
                            &record.table,
                            &record.natural_key,
                            record.table_generation,
                            local_row_id,
                        ),
                    )?
                    .filter(|evidence| {
                        evidence.table == record.table
                            && evidence.natural_key == record.natural_key
                            && evidence.table_generation == record.table_generation
                            && evidence.local_row_id == local_row_id
                    })
                    .and_then(|evidence| evidence.creation_lsn.map(|lsn| (evidence, lsn)))
                    .ok_or_else(|| {
                        Error::SyncError(format!(
                            "pending delete {} {:?} lacks committed creation evidence for provenance binding",
                            record.table, record.natural_key
                        ))
                    })?;
                let (_, creation_lsn) = evidence;
                let lineage_root = format!(
                    "author:{}:{}:{}",
                    local_node_id,
                    local_incarnation.to_hex(),
                    creation_lsn.0
                );
                let bytes = Self::lineage_attestation_bytes(
                    tenant_id,
                    &record.table,
                    &record.natural_key,
                    record.table_generation,
                    local_node_id,
                    local_incarnation,
                    creation_lsn,
                    &lineage_root,
                )?;
                record.author_node_id = Some(local_node_id.to_string());
                record.author_database_incarnation = Some(local_incarnation.to_hex());
                record.author_local_mutation_position = creation_lsn.0;
                record.lineage_root = lineage_root;
                record.lineage_attestation = signer(&bytes)?;
                let sidecar = Self::local_delete_sidecar_from_record(&record)?;
                let sidecar_key = Self::durable_row_lineage_config_key(
                    &record.table,
                    &record.natural_key,
                    record.table_generation,
                );
                if self.local_delete_sidecar_slot_is_eligible(
                    &lineage_state,
                    &sidecar_key,
                    local_row_id,
                )? {
                    self.store_lineage_record_and_row_sidecar(
                        &mut lineage_state,
                        &record_key,
                        &record,
                        &sidecar_key,
                        &sidecar,
                    )?;
                } else {
                    self.store_lineage_record(&mut lineage_state, &record_key, &record)?;
                }
            }
        }
        let author_node_id = record.author_node_id.clone().ok_or_else(|| {
            Error::SyncError(
                "pending delete lacks its creation lineage; refusing outbound provenance repair"
                    .to_string(),
            )
        })?;
        let author_database_incarnation = record
            .author_database_incarnation
            .as_deref()
            .and_then(Incarnation::from_hex)
            .ok_or_else(|| {
                Error::SyncError("delete lineage has an invalid author incarnation".to_string())
            })?;
        Ok(Some(crate::protocol::WireRowLineage {
            author_node_id,
            author_database_incarnation,
            author_local_mutation_position: Lsn(record.author_local_mutation_position),
            table_generation: record.table_generation,
            lineage_root: record.lineage_root,
            attestation: record.lineage_attestation,
        }))
    }

    fn durable_lineage_table_generation(&self, table: &str) -> Result<u64> {
        if let Some(persistence) = &self.persistence {
            return persistence
                .load_config_value::<u64>(&Self::durable_lineage_table_generation_key(table))?
                .filter(|generation| *generation != 0)
                .ok_or_else(|| Error::StoreCorrupted {
                    path: Self::durable_lineage_table_generation_key(table),
                    reason: format!(
                        "table {table} has schema metadata but no authoritative generation"
                    ),
                });
        }
        self.in_memory_table_generations
            .lock()
            .get(table)
            .copied()
            .filter(|generation| *generation != 0)
            .ok_or_else(|| {
                Error::SyncError(format!(
                    "table {table} has no authoritative schema generation"
                ))
            })
    }

    /// Return the authoritative generation counter even when no live table
    /// currently owns it.  A dropped table deliberately retains this counter
    /// so a later same-name CREATE cannot reuse its former identity.
    fn authoritative_table_generation_counter(&self, table: &str) -> Result<u64> {
        if let Some(persistence) = &self.persistence {
            return persistence
                .load_config_value::<u64>(&Self::durable_lineage_table_generation_key(table))
                .map(|generation| generation.unwrap_or(0));
        }
        Ok(self
            .in_memory_table_generations
            .lock()
            .get(table)
            .copied()
            .unwrap_or(0))
    }

    /// Allocate the next generation before a local CREATE is persisted.  A
    /// missing record is valid only for this first CREATE; reopening a schema
    /// without its record is corruption and is never reconstructed from DDL
    /// history.
    pub(crate) fn next_table_generation_for_create(&self, table: &str) -> Result<u64> {
        if let Some(persistence) = &self.persistence {
            return persistence
                .load_config_value::<u64>(&Self::durable_lineage_table_generation_key(table))?
                .unwrap_or(0)
                .checked_add(1)
                .ok_or_else(|| {
                    Error::SyncError(format!("schema generation overflow for {table}"))
                });
        }
        self.in_memory_table_generations
            .lock()
            .get(table)
            .copied()
            .unwrap_or(0)
            .checked_add(1)
            .ok_or_else(|| Error::SyncError(format!("schema generation overflow for {table}")))
    }

    pub(crate) fn persist_created_table_generation_and_ddl(
        &self,
        name: &str,
        meta: &TableMeta,
        generation: u64,
        lsn: Lsn,
    ) -> Result<()> {
        let change = ddl_change_from_meta(name, meta);
        let generation_key = Self::durable_lineage_table_generation_key(name);
        let sidecar_key = Self::durable_ddl_generation_sidecar_key(lsn, 0);
        let encoded_generation = RedbPersistence::encode_config_value(&generation)?;
        let encoded_sidecar = RedbPersistence::encode_config_value(&DurableDdlGenerationSidecar {
            table: Some(name.to_string()),
            table_generation: Some(generation),
        })?;
        if let Some(persistence) = &self.persistence {
            persistence.flush_table_meta_with_config_values_and_append_ddl_log(
                name,
                meta,
                vec![
                    (generation_key.as_str(), encoded_generation),
                    (sidecar_key.as_str(), encoded_sidecar),
                ],
                lsn,
                &change,
            )?;
        } else {
            self.in_memory_table_generations
                .lock()
                .insert(name.to_string(), generation);
            self.in_memory_ddl_generations
                .lock()
                .insert((lsn, 0), (Some(name.to_string()), Some(generation)));
        }
        self.ddl_log.write().push((lsn, change));
        Ok(())
    }

    fn ddl_affected_table(ddl: &DdlChange) -> Option<&str> {
        match ddl {
            DdlChange::CreateTable { name, .. }
            | DdlChange::DropTable { name }
            | DdlChange::AlterTable { name, .. } => Some(name),
            DdlChange::CreateIndex { table, .. } | DdlChange::DropIndex { table, .. } => {
                Some(table)
            }
            DdlChange::CreateTrigger { table, .. }
            | DdlChange::CreateTriggerIncludingSync { table, .. }
            | DdlChange::CreateEventType { table, .. }
            | DdlChange::CreateRoute { table, .. }
            | DdlChange::DropRoute { table, .. }
                if !table.is_empty() =>
            {
                Some(table)
            }
            DdlChange::DropTrigger { .. }
            | DdlChange::CreateSink { .. }
            | DdlChange::CreateTrigger { .. }
            | DdlChange::CreateTriggerIncludingSync { .. }
            | DdlChange::CreateEventType { .. }
            | DdlChange::CreateRoute { .. }
            | DdlChange::DropRoute { .. } => None,
        }
    }

    fn ddl_generation_sidecar_values(
        &self,
        lsn: Lsn,
        ddl: &[DdlChange],
        start: u32,
    ) -> Result<Vec<(String, Vec<u8>)>> {
        self.ddl_generation_sidecars(ddl)?
            .into_iter()
            .enumerate()
            .map(|(offset, sidecar)| {
                let key = Self::durable_ddl_generation_sidecar_key(lsn, start + offset as u32);
                let encoded = RedbPersistence::encode_config_value(&sidecar)?;
                Ok((key, encoded))
            })
            .collect()
    }

    pub(crate) fn ddl_generation_sidecars(
        &self,
        ddl: &[DdlChange],
    ) -> Result<Vec<DurableDdlGenerationSidecar>> {
        ddl.iter()
            .map(|change| {
                let table = Self::ddl_affected_table(change).map(str::to_string);
                let table_generation = table
                    .as_deref()
                    .map(|table| self.durable_lineage_table_generation(table))
                    .transpose()?;
                Ok(DurableDdlGenerationSidecar {
                    table,
                    table_generation,
                })
            })
            .collect()
    }

    pub(crate) fn publish_in_memory_ddl_generation_sidecars(
        &self,
        lsn: Lsn,
        start: u32,
        sidecars: &[DurableDdlGenerationSidecar],
    ) {
        if self.persistence.is_some() || self.capture_detached_sync_write_set.load(Ordering::SeqCst)
        {
            return;
        }
        self.in_memory_ddl_generations
            .lock()
            .extend(sidecars.iter().enumerate().map(|(offset, sidecar)| {
                (
                    (lsn, start + offset as u32),
                    (sidecar.table.clone(), sidecar.table_generation),
                )
            }));
    }

    fn record_ddl_generation_sidecars(&self, lsn: Lsn, ddl: &[DdlChange]) -> Result<()> {
        let start = self
            .ddl_log
            .read()
            .iter()
            .filter(|(existing_lsn, _)| *existing_lsn == lsn)
            .count() as u32;
        let values = self.ddl_generation_sidecar_values(lsn, ddl, start)?;
        if let Some(persistence) = &self.persistence {
            persistence.flush_encoded_config_values(
                values
                    .iter()
                    .map(|(key, value)| (key.as_str(), value.clone()))
                    .collect(),
            )?;
        } else {
            let mut generations = self.in_memory_ddl_generations.lock();
            for (offset, change) in ddl.iter().enumerate() {
                let table = Self::ddl_affected_table(change).map(str::to_string);
                let table_generation = table
                    .as_deref()
                    .map(|table| self.durable_lineage_table_generation(table))
                    .transpose()?;
                generations.insert((lsn, start + offset as u32), (table, table_generation));
            }
        }
        Ok(())
    }

    fn durable_lineage_record(
        &self,
        table: &str,
        natural_key: &NaturalKey,
    ) -> Result<Option<DurableLineageRecord>> {
        let generation = self.durable_lineage_table_generation(table)?;
        self.durable_lineage_record_at_generation(table, natural_key, generation)
    }

    fn durable_lineage_record_at_generation(
        &self,
        table: &str,
        natural_key: &NaturalKey,
        generation: u64,
    ) -> Result<Option<DurableLineageRecord>> {
        let lineage_state = self.lineage_state_lock.lock();
        self.load_lineage_record(
            &lineage_state,
            &Self::durable_lineage_config_key(table, natural_key, generation),
        )
    }

    pub(crate) fn outbound_row_lineages(
        &self,
        changes: &ChangeSet,
        tenant_id: &TenantId,
        local_node_id: &str,
        local_incarnation: Incarnation,
        signer: &dyn Fn(&[u8]) -> Result<Vec<u8>>,
    ) -> Result<OutboundRowLineages> {
        let mut out = HashMap::new();
        // Bind before iterating so an invisible historical INSERT and its
        // later DELETE share one creator sidecar regardless of their order in
        // the outbound change set.
        for row in changes.rows.iter().filter(|row| row.deleted) {
            let _ = self.pending_delete_lineage(
                row,
                tenant_id,
                local_node_id,
                local_incarnation,
                signer,
            )?;
        }
        for row in &changes.rows {
            // A locally staged delete is no longer a live row, so its
            // config-keyed obligation is the authoritative provenance record.
            // Redb retains it across reopen; memory retains it for this
            // database life. It is stamped with the fabric identity before
            // encoding; a missing stamp is a send failure in SyncClient, never
            // attributed to the
            // relay that happens to carry it.
            if row.deleted {
                if let Some(lineage) = self.pending_delete_lineage(
                    row,
                    tenant_id,
                    local_node_id,
                    local_incarnation,
                    signer,
                )? {
                    out.insert(
                        (
                            row.table.clone(),
                            rmp_serde::to_vec(&row.natural_key)
                                .expect("sync natural key serializes"),
                            row.lsn,
                        ),
                        lineage,
                    );
                    continue;
                }
                let generation = self.durable_lineage_table_generation(&row.table)?;
                let record_key =
                    Self::durable_lineage_config_key(&row.table, &row.natural_key, generation);
                let record = {
                    let lineage_state = self.lineage_state_lock.lock();
                    self.load_lineage_record(&lineage_state, &record_key)?
                };
                let Some(record) = record else {
                    return Err(Error::SyncError(
                        "selected delete has neither matching pending nor exact accepted lineage"
                            .to_string(),
                    ));
                };
                if record.table != row.table
                    || record.natural_key != row.natural_key
                    || record.table_generation != generation
                    || record.delete_obligation != DurableDeleteObligation::Accepted
                    || record.delete_lsn != row.lsn.0
                {
                    return Err(Error::SyncError(
                        "selected delete has neither matching pending nor exact accepted lineage"
                            .to_string(),
                    ));
                }
                let author_node_id = record.author_node_id.clone().ok_or_else(|| {
                    Error::SyncError("selected accepted delete lineage lacks an author".to_string())
                })?;
                let author_database_incarnation = record
                    .author_database_incarnation
                    .as_deref()
                    .and_then(Incarnation::from_hex)
                    .ok_or_else(|| {
                        Error::SyncError(
                            "selected accepted delete lineage has an invalid author incarnation"
                                .to_string(),
                        )
                    })?;
                let expected_root = format!(
                    "author:{}:{}:{}",
                    author_node_id,
                    author_database_incarnation.to_hex(),
                    record.author_local_mutation_position,
                );
                if record.lineage_root != expected_root {
                    return Err(Error::SyncError(
                        "selected accepted delete lineage has an invalid creator root".to_string(),
                    ));
                }
                let lineage = crate::protocol::WireRowLineage {
                    author_node_id,
                    author_database_incarnation,
                    author_local_mutation_position: Lsn(record.author_local_mutation_position),
                    table_generation: record.table_generation,
                    lineage_root: record.lineage_root,
                    attestation: record.lineage_attestation,
                };
                Self::verify_lineage_attestation(tenant_id, &row.table, &row.natural_key, &lineage)
                    .map_err(|_| {
                        Error::SyncError(
                            "selected accepted delete lineage has an invalid attestation"
                                .to_string(),
                        )
                    })?;
                out.insert(
                    (
                        row.table.clone(),
                        rmp_serde::to_vec(&row.natural_key).expect("sync natural key serializes"),
                        row.lsn,
                    ),
                    lineage,
                );
                continue;
            }

            // Push does not invent the creation position: before wire
            // encoding it binds exact committed unbound creation evidence to
            // the stable authenticated identity, and retries reuse that bound
            // sidecar. Sampling a live row/current LSN here races compaction
            // and turns a retry into a different creator tuple.
            let live_row = self
                .row_id_for_natural_key_full(&row.table, &row.natural_key, self.snapshot_for_read())
                .and_then(|row_id| {
                    self.row_visible_at_snapshot(&row.table, row_id, self.snapshot_for_read())
                });
            let generation = self.durable_lineage_table_generation(&row.table)?;
            let sidecar_key =
                Self::durable_row_lineage_config_key(&row.table, &row.natural_key, generation);
            let sidecar = {
                let mut lineage_state = self.lineage_state_lock.lock();
                let sidecar = self
                    .load_row_lineage_sidecar(&lineage_state, &sidecar_key)?
                    .filter(|sidecar| {
                        match (
                            sidecar.local_row_id,
                            live_row.as_ref().map(|live| live.row_id),
                        ) {
                            // A visible row with no bound local instance is a
                            // fresh explicit same-key creation after a delete. It
                            // must have been staged at its INSERT, never invented
                            // during send.
                            (None, Some(_)) => false,
                            // A deleted row can still be relayed; retain its
                            // previous immutable root even though there is no
                            // visible row.
                            (_, None) => true,
                            (Some(bound), Some(live)) => bound == live,
                        }
                    });
                match sidecar.filter(|sidecar| !sidecar.lineage_attestation.is_empty()) {
                    Some(sidecar) => {
                        if sidecar.locally_created {
                            let local_row_id = sidecar.local_row_id.ok_or_else(|| {
                                Error::SyncError(format!(
                                    "locally created row {} {:?} lacks its pinned local row",
                                    row.table, row.natural_key
                                ))
                            })?;
                            self.bind_unbound_creation_lineage_with_state(
                                &mut lineage_state,
                                tenant_id,
                                &row.table,
                                &row.natural_key,
                                generation,
                                local_row_id,
                                local_node_id,
                                local_incarnation,
                                signer,
                            )?
                        } else {
                            sidecar
                        }
                    }
                    None => {
                        let local_row_id =
                            live_row.as_ref().map(|row| row.row_id).ok_or_else(|| {
                                Error::SyncError(format!(
                                    "row {} {:?} has no pinned local row for creation-lineage binding",
                                    row.table, row.natural_key
                                ))
                            })?;
                        self.bind_unbound_creation_lineage_with_state(
                            &mut lineage_state,
                            tenant_id,
                            &row.table,
                            &row.natural_key,
                            generation,
                            local_row_id,
                            local_node_id,
                            local_incarnation,
                            signer,
                        )?
                    }
                }
            };
            out.insert(
                (
                    row.table.clone(),
                    rmp_serde::to_vec(&row.natural_key).expect("sync natural key serializes"),
                    row.lsn,
                ),
                crate::protocol::WireRowLineage {
                    author_node_id: sidecar.author_node_id,
                    author_database_incarnation: sidecar.author_database_incarnation,
                    author_local_mutation_position: sidecar.author_local_mutation_position,
                    table_generation: sidecar.table_generation,
                    lineage_root: sidecar.lineage_root,
                    attestation: sidecar.lineage_attestation,
                },
            );
        }
        Ok(out)
    }

    /// Advance one pull-page projection only from the exact authenticated DDL
    /// vector that accompanied this unit. The generation overlay never
    /// reconstructs evidence from schema text, while the direction overlay
    /// mirrors the CREATE/ALTER/DROP semantics of
    /// `latest_declared_table_directions` in received-vector order.
    pub(crate) fn advance_authenticated_pull_schema_projection(
        &self,
        table_generations: &mut HashMap<String, u64>,
        directions: &mut HashMap<String, SyncDirection>,
        changes: &ChangeSet,
        received_ddl: Option<&crate::protocol::ReceivedDdlContext>,
    ) -> Result<()> {
        if changes.ddl.is_empty() {
            return Ok(());
        }
        let received_ddl = received_ddl.ok_or_else(|| {
            Error::SyncError(
                "pull schema projection requires authenticated DDL provenance".to_string(),
            )
        })?;
        if changes.ddl.len() != changes.ddl_lsn.len()
            || changes.ddl.len() != received_ddl.entries.len()
        {
            return Err(Error::SyncError(
                "authenticated pull schema projection does not cover the exact DDL vector"
                    .to_string(),
            ));
        }
        for ((change, source_lsn), entry) in changes
            .ddl
            .iter()
            .zip(changes.ddl_lsn.iter())
            .zip(received_ddl.entries.iter())
        {
            if *source_lsn != entry.source_ddl_lsn {
                return Err(Error::SyncError(
                    "pull schema projection source LSN differs from authenticated DDL provenance"
                        .to_string(),
                ));
            }
            let table = Self::ddl_affected_table(change);
            if table != entry.table.as_deref() {
                return Err(Error::SyncError(
                    "pull schema projection table differs from authenticated DDL provenance"
                        .to_string(),
                ));
            }
            if let (Some(table), Some(generation)) = (table, entry.table_generation) {
                table_generations.insert(table.to_string(), generation);
            }
            match change {
                DdlChange::CreateTable {
                    name, constraints, ..
                } => {
                    let direction = constraints
                        .iter()
                        .find_map(|constraint| constraint_declares_sync_direction(constraint))
                        .unwrap_or(contextdb_core::DEFAULT_SYNC_DIRECTION);
                    directions.insert(name.clone(), direction);
                }
                DdlChange::AlterTable {
                    name, constraints, ..
                } => {
                    if let Some(direction) = constraints
                        .iter()
                        .find_map(|constraint| constraint_declares_sync_direction(constraint))
                    {
                        directions.insert(name.clone(), direction);
                    }
                }
                // As the durable projection does, retain the final declared
                // direction after DROP so the former generation cannot become
                // eligible merely because its live metadata disappears.
                DdlChange::DropTable { .. } => {}
                _ => {}
            }
        }
        Ok(())
    }

    /// Verify every received row against an explicitly authenticated
    /// page-generation projection. A table missing from the projection uses
    /// the durable local generation; an entry in the projection is never
    /// inferred from DDL text or another unit's context.
    pub(crate) fn validate_received_row_lineages_against_generation_projection(
        &self,
        tenant_id: &TenantId,
        changes: &ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        table_generations: &HashMap<String, u64>,
    ) -> Result<()> {
        for row in &changes.rows {
            let matching = lineages
                .iter()
                .filter(|(table, natural_key, lsn, _)| {
                    table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn
                })
                .collect::<Vec<_>>();
            if matching.len() != 1 {
                return Err(Error::SyncError(format!(
                    "protocol v6 requires exactly one lineage for {} {:?} at source LSN {}",
                    row.table, row.natural_key, row.lsn.0
                )));
            }
            let lineage = &matching[0].3;
            let generation = if let Some(generation) = table_generations.get(&row.table) {
                *generation
            } else {
                self.durable_lineage_table_generation(&row.table)?
            };
            if lineage.table_generation != generation {
                return Err(Error::SyncError(format!(
                    "wire row lineage generation {} does not match the authenticated projected generation {} for table {}",
                    lineage.table_generation, generation, row.table
                )));
            }
            let expected_root = format!(
                "author:{}:{}:{}",
                lineage.author_node_id,
                lineage.author_database_incarnation.to_hex(),
                lineage.author_local_mutation_position.0,
            );
            if lineage.lineage_root != expected_root {
                return Err(Error::SyncError(
                    "wire row lineage root does not match its immutable creator tuple".to_string(),
                ));
            }
            Self::verify_lineage_attestation(tenant_id, &row.table, &row.natural_key, lineage)?;
        }
        Ok(())
    }

    /// Validate the amended-v6 provenance before any row mutation. Every data
    /// row has exactly one full-identity sidecar, its root must be the creator
    /// tuple's canonical root, and its table generation must still be live.
    pub(crate) fn validate_received_row_lineages(
        &self,
        tenant_id: &TenantId,
        changes: &ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
    ) -> Result<()> {
        if !changes.ddl.is_empty() {
            return Err(Error::SyncError(
                "received rows beside schema DDL require an authenticated whole-unit schema plan"
                    .to_string(),
            ));
        }
        self.validate_received_row_lineages_against_generation_projection(
            tenant_id,
            changes,
            lineages,
            &HashMap::new(),
        )
    }

    /// The authenticated schema path validates rows against the generation
    /// projected by the ordered received DDL vector, not the receiver's
    /// pre-apply metadata. The raw path above remains deliberately
    /// fail-closed when DDL is present.
    pub(crate) fn validate_received_row_lineages_with_received_ddl(
        &self,
        tenant_id: &TenantId,
        changes: &ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        received_ddl: &crate::protocol::ReceivedDdlContext,
    ) -> Result<()> {
        let mut projected_generations = HashMap::<String, u64>::new();
        for entry in &received_ddl.entries {
            if let (Some(table), Some(generation)) = (&entry.table, entry.table_generation) {
                projected_generations.insert(table.clone(), generation);
            }
        }
        self.validate_received_row_lineages_against_generation_projection(
            tenant_id,
            changes,
            lineages,
            &projected_generations,
        )
    }

    /// An authenticated push can introduce a creator only from the sending
    /// edge's current database incarnation. A relayed creator must already
    /// be the committed config-keyed provenance for this exact
    /// table/key/generation; Redb retains it across reopen and memory retains
    /// it for this database life. A peer cannot forge a new ancestry by
    /// choosing someone else's author tuple.
    pub(crate) fn validate_incoming_push_lineages(
        &self,
        tenant_id: &TenantId,
        changes: &ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        authenticated_peer: &str,
        sender_incarnation: Incarnation,
    ) -> Result<()> {
        self.validate_received_row_lineages(tenant_id, changes, lineages)?;
        self.validate_incoming_push_lineage_authorship(
            changes,
            lineages,
            authenticated_peer,
            sender_incarnation,
        )
    }

    fn validate_incoming_push_lineage_authorship(
        &self,
        changes: &ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        authenticated_peer: &str,
        sender_incarnation: Incarnation,
    ) -> Result<()> {
        for row in &changes.rows {
            let (_, _, _, lineage) = lineages
                .iter()
                .find(|(table, natural_key, lsn, _)| {
                    table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn
                })
                .expect("validated exact row lineage");
            if lineage.author_node_id == authenticated_peer
                && lineage.author_database_incarnation == sender_incarnation
            {
                continue;
            }
            let lineage_state = self.lineage_state_lock.lock();
            let known = self.load_row_lineage_sidecar(
                &lineage_state,
                &Self::durable_row_lineage_config_key(
                    &row.table,
                    &row.natural_key,
                    lineage.table_generation,
                ),
            )?;
            if !known.is_some_and(|known| Self::row_lineage_matches_wire(&known, lineage)) {
                // The creator's valid signature is portable provenance. A
                // freshly rebuilt hub need not have received this lineage
                // before it relays the row onward.
                if lineage.author_node_id.is_empty() {
                    return Err(Error::SyncError(format!(
                        "relayed row {} {:?} has no creator provenance",
                        row.table, row.natural_key
                    )));
                }
            }
        }
        Ok(())
    }

    fn row_lineage_matches_wire(
        known: &DurableRowLineageSidecar,
        lineage: &crate::protocol::WireRowLineage,
    ) -> bool {
        known.table_generation == lineage.table_generation
            && known.author_node_id == lineage.author_node_id
            && known.author_database_incarnation == lineage.author_database_incarnation
            && known.author_local_mutation_position == lineage.author_local_mutation_position
            && known.lineage_root == lineage.lineage_root
            && known.lineage_attestation == lineage.attestation
    }

    /// Identify only fresh deletes authored by the creator whose immutable
    /// lineage the receiver already committed for this exact row instance.
    /// This is the narrow continuation KEEP FIRST permits: a competing edge,
    /// a relay, a stale ordered replay, or a same-key replacement all fail at
    /// least one of these checks.
    fn authenticated_fresh_creator_deletes(
        &self,
        rows: &[RowChange],
        arrivals: &HashMap<Lsn, Option<Lsn>>,
        receipt: Option<&SyncApplyReceipt>,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
    ) -> Result<Vec<AuthenticatedFreshCreatorDelete>> {
        let Some(receipt) = receipt else {
            return Ok(Vec::new());
        };
        let snapshot = self.snapshot();
        let empty_cache = HashMap::new();
        let empty_deleted = HashSet::new();
        let mut permitted = Vec::new();

        for row in rows {
            if !row.deleted || Self::resolve_incoming_arrival(row, arrivals).is_some() {
                continue;
            }
            let Some((_, _, _, lineage)) = lineages.iter().find(|(table, natural_key, lsn, _)| {
                table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn
            }) else {
                continue;
            };
            if lineage.author_node_id != receipt.node_id
                || lineage.author_database_incarnation != receipt.incarnation
            {
                continue;
            }
            if self.table_meta(&row.table).is_none() {
                continue;
            }
            let Some(local) = sync_visible_point_lookup(
                self,
                &empty_cache,
                &row.table,
                &row.natural_key,
                snapshot,
                &empty_deleted,
            )?
            else {
                continue;
            };
            let lineage_key = Self::durable_row_lineage_config_key(
                &row.table,
                &row.natural_key,
                lineage.table_generation,
            );
            let lineage_state = self.lineage_state_lock.lock();
            let known = self.load_row_lineage_sidecar(&lineage_state, &lineage_key)?;
            if known.as_ref().is_some_and(|known| {
                known.local_row_id == Some(local.row_id)
                    && Self::row_lineage_matches_wire(known, lineage)
            }) {
                permitted.push(AuthenticatedFreshCreatorDelete {
                    table: row.table.clone(),
                    natural_key: row.natural_key.clone(),
                    lsn: row.lsn,
                    row_id: local.row_id,
                    values: local.values,
                });
            }
        }
        Ok(permitted)
    }

    fn authenticated_fresh_creator_delete_permission<'a>(
        row: &RowChange,
        local: &VersionedRow,
        policy: ConflictPolicy,
        permitted: &'a [AuthenticatedFreshCreatorDelete],
    ) -> Option<&'a AuthenticatedFreshCreatorDelete> {
        (policy == ConflictPolicy::InsertIfNotExists)
            .then(|| {
                permitted.iter().find(|permission| {
                    permission.table == row.table
                        && permission.natural_key == row.natural_key
                        && permission.lsn == row.lsn
                        && permission.row_id == local.row_id
                })
            })
            .flatten()
    }

    pub(crate) fn validate_incoming_push_lineages_with_received_ddl(
        &self,
        tenant_id: &TenantId,
        changes: &ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        authenticated_peer: &str,
        sender_incarnation: Incarnation,
        received_ddl: &crate::protocol::ReceivedDdlContext,
    ) -> Result<()> {
        self.validate_received_row_lineages_with_received_ddl(
            tenant_id,
            changes,
            lineages,
            received_ddl,
        )?;
        self.validate_incoming_push_lineage_authorship(
            changes,
            lineages,
            authenticated_peer,
            sender_incarnation,
        )
    }

    fn classify_purged_lineage_descendants(
        &self,
        changes: ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
    ) -> Result<PurgedLineageRefusal> {
        let projected_meta = self.projected_sync_table_meta(&changes.ddl);
        let policies = Self::declared_sync_policies(true);
        let mut retained_rows = Vec::with_capacity(changes.rows.len());
        let mut refused_rows = Vec::new();
        let mut conflicts = Vec::new();
        let mut refused_vector_indexes = HashSet::new();
        let mut vector_cursor = 0usize;
        for row in &changes.rows {
            let matching = lineages
                .iter()
                .filter(|(table, natural_key, lsn, _)| {
                    table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn
                })
                .collect::<Vec<_>>();
            if matching.len() != 1 {
                return Err(Error::SyncError(format!(
                    "purged-lineage classification requires exactly one validated lineage for {} {:?} at source LSN {}",
                    row.table, row.natural_key, row.lsn.0
                )));
            }
            let lineage = &matching[0].3;
            let record = self.durable_lineage_record_at_generation(
                &row.table,
                &row.natural_key,
                lineage.table_generation,
            )?;
            let creator_incarnation = lineage.author_database_incarnation.to_hex();
            let matches_purged_lineage = record.is_some_and(|record| {
                record.delete_obligation == DurableDeleteObligation::Purged
                    && record.table == row.table
                    && record.natural_key == row.natural_key
                    && record.table_generation == lineage.table_generation
                    && record.lineage_root == lineage.lineage_root
                    && record.author_node_id.as_deref() == Some(lineage.author_node_id.as_str())
                    && record.author_database_incarnation.as_deref()
                        == Some(creator_incarnation.as_str())
                    && record.author_local_mutation_position
                        == lineage.author_local_mutation_position.0
            });
            let row_has_vector = projected_meta.get(&row.table).is_some_and(|meta| {
                meta.columns
                    .iter()
                    .any(|column| matches!(column.column_type, ColumnType::Vector(_)))
            });
            let vector_group = (row_has_vector
                && next_vector_row_group_matches(&changes.vectors, vector_cursor, row))
            .then(|| vector_row_group_end(&changes.vectors, vector_cursor));
            if matches_purged_lineage {
                if let Some(end) = vector_group {
                    refused_vector_indexes.extend(vector_cursor..end);
                    vector_cursor = end;
                }
                refused_rows.push(row.clone());
                conflicts.push(Conflict {
                    natural_key: row.natural_key.clone(),
                    resolution: Self::sync_conflict_policy_for_table(
                        &policies,
                        self.table_meta(&row.table).as_ref(),
                        &row.table,
                    ),
                    reason: Some(crate::sync_types::PURGED_LINEAGE_CONFLICT_REASON.to_string()),
                    table: Some(row.table.clone()),
                    mutation_kind: Some(if row.deleted { "delete" } else { "edit" }.to_string()),
                    winning_author_node_id: None,
                    hub_acceptance_position: None,
                });
                continue;
            }
            retained_rows.push(row.clone());
            if let Some(end) = vector_group {
                vector_cursor = end;
            }
        }
        let vectors = changes
            .vectors
            .into_iter()
            .enumerate()
            .filter_map(|(index, vector)| {
                (!refused_vector_indexes.contains(&index)).then_some(vector)
            })
            .collect();
        Ok(PurgedLineageRefusal {
            changes: ChangeSet {
                rows: retained_rows,
                vectors,
                edges: changes.edges,
                ddl: changes.ddl,
                ddl_lsn: changes.ddl_lsn,
            },
            refused_rows,
            conflicts,
        })
    }

    /// Return one terminal, row-addressable refusal for each incoming row
    /// whose authenticated lineage belongs to a retired table generation.
    /// A purged root keeps its stronger permanent-erasure reason; every other
    /// row from that generation is refused as removed-generation work.  The
    /// caller may send this receipt only when it covers the whole request, so
    /// no unclassified member can mutate beside it.
    pub(crate) fn retired_generation_refusals(
        &self,
        tenant_id: &TenantId,
        changes: &ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        authenticated_peer: &str,
        sender_incarnation: Incarnation,
    ) -> Result<Vec<Conflict>> {
        // Verify the immutable, portable creator evidence before consulting a
        // retired generation.  A relay is allowed to carry a creator's signed
        // lineage, but an unauthenticated or malformed row must never learn
        // whether that old key was purged or merely belongs to a removed table.
        for row in &changes.rows {
            let matching = lineages
                .iter()
                .filter(|(table, natural_key, lsn, _)| {
                    table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn
                })
                .collect::<Vec<_>>();
            if matching.len() != 1 {
                return Err(Error::SyncError(format!(
                    "protocol v6 requires exactly one lineage for {} {:?} at source LSN {}",
                    row.table, row.natural_key, row.lsn.0
                )));
            }
            let lineage = &matching[0].3;
            let expected_root = format!(
                "author:{}:{}:{}",
                lineage.author_node_id,
                lineage.author_database_incarnation.to_hex(),
                lineage.author_local_mutation_position.0,
            );
            if lineage.lineage_root != expected_root {
                return Err(Error::SyncError(
                    "wire row lineage root does not match its immutable creator tuple".to_string(),
                ));
            }
            Self::verify_lineage_attestation(tenant_id, &row.table, &row.natural_key, lineage)?;
        }
        self.validate_incoming_push_lineage_authorship(
            changes,
            lineages,
            authenticated_peer,
            sender_incarnation,
        )?;

        let policies = Self::declared_sync_policies(true);
        let mut conflicts = Vec::new();
        for row in &changes.rows {
            let matching = lineages
                .iter()
                .filter(|(table, natural_key, lsn, _)| {
                    table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn
                })
                .collect::<Vec<_>>();
            if matching.len() != 1 {
                return Err(Error::SyncError(format!(
                    "protocol v6 requires exactly one lineage for {} {:?} at source LSN {}",
                    row.table, row.natural_key, row.lsn.0
                )));
            }
            let lineage = &matching[0].3;
            let current_generation = self.durable_lineage_table_generation(&row.table)?;
            // Only an older, retired table generation has a terminal
            // no-retry outcome. A future generation is not evidence of
            // retirement; leave it for the ordinary authenticated projection
            // check, which fails closed rather than acknowledging unknown data.
            if lineage.table_generation >= current_generation {
                continue;
            }
            let record = self.durable_lineage_record_at_generation(
                &row.table,
                &row.natural_key,
                lineage.table_generation,
            )?;
            let creator_incarnation = lineage.author_database_incarnation.to_hex();
            let purged_lineage = record.is_some_and(|record| {
                record.delete_obligation == DurableDeleteObligation::Purged
                    && record.lineage_root == lineage.lineage_root
                    && record.author_node_id.as_deref() == Some(lineage.author_node_id.as_str())
                    && record.author_database_incarnation.as_deref()
                        == Some(creator_incarnation.as_str())
                    && record.author_local_mutation_position
                        == lineage.author_local_mutation_position.0
            });
            conflicts.push(Conflict {
                natural_key: row.natural_key.clone(),
                resolution: Self::sync_conflict_policy_for_table(
                    &policies,
                    self.table_meta(&row.table).as_ref(),
                    &row.table,
                ),
                reason: Some(
                    if purged_lineage {
                        crate::sync_types::PURGED_LINEAGE_CONFLICT_REASON
                    } else {
                        crate::sync_types::REMOVED_GENERATION_CONFLICT_REASON
                    }
                    .to_string(),
                ),
                table: Some(row.table.clone()),
                mutation_kind: Some(if row.deleted { "delete" } else { "edit" }.to_string()),
                winning_author_node_id: None,
                hub_acceptance_position: None,
            });
        }
        Ok(conflicts)
    }

    /// Commit the authenticated edge receipt for a push whose every row was
    /// terminally refused before the normal row-apply path.  The receipt is
    /// the durable acknowledgement boundary: a dropped response can then be
    /// reconciled by the edge without retransmitting the same retired rows.
    pub(crate) fn commit_terminal_sync_refusals_with_receipt(
        &self,
        receipt: SyncApplyReceipt,
        row_count: usize,
        conflicts: Vec<Conflict>,
    ) -> Result<ApplyResult> {
        if row_count == 0 || conflicts.len() != row_count {
            return Err(Error::SyncError(
                "terminal sync refusal receipt must cover every transmitted row".to_string(),
            ));
        }
        self.commit_sync_apply_receipt_only(&receipt)?;
        if self.persistence.is_none() {
            let key = Self::applied_push_watermark_node_incarnation_key(
                &receipt.tenant_id,
                &receipt.node_id,
                receipt.incarnation,
            );
            self.in_memory_applied_push_watermarks
                .lock()
                .entry(key)
                .and_modify(|current| *current = (*current).max(receipt.source_lsn))
                .or_insert(receipt.source_lsn);
        }
        Ok(ApplyResult {
            applied_rows: 0,
            skipped_rows: row_count,
            conflicts,
            new_lsn: self.current_lsn(),
        })
    }

    fn changeset_is_wholly_empty(changes: &ChangeSet) -> bool {
        changes.rows.is_empty()
            && changes.vectors.is_empty()
            && changes.edges.is_empty()
            && changes.ddl.is_empty()
            && changes.ddl_lsn.is_empty()
    }

    /// Ordinary pulls suppress an exact replay only after the accepted delete
    /// still owns an absent full natural key. Dependency-complete units remain
    /// atomic: a matching terminated member rejects the whole unit.
    pub(crate) fn drop_accepted_lineage_replays_against_generation_projection(
        &self,
        tenant_id: &TenantId,
        changes: ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        table_generations: &HashMap<String, u64>,
    ) -> Result<AcceptedDeleteSuppression> {
        self.validate_received_row_lineages_against_generation_projection(
            tenant_id,
            &changes,
            lineages,
            table_generations,
        )?;
        self.suppress_accepted_lineage_replays_with_generation_projection(
            changes,
            lineages,
            false,
            table_generations,
        )
    }

    #[cfg(test)]
    fn reject_dependency_complete_accepted_lineage_replays(
        &self,
        tenant_id: &TenantId,
        changes: ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
    ) -> Result<AcceptedDeleteSuppression> {
        self.validate_received_row_lineages(tenant_id, &changes, lineages)?;
        self.suppress_accepted_lineage_replays(changes, lineages, true)
    }

    pub(crate) fn reject_dependency_complete_accepted_lineage_replays_against_generation_projection(
        &self,
        tenant_id: &TenantId,
        changes: ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        table_generations: &HashMap<String, u64>,
    ) -> Result<AcceptedDeleteSuppression> {
        self.validate_received_row_lineages_against_generation_projection(
            tenant_id,
            &changes,
            lineages,
            table_generations,
        )?;
        self.suppress_accepted_lineage_replays_with_generation_projection(
            changes,
            lineages,
            true,
            table_generations,
        )
    }

    /// Push has no ordinary-pull cursor to consume a suppressed replay. Keep
    /// its accepted-delete check strict and return the original changes only
    /// after every live member has cleared the dependency-style classifier.
    pub(crate) fn reject_accepted_lineage_replays(
        &self,
        tenant_id: &TenantId,
        changes: ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
    ) -> Result<ChangeSet> {
        self.validate_received_row_lineages(tenant_id, &changes, lineages)?;
        Ok(self
            .suppress_accepted_lineage_replays(changes, lineages, true)?
            .changes)
    }

    pub(crate) fn reject_accepted_lineage_replays_with_received_ddl(
        &self,
        tenant_id: &TenantId,
        changes: ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        received_ddl: &crate::protocol::ReceivedDdlContext,
    ) -> Result<ChangeSet> {
        self.validate_received_row_lineages_with_received_ddl(
            tenant_id,
            &changes,
            lineages,
            received_ddl,
        )?;
        Ok(self
            .suppress_accepted_lineage_replays(changes, lineages, true)?
            .changes)
    }

    fn suppress_accepted_lineage_replays(
        &self,
        changes: ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        dependency_complete: bool,
    ) -> Result<AcceptedDeleteSuppression> {
        self.suppress_accepted_lineage_replays_with_generation_projection(
            changes,
            lineages,
            dependency_complete,
            &HashMap::new(),
        )
    }

    fn suppress_accepted_lineage_replays_with_generation_projection(
        &self,
        changes: ChangeSet,
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
        dependency_complete: bool,
        table_generations: &HashMap<String, u64>,
    ) -> Result<AcceptedDeleteSuppression> {
        let projected_meta = self.projected_sync_table_meta(&changes.ddl);
        let snapshot = self.snapshot();
        let skip_deleted = HashSet::new();
        let mut retained_rows = Vec::with_capacity(changes.rows.len());
        let mut suppressed_vector_indexes = HashSet::new();
        let mut vector_cursor = 0usize;
        let mut suppressed_live_replay = false;
        for row in &changes.rows {
            let row_has_vector = projected_meta.get(&row.table).is_some_and(|meta| {
                meta.columns
                    .iter()
                    .any(|column| matches!(column.column_type, ColumnType::Vector(_)))
            });
            let vector_group = (row_has_vector
                && next_vector_row_group_matches(&changes.vectors, vector_cursor, row))
            .then(|| vector_row_group_end(&changes.vectors, vector_cursor));
            if row.deleted {
                retained_rows.push(row.clone());
                if let Some(end) = vector_group {
                    vector_cursor = end;
                }
                continue;
            }
            let record = if let Some(generation) = table_generations.get(&row.table) {
                self.durable_lineage_record_at_generation(
                    &row.table,
                    &row.natural_key,
                    *generation,
                )?
            } else {
                self.durable_lineage_record(&row.table, &row.natural_key)?
            };
            let Some(record) = record else {
                retained_rows.push(row.clone());
                if let Some(end) = vector_group {
                    vector_cursor = end;
                }
                continue;
            };
            if record.delete_obligation != DurableDeleteObligation::Accepted {
                retained_rows.push(row.clone());
                if let Some(end) = vector_group {
                    vector_cursor = end;
                }
                continue;
            }
            let incoming = lineages.iter().find(|(table, natural_key, lsn, _)| {
                table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn
            });
            // An absent sidecar fails closed: it cannot prove that it is a
            // new lineage entitled to resurrect this key.
            let same_terminated_lineage = incoming.is_none_or(|(_, _, _, lineage)| {
                let creator_matches = match (
                    record.author_node_id.as_deref(),
                    record.author_database_incarnation.as_deref(),
                ) {
                    (Some(author), Some(incarnation)) => {
                        lineage.author_node_id == author
                            && lineage.author_database_incarnation.to_hex() == incarnation
                            && lineage.author_local_mutation_position.0
                                == record.author_local_mutation_position
                    }
                    // A pre-provenance durable delete cannot prove a new
                    // same-key lineage.  Its absent creator is the frozen
                    // compatibility default and safely rejects an absent or
                    // root-equal replay until a v6 creator root differs.
                    _ => true,
                };
                lineage.lineage_root == record.lineage_root && creator_matches
            });
            if same_terminated_lineage {
                if dependency_complete {
                    return Err(Error::SyncError(format!(
                        "strict received row {} {:?} replays a lineage terminated by an accepted delete",
                        row.table, row.natural_key
                    )));
                }
                let visible = if self.table_meta(&row.table).is_some() {
                    self.visible_row_by_natural_key(
                        &row.table,
                        &row.natural_key,
                        snapshot,
                        &skip_deleted,
                    )?
                } else {
                    None
                };
                if visible.is_some() {
                    return Err(Error::SyncError(format!(
                        "received row {} {:?} replays a lineage terminated by an accepted delete but a fresh same-key row is visible",
                        row.table, row.natural_key
                    )));
                }
                suppressed_live_replay = true;
                if let Some(end) = vector_group {
                    suppressed_vector_indexes.extend(vector_cursor..end);
                    vector_cursor = end;
                }
                continue;
            }
            retained_rows.push(row.clone());
            if let Some(end) = vector_group {
                vector_cursor = end;
            }
        }
        let vectors = changes
            .vectors
            .into_iter()
            .enumerate()
            .filter_map(|(index, vector)| {
                (!suppressed_vector_indexes.contains(&index)).then_some(vector)
            })
            .collect();
        Ok(AcceptedDeleteSuppression {
            changes: ChangeSet {
                rows: retained_rows,
                vectors,
                edges: changes.edges,
                ddl: changes.ddl,
                ddl_lsn: changes.ddl_lsn,
            },
            suppressed_live_replay,
        })
    }

    /// Put a local SQL delete into the same storage transaction as the row
    /// removal. Redb retains the record across close/open; an in-memory
    /// database retains it for its shared handle life. Without it the vanished
    /// row cannot be offered to the hub again.
    pub(crate) fn stage_local_delete_obligation(
        &self,
        tx: TxId,
        table: &str,
        row: &VersionedRow,
    ) -> Result<()> {
        let Some(meta) = self.table_meta(table) else {
            return Ok(());
        };
        if !matches!(
            crate::executor::effective_sync_direction(&meta),
            SyncDirection::Push | SyncDirection::Both
        ) {
            // Direction governs ordinary rows, including whether an edge owes
            // a local delete to its hub. Pull-only and OFF tables must remain
            // eligible for their ordinary authoritative pull.
            return Ok(());
        }
        let Some(natural_key) = natural_key_from_row_values(&meta, &row.values) else {
            return Ok(());
        };
        let generation = self.durable_lineage_table_generation(table)?;
        let staged_evidence =
            self.staged_unbound_creation_lineage(tx, table, &natural_key, generation, row.row_id)?;
        let lineage_state = self.lineage_state_lock.lock();
        let inherited = self
            .load_row_lineage_sidecar(
                &lineage_state,
                &Self::durable_row_lineage_config_key(table, &natural_key, generation),
            )?
            .filter(|lineage| {
                lineage.table_generation == generation && lineage.local_row_id == Some(row.row_id)
            });
        let evidence = if inherited.is_none() {
            let creation_key = Self::durable_unbound_creation_config_key(
                table,
                &natural_key,
                generation,
                row.row_id,
            );
            Some(
                staged_evidence
                    .or(self.load_unbound_creation_lineage(&lineage_state, &creation_key)?)
                    .filter(|evidence| {
                        evidence.table_generation == generation
                            && evidence.local_row_id == row.row_id
                            && evidence.natural_key == natural_key
                    })
                    .ok_or_else(|| {
                        Error::SyncError(format!(
                            "DELETE from {} {:?} lacks creation evidence",
                            table, natural_key
                        ))
                    })?,
            )
        } else {
            None
        };
        let author_node_id = inherited
            .as_ref()
            .map(|lineage| lineage.author_node_id.clone());
        let author_database_incarnation = inherited
            .as_ref()
            .map(|lineage| lineage.author_database_incarnation.to_hex());
        let author_local_mutation_position = inherited
            .as_ref()
            .map(|lineage| lineage.author_local_mutation_position.0)
            .or_else(|| {
                evidence
                    .as_ref()
                    .and_then(|evidence| evidence.creation_lsn.map(|lsn| lsn.0))
            })
            .or_else(|| evidence.as_ref().map(|_| 0))
            .expect("inherited lineage or unbound evidence exists");
        let lineage_root = inherited
            .as_ref()
            .map(|lineage| lineage.lineage_root.clone())
            .unwrap_or_else(|| {
                format!(
                    "unbound:{}:{}",
                    Self::hex_component(&sync_identity_key(table, &natural_key)),
                    evidence
                        .as_ref()
                        .and_then(|evidence| evidence.creation_lsn)
                        .map(|lsn| lsn.0)
                        .unwrap_or(0)
                )
            });
        let delete_lsn = 0;
        let record = DurableLineageRecord {
            table: table.to_string(),
            natural_key: natural_key.clone(),
            table_generation: generation,
            local_row_id: Some(row.row_id),
            locally_created: inherited
                .as_ref()
                .map(|lineage| lineage.locally_created)
                .unwrap_or(true),
            lineage_root,
            lineage_attestation: inherited
                .as_ref()
                .map(|lineage| lineage.lineage_attestation.clone())
                .unwrap_or_default(),
            author_node_id,
            author_database_incarnation,
            author_local_mutation_position,
            delete_lsn,
            delete_obligation: DurableDeleteObligation::Pending,
            accepted_hub_lsn: None,
            bound_hub_node_id: None,
            purge_frontier: None,
        };
        let key = Self::durable_lineage_config_key(table, &natural_key, generation);
        let generation_key = Self::durable_lineage_table_generation_key(table);
        let record = RedbPersistence::encode_config_value(&record)?;
        let generation = RedbPersistence::encode_config_value(&generation)?;
        // Commit-time purge fencing reads the write set before lineage state.
        // Release lineage state before staging this obligation so concurrent
        // delete staging follows that same lock order instead of inverting it.
        drop(lineage_state);
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.config_writes.push((generation_key, generation));
            ws.config_writes.push((key, record));
        })
    }

    pub(crate) fn stamp_pending_delete_author_tuple(
        &self,
        rows: &[RowChange],
        _author_node_id: &str,
        _author_database_incarnation: Incarnation,
    ) -> Result<()> {
        let lineage_state = self.lineage_state_lock.lock();
        for row in rows.iter().filter(|row| row.deleted) {
            let key = Self::durable_lineage_config_key(
                &row.table,
                &row.natural_key,
                self.durable_lineage_table_generation(&row.table)?,
            );
            let Some(record) = self.load_lineage_record(&lineage_state, &key)? else {
                continue;
            };
            if record.delete_obligation != DurableDeleteObligation::Pending
                || record.delete_lsn != row.lsn.0
            {
                continue;
            }
            if record.author_node_id.is_none() {
                return Err(Error::SyncError(
                    "pending delete lacks its creation lineage; refusing outbound provenance repair"
                        .to_string(),
                ));
            }
        }
        Ok(())
    }

    fn durable_pending_deletes_since(&self, since_lsn: Lsn) -> Result<Vec<DurablePendingDelete>> {
        let lineage_state = self.lineage_state_lock.lock();
        let records = self.list_lineage_records(&lineage_state)?;
        let mut changes = Vec::new();
        for (_, record) in records {
            if record.table_generation != self.durable_lineage_table_generation(&record.table)?
                || record.delete_obligation != DurableDeleteObligation::Pending
                || record.delete_lsn <= since_lsn.0
            {
                continue;
            }
            changes.push(DurablePendingDelete {
                row: RowChange {
                    table: record.table,
                    natural_key: record.natural_key,
                    values: HashMap::from([("__deleted".to_string(), Value::Bool(true))]),
                    deleted: true,
                    lsn: Lsn(record.delete_lsn),
                    created_at: None,
                },
                local_row_id: record.local_row_id,
            });
        }
        Ok(changes)
    }

    pub(crate) fn has_durable_pending_delete_obligations(&self) -> Result<bool> {
        let lineage_state = self.lineage_state_lock.lock();
        Ok(self
            .list_lineage_records(&lineage_state)?
            .into_iter()
            .map(|(_, record)| {
                Ok(record.delete_obligation == DurableDeleteObligation::Pending
                    && record.table_generation
                        == self.durable_lineage_table_generation(&record.table)?)
            })
            .collect::<Result<Vec<_>>>()?
            .into_iter()
            .any(|pending| pending))
    }

    fn reconcile_durable_pending_deletes(
        mut changes: ChangeSet,
        pending: Vec<DurablePendingDelete>,
    ) -> ChangeSet {
        for pending in pending {
            let row = pending.row;
            let identity = sync_identity_key(&row.table, &row.natural_key);
            changes.rows.retain(|existing| {
                existing.deleted
                    || sync_identity_key(&existing.table, &existing.natural_key) != identity
                    || existing.lsn > row.lsn
            });
            if let Some(local_row_id) = pending.local_row_id {
                changes.vectors.retain(|vector| {
                    vector.index.table != row.table
                        || vector.row_id != local_row_id
                        || vector.vector.is_empty()
                        || vector.lsn > row.lsn
                });
            }
            if !changes.rows.iter().any(|existing| {
                existing.deleted
                    && existing.table == row.table
                    && existing.natural_key == row.natural_key
                    && existing.lsn == row.lsn
            }) {
                changes.rows.push(row);
            }
        }
        changes
    }

    fn append_durable_pending_delete_changes(
        &self,
        since_lsn: Lsn,
        changes: ChangeSet,
    ) -> ChangeSet {
        match self.durable_pending_deletes_since(since_lsn) {
            Ok(pending) => Self::reconcile_durable_pending_deletes(changes, pending),
            Err(_) => changes,
        }
    }

    sync_test_seam! {
    /// Add accepted delete ancestry that an explicit destination move selected.
    /// These records share the ordinary lineage lifecycle; this view makes
    /// already-held absence transportable to the new hub. Redb carries that
    /// state across restart, while memory carries it only for this database
    /// life.
    fn append_destination_reupload_deletes(
        &self,
        mut changes: ChangeSet,
        held_through_lsn: Lsn,
    ) -> Result<ChangeSet> {
        let lineage_state = self.lineage_state_lock.lock();
        let records = self.list_lineage_records(&lineage_state)?;
        for (_, record) in records {
            if record.delete_obligation != DurableDeleteObligation::Accepted
                || record.delete_lsn == 0
                || record.delete_lsn > held_through_lsn.0
                || record.table_generation
                    != self.durable_lineage_table_generation(&record.table)?
            {
                continue;
            }
            let row = RowChange {
                table: record.table,
                natural_key: record.natural_key,
                values: HashMap::from([("__deleted".to_string(), Value::Bool(true))]),
                deleted: true,
                lsn: Lsn(record.delete_lsn),
                created_at: None,
            };
            if !changes.rows.iter().any(|existing| {
                existing.deleted
                    && existing.table == row.table
                    && existing.natural_key == row.natural_key
                    && existing.lsn == row.lsn
            }) {
                changes.rows.push(row);
            }
        }
        Ok(changes)
    }
    }

    fn record_durable_delete_acceptance(
        &self,
        rows: &[RowChange],
        hub_lsn: Lsn,
        hub_node_id: Option<&str>,
    ) -> Result<()> {
        let mut lineage_state = self.lineage_state_lock.lock();
        for row in rows.iter().filter(|row| row.deleted) {
            let key = Self::durable_lineage_config_key(
                &row.table,
                &row.natural_key,
                self.durable_lineage_table_generation(&row.table)?,
            );
            let Some(mut record) = self.load_lineage_record(&lineage_state, &key)? else {
                continue;
            };
            if record.delete_lsn != row.lsn.0
                || record.delete_obligation != DurableDeleteObligation::Pending
            {
                continue;
            }
            record.delete_obligation = DurableDeleteObligation::Accepted;
            record.accepted_hub_lsn = Some(hub_lsn.0);
            record.bound_hub_node_id = hub_node_id.map(ToOwned::to_owned);
            self.store_lineage_record(&mut lineage_state, &key, &record)?;
        }
        Ok(())
    }

    pub(crate) fn retire_durable_delete_obligations(&self, rows: &[RowChange]) -> Result<()> {
        let mut lineage_state = self.lineage_state_lock.lock();
        for row in rows.iter().filter(|row| row.deleted) {
            let key = Self::durable_lineage_config_key(
                &row.table,
                &row.natural_key,
                self.durable_lineage_table_generation(&row.table)?,
            );
            let Some(record) = self.load_lineage_record(&lineage_state, &key)? else {
                continue;
            };
            if record.delete_lsn == row.lsn.0
                && record.delete_obligation == DurableDeleteObligation::Pending
            {
                self.remove_lineage_record(&mut lineage_state, &key)?;
            }
        }
        Ok(())
    }

    fn clear_sync_tombstone(&self, table: &str, natural_key: &NaturalKey) {
        self.sync_tombstone_arrivals
            .write()
            .remove(&Self::sync_tombstone_key(table, natural_key));
    }

    fn row_id_for_delete_change(&self, row: &RowChange) -> Option<RowId> {
        self.change_log.read().iter().rev().find_map(|entry| {
            let ChangeLogEntry::RowDelete {
                table,
                row_id,
                natural_key,
                lsn,
            } = entry
            else {
                return None;
            };
            (table == &row.table && natural_key == &row.natural_key && *lsn == row.lsn)
                .then_some(*row_id)
        })
    }

    /// A hub restored before an acknowledged local delete can replay its old
    /// live row. While this database is still open, the accepted-local delete
    /// records the hub order that made it obsolete; do not resurrect that row
    /// from an older ordered arrival. This intentionally does not reconstruct
    /// tombstones on restart (DL-CDB-31 owns that retention question).
    fn incoming_row_is_stale_against_sync_tombstone(
        &self,
        row: &RowChange,
        arrivals: &HashMap<Lsn, Option<Lsn>>,
        adoption: SyncAdoption,
    ) -> Result<bool> {
        // A cursor that just adopted a different source compares no prior
        // source ordering. Its authoritative from-zero history must be able
        // to restore a row even when this session still remembers a delete
        // accepted by the old source.
        if adoption != SyncAdoption::Continuing {
            return Ok(false);
        }
        let Some(incoming_arrival) = Self::resolve_incoming_arrival(row, arrivals) else {
            return Ok(false);
        };
        // Durable accepted deletes are intentionally NOT compared to a hub
        // arrival clock here.  Rebind/source-adoption safety is decided by
        // `drop_accepted_lineage_replays_against_generation_projection` before
        // apply, using the immutable root/creator tuple; clocks from a replaced
        // hub are incomparable and must never suppress a later genuine same-key
        // lineage.
        Ok(self
            .sync_tombstone_arrivals
            .read()
            .get(&Self::sync_tombstone_key(&row.table, &row.natural_key))
            .is_some_and(|marker| match marker.kind {
                // The hub may refuse a keep-first/server-wins delete and
                // re-emit its retained row in THAT SAME commit. That equal
                // arrival is authoritative repair, not a restored-hub replay.
                contextdb_relational::store::SyncSourceKind::AcceptedLocal => {
                    marker.accepted_local_order_invalidated || incoming_arrival < marker.arrival
                }
                contextdb_relational::store::SyncSourceKind::AcceptedLocalPending => true,
                // A pulled tombstone already describes the hub's own
                // authoritative delete; its equal-arrival echo remains stale.
                contextdb_relational::store::SyncSourceKind::Pulled => {
                    incoming_arrival <= marker.arrival
                }
            }))
    }

    sync_test_seam! {
    /// Persist the accepting hub's order after a push acknowledgement. The
    /// acknowledgement's existing `ApplyResult::new_lsn` is the hub commit
    /// position, so no wire field is needed. The commit lock makes the
    /// current-row comparison and the provenance write one ordering boundary:
    /// a later local write has a different row LSN and is never marked as if
    /// the hub had accepted it.
    fn record_hub_accepted_rows(
        &self,
        rows: &[RowChange],
        hub_lsn: Lsn,
        hub_node_id: Option<&str>,
    ) -> Result<()> {
        let _operation = self.assert_open_operation();
        self.with_commit_lock(|| {
            let snapshot = self.snapshot();
            let empty_skip_deleted = HashSet::new();
            let mut source_entries = Vec::new();
            let mut tombstones = Vec::new();
            for row in rows {
                if row.deleted {
                    let row_id = self.row_id_for_delete_change(row);
                    let current = self
                        .visible_row_by_natural_key(
                            &row.table,
                            &row.natural_key,
                            snapshot,
                            &empty_skip_deleted,
                        )?
                        .is_none();
                    if current {
                        tombstones.push((
                            Self::sync_tombstone_key(&row.table, &row.natural_key),
                            SyncTombstoneArrival {
                                arrival: hub_lsn,
                                delete_lsn: row.lsn,
                                row_id,
                                kind: contextdb_relational::store::SyncSourceKind::AcceptedLocal,
                                accepted_local_order_invalidated: false,
                            },
                        ));
                    }
                    continue;
                }
                let Some(local) = self.visible_row_by_natural_key(
                    &row.table,
                    &row.natural_key,
                    snapshot,
                    &empty_skip_deleted,
                )?
                else {
                    continue;
                };
                if local.lsn == row.lsn {
                    // Re-delivery after a hub restore has the same local
                    // source LSN but a NEW hub ordering position. Refresh an
                    // existing AcceptedLocal marker as well as creating one.
                    source_entries.push((row.table.clone(), local.row_id, hub_lsn));
                }
            }
            // A later same-key local INSERT must not hide the fact that this
            // exact earlier DELETE was acknowledged. Its row/tombstone sidecar
            // stays untouched, but the durable delete lifecycle still moves
            // Pending -> Accepted before the caller advances its watermark.
            self.record_durable_delete_acceptance(rows, hub_lsn, hub_node_id)?;
            if source_entries.is_empty() && tombstones.is_empty() {
                return Ok(());
            }
            if let Some(persistence) = &self.persistence {
                persistence.append_sync_source_provenance_batch(
                    &source_entries
                        .iter()
                        .map(|(table, row_id, lsn)| (table.clone(), *row_id, *lsn, 1))
                        .collect::<Vec<_>>(),
                )?;
            }
            if !source_entries.is_empty() {
                self.relational_store
                    .set_sync_source_lsns(source_entries.clone());
                self.relational_store
                    .set_sync_source_kinds(source_entries.into_iter().map(|(table, row_id, _)| {
                        (
                            table,
                            row_id,
                            contextdb_relational::store::SyncSourceKind::AcceptedLocal,
                        )
                    }));
            }
            if !tombstones.is_empty() {
                self.sync_tombstone_arrivals.write().extend(tombstones);
            }
            Ok(())
        })
    }
    }

    sync_test_seam! {
    #[cfg(any(test, feature = "test-seams"))]
    /// Apply every durable/in-memory semantic effect of one authenticated push
    /// reply only while that replying hub is still authoritative. Destination
    /// change holds the same peer lock over its reset and rebind, so a reply
    /// lands wholly before the move or is refused wholly after it: an old hub
    /// cannot mark rows accepted, retire delete obligations, or leave
    /// reconciliation markers in the new destination's state.
    fn record_hub_push_reply_effects_for_hub(
        &self,
        tenant_id: &TenantId,
        hub_node_id: &str,
        ordinary_refused_rows: &[RowChange],
        purge_refused_rows: &[RowChange],
        accepted_rows: &[RowChange],
        hub_lsn: Lsn,
    ) -> Result<()> {
        self.with_authoritative_hub_reply(hub_node_id, |db| {
            db.record_hub_push_reply_effects_while_authoritative(
                tenant_id,
                hub_node_id,
                ordinary_refused_rows,
                purge_refused_rows,
                accepted_rows,
                hub_lsn,
            )
        })
    }

    pub(crate) fn record_hub_push_reply_effects_while_authoritative(
        &self,
        tenant_id: &TenantId,
        hub_node_id: &str,
        ordinary_refused_rows: &[RowChange],
        purge_refused_rows: &[RowChange],
        accepted_rows: &[RowChange],
        hub_lsn: Lsn,
    ) -> Result<()> {
        if !ordinary_refused_rows.is_empty() {
            let context = TerminalRefusalPullContext {
                tenant_id: tenant_id.clone(),
                hub_node_id: hub_node_id.to_string(),
                generation: 0,
            };
            self.record_terminal_refusal_markers(&context, ordinary_refused_rows)?;
        }
        let refused_deletes = ordinary_refused_rows
            .iter()
            .chain(purge_refused_rows)
            .filter(|row| row.deleted)
            .cloned()
            .collect::<Vec<_>>();
        if !refused_deletes.is_empty() {
            self.retire_durable_delete_obligations(&refused_deletes)?;
        }
        if !accepted_rows.is_empty() {
            self.record_hub_accepted_rows(accepted_rows, hub_lsn, Some(hub_node_id))?;
        }
        Ok(())
    }

    /// Serialize every state change derived from one authenticated hub reply
    /// with an explicit destination move. Callers use the closure for their
    /// in-memory client state; database writers called from that closure must
    /// use their `_while_authoritative` form so they do not re-lock the peer.
    pub(crate) fn with_authoritative_hub_reply<T>(
        &self,
        hub_node_id: &str,
        effect: impl FnOnce(&Database) -> Result<T>,
    ) -> Result<T> {
        let _operation = self.open_operation()?;
        let established = self.retention_sync_peer.lock();
        self.ensure_authoritative_hub_locked(hub_node_id, &established)?;
        effect(self)
    }

    /// Apply one authenticated pull page while destination authority and table
    /// schema publication share the same lock order. The schema write gate must
    /// come before the public-operation and destination locks: taking the
    /// ordinary reply wrapper first would retain a schema read lease and then
    /// deadlock when received apply upgrades to the write side.
    pub(crate) fn with_authoritative_hub_received_apply<T>(
        &self,
        hub_node_id: &str,
        effect: impl FnOnce(&Database) -> Result<T>,
    ) -> Result<T> {
        let _schema_publication =
            self.enter_apply_changes_schema_publication_gate("sync pull apply")?;
        let _operation = self.open_operation_after_public_tx_control_wait("sync pull apply")?;
        let established = self.retention_sync_peer.lock();
        self.ensure_authoritative_hub_locked(hub_node_id, &established)?;
        effect(self)
    }

    fn ensure_authoritative_hub_locked(
        &self,
        hub_node_id: &str,
        established: &Option<String>,
    ) -> Result<()> {
        if established.as_deref() != Some(hub_node_id) {
            return Err(Error::SyncError(format!(
                "authenticated hub {hub_node_id} is no longer this edge's authoritative destination"
            )));
        }
        if let Some(persistence) = &self.persistence {
            let durable =
                persistence.load_config_value::<String>(RETENTION_SYNC_PEER_CONFIG_KEY)?;
            if durable.as_deref() != Some(hub_node_id) {
                return Err(Error::SyncError(format!(
                    "authenticated hub {hub_node_id} is no longer this edge's durable authoritative destination"
                )));
            }
        }
        Ok(())
    }
    }

